// A turn off a reflector, through the layer: 1-12 (level11)'s reflect_agent_761 at
// (180, 140), horizontal. A tap on the line from the player through it is caught
// by a position sample within 32 of it, under the wall that hangs to y 128, and the
// new leg - spawned AT the reflector, min(the length fired, the way from the player
// to it) long, the heading's y flipped (planning step 157, G9) - opens a portal.
// ETHCallback_reflect_agent's pictures: the old shot's flash where it was caught,
// the new leg's mark at its end (a clear ray, so portal_mark), and the new leg's
// own flash on its first tick, 24 out from the reflector along its way.
void AShotTurnedByAReflectorMarksItsNewEnd() {
    if (!OriginalArtIsThere("AShotTurnedByAReflectorMarksItsNewEnd")) return;
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level11");
    layer.OnAttach(registry);
    int ticks = 0;
    if (!ReadyToShoot(layer, registry, ticks)) return;
    const glm::dvec2 mirror(180.0, 140.0);
    const glm::dvec2 from = playerPx(registry, layer);
    const glm::dvec2 aim = from + (mirror - from) * 1.5;
    CHECK(onScreen(registry, aim));
    shoot(layer, registry, screenOf(registry, aim));
    CHECK_MSG(layer.SimLevel()->portals.flight.has_value(), "the tap fired: " + lastFailure(layer));
    if (!layer.SimLevel()->portals.flight) return;
    // The first leg: where it started (its casterPos) and where the tap-time ray ended it.
    const glm::dvec2 firstFrom = layer.SimLevel()->portals.flight->fromPx;
    const glm::dvec2 firstTo = layer.SimLevel()->portals.flight->toPx;
    layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    int turnTick = -1;
    MagicPortals::Portals::Reflection turn;
    std::vector<MagicPortalsLayer::EffectReport> seenFlashes; // the 350 ms flash is over by the turn
    for (int i = 0; i < 120 && layer.SimLevel()->portals.flight && turnTick < 0; ++i) {
        tickWith(layer, registry, kRest, {}, {});
        if (!layer.SimLevel()->portals.reflected.empty()) {
            turnTick = i;
            turn = layer.SimLevel()->portals.reflected.front();
        }
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
        NoteFlashes(layer, seenFlashes);
    }
    CHECK_MSG(turnTick >= 0, "the shot was turned: " + lastFailure(layer));
    if (turnTick < 0) return;
    // The new leg, worked out here from the listing and not read back from the sim (planning step 157): the first leg's
    // stored direction with its y flipped (a horizontal plane), for min(the length that leg was fired, the way from
    // where it began to the reflector), from the reflector. The first leg is aimed at the ray's end under the wall
    // (planning step 156); the new leg's own ray answers for the mark: red_cross where it is doomed (and red_waves (A)
    // where it met nothing and its end is in a field), portal_mark where it is clear. The first leg's own mark is a
    // red_cross at the tap.
    const glm::dvec2 aimedAt = (firstTo - firstFrom) / glm::distance(firstTo, firstFrom);
    const glm::dvec2 expectedDest =
        mirror + glm::dvec2(aimedAt.x, -aimedAt.y) *
                     std::min(glm::distance(firstTo, firstFrom), glm::distance(firstFrom, mirror));
    CHECK_MSG(turn.agentPx == mirror && glm::distance(turn.toPx, expectedDest) < 1e-6,
              "the new leg leaves reflect_agent_761 for " + Point(expectedDest) + ": " + Point(turn.toPx));
    CHECK_MSG(glm::distance(turn.atPx, mirror) < 32.0,
              "and the shot was caught within its size.x of 32: " + Point(turn.atPx));
    const char* markEntity = turn.said.willDie ? "red_cross.ent" : "portal_mark.ent";
    const auto marks = EffectsOf(layer, markEntity);
    int atNewEnd = 0;
    for (const auto& mark : marks) atNewEnd += (mark.atPx == turn.said.atPx && mark.zUnits == 32.0) ? 1 : 0;
    CHECK_MSG(atNewEnd == 1, std::string(markEntity) + " at the new leg's end, " + Point(turn.said.atPx) + ": " +
                                 std::to_string(atNewEnd) + " of " + std::to_string(marks.size()));
    const auto waves = EffectsOf(layer, "red_waves.ent");
    CHECK_MSG(waves.size() == (turn.said.redWaves ? 1u : 0u) &&
                  (waves.empty() || (waves[0].atPx == turn.toPx && waves[0].zUnits == 32.0)),
              "and red_waves (A) at the new destination exactly where its ray met nothing in a field: " +
                  std::to_string(waves.size()));
    auto flashes = seenFlashes;
    bool atTurn = false;
    for (const auto& flash : flashes) atTurn = atTurn || (flash.atPx == turn.atPx && flash.zUnits == 0.0);
    CHECK_MSG(flashes.size() == 2 && atTurn, "the first leg's flash and the old shot's where it turned, " +
                                                 Point(turn.atPx) + ": " + std::to_string(flashes.size()));
    // The new leg's own first tick.
    tickWith(layer, registry, kRest, {}, {});
    const bool launched = layer.SimLevel()->portals.launches.size() == 1 &&
                          layer.SimLevel()->portals.launches.front().fromPx == turn.agentPx;
    layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    CHECK_MSG(launched, "the new leg launches on the tick after its turn, from the reflector");
    NoteFlashes(layer, seenFlashes);
    flashes = seenFlashes;
    const glm::dvec2 way = glm::normalize(turn.said.atPx - turn.agentPx);
    bool out24 = false;
    for (const auto& flash : flashes) out24 = out24 || glm::distance(flash.atPx, turn.agentPx + way * 24.0) < 1e-4;
    CHECK_MSG(flashes.size() == 3 && out24,
              "and flashes 24 out from the reflector along its way: " + std::to_string(flashes.size()));
    landShot(layer, registry);
    std::printf("  1-12: a shot caught at %s by reflect_agent_761 and sent on from it, %s at %s, %zu portal(s) placed\n",
                Point(turn.atPx).c_str(), markEntity, Point(turn.said.atPx).c_str(),
                layer.SimLevel()->portals.placed.size());
    layer.OnDetach(registry);
}

// A tap with a fire diamond carried (3-32, level31b), through the layer: the
// method's own branch casts no ray, so the mark follows the leftover low byte of
// absTouchPos.x in the original's world pixels (Portals::State::FireDiamondWillDie),
// no red_waves; and the shot is converted before it ever flies, so no flash.
void AFireDiamondTapsMarkIsTheLeftoverByte() {
    if (!OriginalArtIsThere("AFireDiamondTapsMarkIsTheLeftoverByte")) return;
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level31b");
    layer.OnAttach(registry);
    int ticks = 0;
    if (!ReadyToShoot(layer, registry, ticks)) return;
    const MagicPortals::Diamonds::Diamond* fire = nullptr;
    for (const auto& diamond : layer.SimLevel()->diamonds.diamonds) {
        if (diamond.fire && fire == nullptr) fire = &diamond;
    }
    CHECK_MSG(fire != nullptr, "3-32 places a fire diamond");
    if (fire == nullptr) return;
    PutPlayerAt(registry, layer, fire->atPx);
    for (int i = 0; i < 5 && !layer.SimLevel()->diamonds.carrierHasFire; ++i) {
        tickWith(layer, registry, kRest, {}, {});
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    }
    CHECK_MSG(layer.SimLevel()->diamonds.carrierHasFire, "the fire diamond is carried");
    glm::dvec2 aim = playerPx(registry, layer) + glm::dvec2(60.0, -50.0);
    for (int i = 0; i < 60 && !onScreen(registry, aim); ++i) {
        tickWith(layer, registry, kRest, {}, {});
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
        aim = playerPx(registry, layer) + glm::dvec2(60.0, -50.0);
    }
    CHECK(onScreen(registry, aim));
    shoot(layer, registry, screenOf(registry, aim));
    CHECK_MSG(layer.SimLevel()->portals.lastTap.reason == MagicPortals::Portals::TapReason::Fired &&
                  layer.SimLevel()->portals.flight.has_value(),
              "the tap fired: " + lastFailure(layer));
    if (!layer.SimLevel()->portals.flight) return;
    const glm::dvec2 tapPx = layer.SimLevel()->portals.flight->toPx;
    const bool dies = MagicPortals::Portals::State::FireDiamondWillDie(tapPx.x * (720.0 / 256.0));
    layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    const auto crosses = EffectsOf(layer, "red_cross.ent");
    const auto marks = EffectsOf(layer, "portal_mark.ent");
    CHECK_MSG(static_cast<int>(crosses.size()) == (dies ? 1 : 0) && static_cast<int>(marks.size()) == (dies ? 0 : 1),
              std::string("the leftover byte says ") + (dies ? "red_cross" : "portal_mark") + " for x " +
                  std::to_string(tapPx.x) + ": " + std::to_string(crosses.size()) + " cross, " +
                  std::to_string(marks.size()) + " mark");
    CHECK(EffectsOf(layer, "red_waves.ent").empty());
    tickWith(layer, registry, kRest, {}, {});
    CHECK_MSG(!layer.SimLevel()->portals.flight && layer.SimLevel()->portals.launches.empty(),
              "the shot is a fireball before it ever flies: no leg, no flash");
    std::printf("  3-32 with the fire diamond: a tap at x %.4f u = %.4f px, low byte %s: %s\n", tapPx.x,
                tapPx.x * (720.0 / 256.0), dies ? "set" : "clear", dies ? "red_cross" : "portal_mark");
    layer.OnDetach(registry);
}

// ---- What a crystal leaves where it was (the visuals plan's 10.2, step 106) ----------
//
// pickCrystalEffect adds crystal_pick.ent where the character takes a crystal, and
// ETHCallback_timer adds crystal_vanish.ent, at 1.3, where a timed crystal's time
// runs out while it is still there: each at the crystal's GetPosition() plus
// vector3(0, 0, scale(20)), so on top of the crystal's own depth, and with no
// owner. 00_order 10.2's gate: "a taken crystal spawns exactly 5 + 2 particles at
// z + 20, freed at Finished". 1-27 (level26) carries both kinds: crystal_ent_1269
// at (80, 140), eth_z -4, in open air, and the timed crystal_1264 at (400, 208),
// eth_z 0, 10 s.

// The first live effect of that .ent, or an empty report; `count` says how many.
MagicPortalsLayer::EffectReport FirstEffect(const MagicPortalsLayer& layer, const std::string& entity, int& count) {
    MagicPortalsLayer::EffectReport found;
    count = 0;
    for (const MagicPortalsLayer::EffectReport& report : layer.EffectReports()) {
        if (report.entity != entity) continue;
        if (count++ == 0) found = report;
    }
    return found;
}

// Frames (no ticks) until the effect `id` is freed: on which frame it went, the
// most of its particles ever released, and how many effects went on the way.
struct Burnt {
    int freedOn = -1;
    int mostReleased = 0;
    int freed = 0;
};

Burnt BurnDown(MagicPortalsLayer& layer, entt::registry& registry, int id, int frames) {
    Burnt burnt;
    const int freedBefore = layer.EffectsFreed();
    for (int frame = 1; frame <= frames; ++frame) {
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
        const MagicPortalsLayer::EffectReport mine = ByIdIn(layer.EffectReports(), id);
        if (mine.id == 0) {
            burnt.freedOn = frame;
            break;
        }
        burnt.mostReleased = std::max(burnt.mostReleased, mine.released);
    }
    burnt.freed = layer.EffectsFreed() - freedBefore;
    return burnt;
}

void ATakenCrystalLeavesItsPickWhereItStood() {
    if (!OriginalArtIsThere("ATakenCrystalLeavesItsPickWhereItStood")) return;
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level26");
    layer.OnAttach(registry);
    CHECK_MSG(layer.SimLevel() != nullptr && layer.ArtError().empty(), layer.LoadError() + layer.ArtError());
    if (layer.SimLevel() == nullptr || !layer.ArtError().empty()) return;
    CloseTheLevelStartPopup(layer, registry);
    // Long enough for the bob to have moved it off its node.
    for (int tick = 0; tick < 40; ++tick) {
        tickWith(layer, registry, kRest, {}, {});
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    }
    const std::string name = "crystal_ent_1269";
    const glm::dvec2 node(80.0, 140.0);
    const std::optional<MagicPortalsLayer::MotionReport> before = MotionOf(layer, name);
    CHECK(before.has_value() && before->crystal && before->moving);
    if (!before) return;
    CHECK_MSG(glm::distance(before->ownerPx, node) > 0.01,
              "the bob has moved it off its node: " + Point(before->ownerPx));
    const int spawnedBefore = layer.EffectsSpawned();

    PutPlayerAt(registry, layer, before->ownerPx);
    const MagicPortals::Goals::Crystal* crystal = nullptr;
    glm::dvec2 lastDrawn = before->ownerPx;
    for (int ticks = 0; ticks < 5; ++ticks) {
        const std::optional<MagicPortalsLayer::MotionReport> now = MotionOf(layer, name);
        if (now) lastDrawn = now->ownerPx;
        tickWith(layer, registry, kRest, {}, {});
        crystal = layer.SimLevel()->goals.FindCrystal(name);
        if (crystal != nullptr && crystal->collected) break;
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    }
    CHECK_MSG(crystal != nullptr && crystal->collected, "the player takes " + name);
    if (crystal == nullptr || !crystal->collected) return;
    // THE TICK ONLY QUEUES IT: the frame adds it.
    int picks = 0;
    FirstEffect(layer, "crystal_pick.ent", picks);
    CHECK_MSG(layer.EffectsSpawned() == spawnedBefore && picks == 0, "nothing is added on the tick");
    const std::optional<MagicPortalsLayer::MotionReport> after = MotionOf(layer, name);
    CHECK_MSG(after && after->ownerPx == lastDrawn,
              "the crystal's entity point is where the last tick drew it: " + Point(lastDrawn));
    layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    CHECK_MSG(layer.EffectsSpawned() == spawnedBefore + 1,
              "one added on the frame: " + std::to_string(layer.EffectsSpawned() - spawnedBefore));
    const MagicPortalsLayer::EffectReport pick = FirstEffect(layer, "crystal_pick.ent", picks);
    int vanishes = 0;
    FirstEffect(layer, "crystal_vanish.ent", vanishes);
    CHECK_MSG(picks == 1 && vanishes == 0, "one crystal_pick and no crystal_vanish: " + std::to_string(picks) +
                                               " / " + std::to_string(vanishes));
    if (pick.id == 0) return;

    // WHERE: the crystal's own point, bob and all - not its node - and 20 in front
    // of ITS depth: -4 + 20 = 16, where a flat scale(20) would have said 20.
    CHECK_MSG(pick.atPx == lastDrawn && glm::distance(pick.atPx, node) > 0.01,
              "at the crystal's drawn entity point " + Point(lastDrawn) + ", not its node: " + Point(pick.atPx));
    CHECK_MSG(nearlyU(pick.zUnits, 16.0), "z -4 + 20 = 16: " + std::to_string(pick.zUnits));
    // WHAT: crystal_pick.ent as read - no sprite, no light, temporary; 5 sparkles and 2
    // crystals, at the script's own size.
    CHECK_MSG(!pick.drawn && !pick.hasLight && pick.temporary && pick.scriptScale == 1.0,
              "no picture, no light, temporary, at getScale()");
    CHECK_MSG(pick.systems == 2 && pick.pool == 5 + 2,
              "5 + 2 particles in 2 systems: " + std::to_string(pick.systems) + " systems, " +
                  std::to_string(pick.pool));
    CHECK_MSG(pick.systemSizePx.size() == 2 && nearlyU(pick.systemSizePx[0], 20.0) &&
                  nearlyU(pick.systemSizePx[1], 28.0),
              "sparkles at 20, the crystal at 28");
    // IN FRONT OF THE PLAYER, as F14 r1 #54-#57 show the original's crystal drawn over
    // the mage: 16 against the player's 4 / 2.8125.
    CHECK_MSG(pick.systemZ.size() == 2 && pick.systemZ[0] > layer.PlayerSlotZ() &&
                  pick.systemZ[1] > layer.PlayerSlotZ(),
              "both systems in front of the player");

    // FREED AT FINISHED, by its pools and nothing else: the fifth sparkle is released
    // past 4/5 of 350 + 150 ms (24 frames) and lives 200 to 500 ms (12 to 30 more),
    // the two crystals 400 ms from the first frame - so the pools are over no sooner
    // than frame 35 and no later than 54.
    const Burnt burnt = BurnDown(layer, registry, pick.id, 120);
    std::printf("  crystal_pick at %s z %.1f: %d of %d particles released, freed on frame %d\n",
                Point(pick.atPx).c_str(), pick.zUnits, burnt.mostReleased, pick.pool, burnt.freedOn);
    CHECK_MSG(burnt.mostReleased == 7, "all 7 released before it went: " + std::to_string(burnt.mostReleased));
    CHECK_MSG(burnt.freedOn >= 35 && burnt.freedOn <= 54,
              "freed when its pools are over, frame " + std::to_string(burnt.freedOn) + " (35..54)");
    CHECK_MSG(burnt.freed == 1, "exactly it freed: " + std::to_string(burnt.freed));

    // A TIMED CRYSTAL TAKEN BEFORE ITS TIME: crystal_pick, its dial shrinking away,
    // and no crystal_vanish - ETHCallback_timer finds it deleted and adds nothing -
    // even once its 10 s are long past.
    const std::string timed = "crystal_1264";
    const std::optional<MagicPortalsLayer::MotionReport> timedAt = MotionOf(layer, timed);
    CHECK(timedAt.has_value());
    if (!timedAt) return;
    PutPlayerAt(registry, layer, timedAt->ownerPx);
    int ticks = 0;
    int pickedTimed = 0;
    int vanished = 0;
    while (ticks < 660) {
        tickWith(layer, registry, kRest, {}, {});
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
        ++ticks;
        int count = 0;
        for (const MagicPortalsLayer::EffectReport& report : layer.EffectReports()) {
            if (report.entity == "crystal_pick.ent" && glm::distance(report.atPx, timedAt->ownerPx) < 1.0) ++count;
        }
        pickedTimed = std::max(pickedTimed, count);
        FirstEffect(layer, "crystal_vanish.ent", count);
        vanished += count;
    }
    const MagicPortals::Goals::Crystal* taken = layer.SimLevel()->goals.FindCrystal(timed);
    const std::optional<MagicPortalsLayer::TimerReport> dial = DialOf(layer, timed);
    std::printf("  %s taken early: %d crystal_pick at it, %d crystal_vanish in %d ticks\n", timed.c_str(),
                pickedTimed, vanished, ticks);
    CHECK_MSG(taken != nullptr && taken->collected && !taken->expired, timed + " taken early");
    CHECK_MSG(pickedTimed == 1 && vanished == 0,
              "one crystal_pick at it, and no crystal_vanish over " + std::to_string(ticks) + " ticks: " +
                  std::to_string(pickedTimed) + " / " + std::to_string(vanished));
    CHECK_MSG(dial && !dial->drawn, "its dial shrank away");
    layer.OnDetach(registry);
}

void ATimedCrystalGoesWithItsVanishAtItsTime() {
    if (!OriginalArtIsThere("ATimedCrystalGoesWithItsVanishAtItsTime")) return;
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level26");
    layer.OnAttach(registry);
    CHECK_MSG(layer.SimLevel() != nullptr && layer.ArtError().empty(), layer.LoadError() + layer.ArtError());
    if (layer.SimLevel() == nullptr || !layer.ArtError().empty()) return;
    const std::string name = "crystal_1264";
    glm::dvec2 lastDrawn(0.0);
    int tick = 0;
    int early = 0;
    const MagicPortals::Goals::Crystal* crystal = nullptr;
    int spawnedBefore = 0;
    while (tick < 700) {
        const std::optional<MagicPortalsLayer::MotionReport> now = MotionOf(layer, name);
        if (now) lastDrawn = now->ownerPx;
        spawnedBefore = layer.EffectsSpawned();
        tickWith(layer, registry, kRest, {}, {});
        ++tick;
        crystal = layer.SimLevel()->goals.FindCrystal(name);
        if (crystal == nullptr || crystal->expired || crystal->collected) break;
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
        int count = 0;
        FirstEffect(layer, "crystal_vanish.ent", count);
        early += count;
    }
    CHECK_MSG(crystal != nullptr && crystal->expired && tick == 626,
              name + " goes just after its time, on tick " + std::to_string(tick) + ", the 626th");
    CHECK_MSG(early == 0, "no burst before its time: " + std::to_string(early));
    if (crystal == nullptr || !crystal->expired) return;
    int vanishes = 0;
    FirstEffect(layer, "crystal_vanish.ent", vanishes);
    CHECK_MSG(layer.EffectsSpawned() == spawnedBefore && vanishes == 0, "nothing is added on the tick");
    layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    const MagicPortalsLayer::EffectReport gone = FirstEffect(layer, "crystal_vanish.ent", vanishes);
    int picks = 0;
    FirstEffect(layer, "crystal_pick.ent", picks);
    CHECK_MSG(vanishes == 1 && picks == 0 && layer.EffectsSpawned() == spawnedBefore + 1,
              "one crystal_vanish and no crystal_pick on the frame: " + std::to_string(vanishes) + " / " +
                  std::to_string(picks));
    if (gone.id == 0) return;
    CHECK_MSG(gone.atPx == lastDrawn && glm::distance(gone.atPx, glm::dvec2(400.0, 208.0)) > 0.01,
              "at the crystal's last drawn entity point " + Point(lastDrawn) + ", bob and all: " + Point(gone.atPx));
    CHECK_MSG(nearlyU(gone.zUnits, 20.0), "its eth_z 0 + 20: " + std::to_string(gone.zUnits));
    // AT scale(1.3): the script's Scale, which the .ent's <Scale> 1 leaves as it is and
    // every particle takes - the explosion's 22 and the crystal's 28 drawn at 28.6 and
    // 36.4. One explosion cell and two crystals, all at once.
    CHECK_MSG(gone.scriptScale == 1.3 && nearlyU(gone.scale.x, 1.3), "at 1.3: " + std::to_string(gone.scale.x));
    CHECK_MSG(gone.systems == 2 && gone.pool == 1 + 2, "1 + 2 particles: " + std::to_string(gone.pool));
    CHECK_MSG(gone.systemSizePx.size() == 2 && nearlyU(gone.systemSizePx[0], 22.0 * 1.3) &&
                  nearlyU(gone.systemSizePx[1], 28.0 * 1.3),
              "28.6 and 36.4");
    CHECK_MSG(!gone.drawn && !gone.hasLight && gone.temporary, "no picture, no light, temporary");
    CHECK_MSG(gone.systemZ.size() == 2 && gone.systemZ[0] > layer.PlayerSlotZ() &&
                  gone.systemZ[1] > layer.PlayerSlotZ(),
              "in front of the player");
    // Both systems all at once, 350 and 400 ms from the frame it was added: the
    // crystals' 400 are over on the 25th frame after it, give or take a rounding.
    const Burnt burnt = BurnDown(layer, registry, gone.id, 120);
    std::printf("  crystal_vanish at %s z %.1f x %.1f: freed on frame %d\n", Point(gone.atPx).c_str(), gone.zUnits,
                gone.scriptScale, burnt.freedOn);
    CHECK_MSG(burnt.mostReleased == 3 && burnt.freedOn >= 24 && burnt.freedOn <= 27 && burnt.freed == 1,
              "all 3 released, freed on frame " + std::to_string(burnt.freedOn) + " (24..27)");
    layer.OnDetach(registry);
}

// ---- what a key and its keyhole leave (the visuals plan's 10.3) ---------------------

// THE STEP'S GATE: a key taken on 3-18 (level17b) leaves key_pick at the key, 32 in
// front of it. minion_spawn A stands on the level's one key, so a MINION takes it as
// the level starts - ETHCallback_key's free branch admits isMinion as it admits the
// character, and adds key_pick either way.
void AKeyTakenOn318LeavesItsPickAtTheKey() {
    if (!OriginalArtIsThere("AKeyTakenOn318LeavesItsPickAtTheKey")) return;
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level17b");
    layer.OnAttach(registry);
    CHECK_MSG(layer.SimLevel() != nullptr && layer.ArtError().empty(), layer.LoadError() + layer.ArtError());
    if (layer.SimLevel() == nullptr || !layer.ArtError().empty()) return;
    CloseTheLevelStartPopup(layer, registry);
    const std::string name = "key_ent_2103";
    const glm::dvec2 node(224.0, 368.0);
    const MagicPortals::Keys::Key* key = layer.SimLevel()->keys.FindKey(name);
    CHECK_MSG(key != nullptr && key->owner == entt::null, name + " lies unowned before the first tick");
    if (key == nullptr) return;
    const int spawnedBefore = layer.EffectsSpawned();
    glm::dvec2 lastDrawn(0.0);
    int tick = 0;
    while (tick < 60) {
        if (const std::optional<MagicPortalsLayer::MotionReport> now = MotionOf(layer, name)) lastDrawn = now->ownerPx;
        tickWith(layer, registry, kRest, {}, {});
        ++tick;
        key = layer.SimLevel()->keys.FindKey(name);
        if (key != nullptr && key->owner != entt::null) break;
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    }
    CHECK_MSG(key != nullptr && key->owner != entt::null && key->owner != layer.SimLevel()->player,
              "a minion takes it, on tick " + std::to_string(tick));
    if (key == nullptr || key->owner == entt::null) return;
    int picks = 0;
    FirstEffect(layer, "key_pick.ent", picks);
    CHECK_MSG(layer.EffectsSpawned() == spawnedBefore && picks == 0, "nothing is added on the tick");
    layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    const MagicPortalsLayer::EffectReport pick = FirstEffect(layer, "key_pick.ent", picks);
    CHECK_MSG(picks == 1 && layer.EffectsSpawned() == spawnedBefore + 1,
              "one key_pick on the frame: " + std::to_string(picks));
    if (pick.id == 0) return;
    // AT THE KEY: its entity point as the last tick drew it, and 32 in front of its
    // eth_z of 0.
    CHECK_MSG(pick.atPx == lastDrawn && glm::distance(pick.atPx, node) < 2.0,
              "at the key's drawn point " + Point(lastDrawn) + ", by its node: " + Point(pick.atPx));
    CHECK_MSG(nearlyU(pick.zUnits, 32.0), "the key's 0 + 32: " + std::to_string(pick.zUnits));
    // key_pick.ent as read: no sprite or light, temporary; 8 sparkles over a life and
    // one growing from 3, at the script's own size.
    CHECK_MSG(!pick.drawn && !pick.hasLight && pick.temporary && pick.scriptScale == 1.0,
              "no picture, no light, temporary, at getScale()");
    CHECK_MSG(pick.systems == 2 && pick.pool == 8 + 1 && pick.systemSizePx.size() == 2 &&
                  nearlyU(pick.systemSizePx[0], 12.0) && nearlyU(pick.systemSizePx[1], 3.0),
              "8 + 1 sparkles at 12 and 3: " + std::to_string(pick.pool));
    CHECK_MSG(pick.systemZ.size() == 2 && pick.systemZ[0] > layer.PlayerSlotZ() &&
                  pick.systemZ[1] > layer.PlayerSlotZ(),
              "both systems in front of the player");
    // FREED BY ITS POOLS: the eighth sparkle released at 7/8 of 300 + 100 ms and living
    // 200 to 400 more, the growing one 500 ms from the first frame.
    const Burnt burnt = BurnDown(layer, registry, pick.id, 120);
    std::printf("  3-18: %s taken on tick %d by a minion: key_pick at %s z %.1f, %d of %d released, freed on frame "
                "%d\n",
                name.c_str(), tick, Point(pick.atPx).c_str(), pick.zUnits, burnt.mostReleased, pick.pool,
                burnt.freedOn);
    CHECK_MSG(burnt.mostReleased == 9 && burnt.freedOn >= 30 && burnt.freedOn <= 50 && burnt.freed == 1,
              "all 9 released, freed on frame " + std::to_string(burnt.freedOn) + " (30..50)");
    layer.OnDetach(registry);
}

// The whole of it on 3-09 (level8b), whose five depths all differ: the player takes
// key_ent_1335 (eth_z -6) and carries it to keyhole_1338 (-14), whose door is
// door_locked_ent_1343 (-8). key_pick at the key, 26; the halo at the keyhole on the
// fly-in's frame 1, 41 ticks after the unlock, at a z of its own, 32; and on the tick
// the keyhole goes, with the door's shake, the three the keyhole adds in its order:
// wall_destroy at the door (-8), door_locked_vanish 2 raw units in front of it
// (-8 + 0.711) and keyhole_vanish 32 in front of the keyhole (18).
void AKeyAndItsKeyholeLeaveWhatTheScriptAdds() {
    if (!OriginalArtIsThere("AKeyAndItsKeyholeLeaveWhatTheScriptAdds")) return;
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level8b");
    layer.OnAttach(registry);
    CHECK_MSG(layer.SimLevel() != nullptr && layer.ArtError().empty(), layer.LoadError() + layer.ArtError());
    if (layer.SimLevel() == nullptr || !layer.ArtError().empty()) return;
    CloseTheLevelStartPopup(layer, registry);
    for (int tick = 0; tick < 10; ++tick) {
        tickWith(layer, registry, kRest, {}, {});
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    }
    const std::string keyName = "key_ent_1335";
    const std::string holeName = "keyhole_1338";
    const glm::dvec2 holeAt(582.0, 198.0);
    const glm::dvec2 doorAt(624.0, 160.0);
    constexpr double kBare = 2.0 / (720.0 / 256.0);
    const MagicPortals::Keys::Key* key = layer.SimLevel()->keys.FindKey(keyName);
    const MagicPortals::Keys::Keyhole* hole = layer.SimLevel()->keys.FindKeyhole(holeName);
    CHECK(key != nullptr && hole != nullptr);
    if (key == nullptr || hole == nullptr) return;
    CHECK_MSG(key->owner == entt::null && hole->doorName == "door_locked_ent_1343" && hole->atPx == holeAt,
              "the key lies unowned, and the keyhole opens door_locked_ent_1343");
    int count = 0;
    FirstEffect(layer, "key_pick.ent", count);
    CHECK_MSG(count == 0, "no key_pick while the key lies");

    // TAKEN, by the player, at the key's drawn point.
    const std::optional<MagicPortalsLayer::MotionReport> lying = MotionOf(layer, keyName);
    CHECK(lying.has_value() && !lying->crystal);
    if (!lying) return;
    PutPlayerAt(registry, layer, lying->ownerPx);
    glm::dvec2 lastDrawn = lying->ownerPx;
    int spawnedBefore = layer.EffectsSpawned();
    for (int tick = 0; tick < 5; ++tick) {
        if (const std::optional<MagicPortalsLayer::MotionReport> now = MotionOf(layer, keyName)) {
            lastDrawn = now->ownerPx;
        }
        tickWith(layer, registry, kRest, {}, {});
        key = layer.SimLevel()->keys.FindKey(keyName);
        if (key != nullptr && key->owner != entt::null) break;
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    }
    CHECK_MSG(key != nullptr && key->owner == layer.SimLevel()->player, "the player takes " + keyName);
    if (key == nullptr || key->owner == entt::null) return;
    // Its sound on that tick, ETHCallback_key #805 (planning step 142).
    const auto heard = [&layer](const char* event) {
        const std::vector<std::string> sounds = layer.LatchedSounds();
        return static_cast<int>(std::count(sounds.begin(), sounds.end(), std::string(event)));
    };
    CHECK_MSG(heard("key_picked") == 1, "playKeyPickSound latched on the pick's tick");
    FirstEffect(layer, "key_pick.ent", count);
    CHECK_MSG(layer.EffectsSpawned() == spawnedBefore && count == 0, "nothing is added on the pick's tick");
    layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    const MagicPortalsLayer::EffectReport pick = FirstEffect(layer, "key_pick.ent", count);
    CHECK_MSG(count == 1 && pick.atPx == lastDrawn && nearlyU(pick.zUnits, 26.0),
              "one key_pick at the key's drawn point " + Point(lastDrawn) + ", -6 + 32 = 26: " + Point(pick.atPx) +
                  " z " + std::to_string(pick.zUnits));

    // THE UNLOCK: carried onto the keyhole. No second pick while it is carried.
    int strayPicks = 0;
    int carried = 0;
    while (carried < 300) {
        PutPlayerAt(registry, layer, holeAt);
        tickWith(layer, registry, kRest, {}, {});
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
        ++carried;
        for (const MagicPortalsLayer::EffectReport& report : layer.EffectReports()) {
            if (report.entity == "key_pick.ent" && report.id != pick.id) ++strayPicks;
        }
        key = layer.SimLevel()->keys.FindKey(keyName);
        if (key != nullptr && key->spent) break;
    }
    CHECK_MSG(key != nullptr && key->spent && key->opened >= 0 &&
                  layer.SimLevel()->keys.keyholes[static_cast<std::size_t>(key->opened)].name == holeName,
              "the key opens " + holeName + " after " + std::to_string(carried) + " ticks");
    CHECK_MSG(strayPicks == 0, "no second key_pick while carried: " + std::to_string(strayPicks));
    if (key == nullptr || !key->spent) return;

    // THE HALO, on the fly-in's frame 1: the 43rd tick after the unlock at 16 ms (the 41st at 16.667).
    // And the two sounds of the fly-in (planning step 142): playDoorUnlockSound
    // as the next tick builds its WaypointManager (#221-550), playKeyUnlockSound
    // with the halo (#593-635).
    int haloAfter = -1;
    int unlockHeard = -1;
    int keyUnlockHeard = -1;
    MagicPortalsLayer::EffectReport halo;
    for (int n = 1; n <= 80 && haloAfter < 0; ++n) {
        tickWith(layer, registry, kRest, {}, {});
        if (heard("door_unlocked") > 0 && unlockHeard < 0) unlockHeard = n;
        if (heard("key_unlocked") > 0 && keyUnlockHeard < 0) keyUnlockHeard = n;
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
        halo = FirstEffect(layer, "key_unlock_halo.ent", count);
        if (count > 0) haloAfter = n;
    }
    CHECK_MSG(haloAfter == 43 && count == 1, "one halo, on the 43rd tick after the unlock: " + std::to_string(haloAfter));
    CHECK_MSG(unlockHeard == 1, "playDoorUnlockSound on the tick after the unlock: " + std::to_string(unlockHeard));
    CHECK_MSG(keyUnlockHeard == haloAfter,
              "playKeyUnlockSound on the halo's tick: " + std::to_string(keyUnlockHeard));
    CHECK_MSG(halo.atPx == holeAt && nearlyU(halo.zUnits, 32.0),
              "at the keyhole, z 32 of its own (not -14 + 32): " + Point(halo.atPx) + " z " +
                  std::to_string(halo.zUnits));
    CHECK_MSG(!halo.drawn && !halo.hasLight && halo.temporary && halo.systems == 1 && halo.pool == 1 &&
                  halo.systemSizePx.size() == 1 && nearlyU(halo.systemSizePx[0], 3.0) &&
                  halo.systemZ[0] > layer.PlayerSlotZ(),
              "one sparkle growing from 3, temporary, in front of the player");

    // THE KEYHOLE GOES: on that tick nothing is added and the door's 20 shakes; on
    // the frame the three come, in the script's order.
    int goneAfter = -1;
    for (int n = 1; n <= 200; ++n) {
        spawnedBefore = layer.EffectsSpawned();
        tickWith(layer, registry, kRest, {}, {});
        hole = layer.SimLevel()->keys.FindKeyhole(holeName);
        if (hole != nullptr && hole->gone) {
            goneAfter = haloAfter + n;
            break;
        }
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    }
    CHECK_MSG(goneAfter > 0, "the keyhole goes");
    if (goneAfter < 0) return;
    CHECK_MSG(heard("keyhole_vanished") == 1, "playDemolitionSound on the keyhole's tick (#235)");
    CHECK_MSG(layer.EffectsSpawned() == spawnedBefore, "nothing is added on the keyhole's tick");
    CHECK_MSG(std::fabs(layer.Quake().amplitudePx - quakeRowPx(20.0)) < 1e-9,
              "door_unlocked's 20 on the same tick: " + std::to_string(layer.Quake().amplitudePx) + " px");
    layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    CHECK_MSG(layer.EffectsSpawned() == spawnedBefore + 3,
              "three on the frame: " + std::to_string(layer.EffectsSpawned() - spawnedBefore));
    int dusts = 0;
    int sparkleSets = 0;
    int bursts = 0;
    const MagicPortalsLayer::EffectReport dust = FirstEffect(layer, "wall_destroy.ent", dusts);
    const MagicPortalsLayer::EffectReport sparkles = FirstEffect(layer, "door_locked_vanish.ent", sparkleSets);
    const MagicPortalsLayer::EffectReport burst = FirstEffect(layer, "keyhole_vanish.ent", bursts);
    CHECK_MSG(dusts == 1 && sparkleSets == 1 && bursts == 1, "one of each");
    if (dust.id == 0 || sparkles.id == 0 || burst.id == 0) return;
    CHECK_MSG(dust.id < sparkles.id && sparkles.id < burst.id,
              "added in ETHCallback_keyhole's order: wall_destroy, door_locked_vanish, keyhole_vanish");
    // wall_destroy: at the door's own point and depth, dirt and smoke, both systems
    // at their StartPoint's 32 in front of it.
    CHECK_MSG(dust.atPx == doorAt && nearlyU(dust.zUnits, -8.0) && !dust.drawn && !dust.hasLight &&
                  dust.temporary && dust.systems == 2 && dust.pool == 22 + 10 && dust.systemSizePx.size() == 2 &&
                  nearlyU(dust.systemSizePx[0], 19.0) && nearlyU(dust.systemSizePx[1], 60.0),
              "wall_destroy at the door " + Point(dust.atPx) + " z " + std::to_string(dust.zUnits) + ", 22 + 10");
    CHECK_MSG(dust.systemZ.size() == 2 && dust.systemZ[0] > layer.PlayerSlotZ() &&
                  dust.systemZ[1] > layer.PlayerSlotZ(),
              "its dirt and smoke in front of the player (-8 + 32)");
    // door_locked_vanish: at the door, 0.711 in front of its -8 - behind the player.
    CHECK_MSG(sparkles.atPx == doorAt && nearlyU(sparkles.zUnits, -8.0 + kBare) && sparkles.systems == 1 &&
                  sparkles.pool == 30 && sparkles.systemSizePx.size() == 1 &&
                  nearlyU(sparkles.systemSizePx[0], 9.0) && sparkles.systemZ[0] < layer.PlayerSlotZ(),
              "door_locked_vanish at the door, z " + std::to_string(sparkles.zUnits) + ", 30 sparkles");
    // keyhole_vanish: at the keyhole, -14 + 32 = 18, in front of the player.
    CHECK_MSG(burst.atPx == holeAt && nearlyU(burst.zUnits, 18.0) && burst.systems == 1 && burst.pool == 1 &&
                  burst.systemSizePx.size() == 1 && nearlyU(burst.systemSizePx[0], 74.0) &&
                  burst.systemZ[0] > layer.PlayerSlotZ(),
              "keyhole_vanish at the keyhole, z " + std::to_string(burst.zUnits));

    // EACH FREED BY ITS POOLS, frames only.
    int dustFreed = -1;
    int sparklesFreed = -1;
    int burstFreed = -1;
    for (int frame = 1; frame <= 150 && (dustFreed < 0 || sparklesFreed < 0 || burstFreed < 0); ++frame) {
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
        const std::vector<MagicPortalsLayer::EffectReport> reports = layer.EffectReports();
        if (dustFreed < 0 && ByIdIn(reports, dust.id).id == 0) dustFreed = frame;
        if (sparklesFreed < 0 && ByIdIn(reports, sparkles.id).id == 0) sparklesFreed = frame;
        if (burstFreed < 0 && ByIdIn(reports, burst.id).id == 0) burstFreed = frame;
    }
    std::printf("  3-09: key_pick z %.3f; unlocked after %d carried ticks, the halo %d ticks later at z %.3f; the "
                "keyhole gone %d ticks after the unlock: wall_destroy z %.3f (freed frame %d), door_locked_vanish z "
                "%.4f (%d), keyhole_vanish z %.3f (%d)\n",
                pick.zUnits, carried, haloAfter, halo.zUnits, goneAfter, dust.zUnits, dustFreed, sparkles.zUnits,
                sparklesFreed, burst.zUnits, burstFreed);
    CHECK_MSG(goneAfter >= 93 && goneAfter <= 94, "the keyhole's 1500 ms: " + std::to_string(goneAfter));
    CHECK_MSG(dustFreed >= 66 && dustFreed <= 110, "wall_destroy's 1100-1800 ms: " + std::to_string(dustFreed));
    CHECK_MSG(sparklesFreed >= 50 && sparklesFreed <= 68,
              "door_locked_vanish's last sparkle out by 531 + 350-550 ms: " + std::to_string(sparklesFreed));
    CHECK_MSG(burstFreed >= 41 && burstFreed <= 45, "keyhole_vanish's 700 ms: " + std::to_string(burstFreed));
    layer.OnDetach(registry);
}

// ---- what a diamond, a shock ring and a fire signal leave (the visuals plan's 10.4) --

// A bare 10, as the engine's world units are to the level's at the 720 px screen of R12.
constexpr double kBareTen = 10.0 / (720.0 / 256.0);

// shock_strike.png, 512 x 128 texels at density 1, cut 5 x 2 AS THE ORIGINAL CUTS IT:
// SetupSpriteRects strides it in whole units, 102 x 64 (Sprite.cpp:119-130), so each
// of its quads samples 102 / 512 of the texture across, not a flipbook's fifth, and
// starts at a whole number of those strides. Counts the quads it read.
int CheckShockCut(entt::registry& registry, const MagicPortalsLayer::EffectReport& effect, const std::string& what) {
    int read = 0;
    for (const entt::entity quad : effect.particleQuads) {
        if (!registry.valid(quad)) continue;
        const auto& material = registry.get<MaterialComponent>(quad);
        if (!EndsWith(material.albedoTexturePath, "/shock_strike.png")) continue;
        ++read;
        const float column = material.uvOffset.x / 0.19921875f;
        const float row = material.uvOffset.y / 0.5f;
        const bool whole = std::fabs(column - std::round(column)) < 1e-5f && column >= 0.0f && column <= 4.0f &&
                           std::fabs(row - std::round(row)) < 1e-5f && row >= 0.0f && row <= 1.0f;
        CHECK_MSG(material.uvScale == glm::vec2(0.19921875f, 0.5f) && whole &&
                      !registry.all_of<SpriteAnimationComponent>(quad),
                  what + ": a shock_strike cell of 102 / 512 x 64 / 128 at a whole stride, not a flipbook's: scale (" +
                      std::to_string(material.uvScale.x) + ", " + std::to_string(material.uvScale.y) + ") offset (" +
                      std::to_string(material.uvOffset.x) + ", " + std::to_string(material.uvOffset.y) + ")");
    }
    return read;
}

// THE SHOCK DIAMOND, on 3-16 (level15b): shock_diamond_ent_1741 at (204, 124), eth_z 0,
// taken by the player - shock_diamond_pick at the diamond, on its own depth - and on a
// later tick, carried, striking the level's first minion put 8 px from it:
// shock_death at the MINION's entity point (its body's centre less
// EntityAboveCentrePx) on its depth of 2 / 2.8125, then shock_strike at the midpoint of
// the two, z and all, turned by getAngle(normalize(enemy - diamond)) - radians,
// handed over as degrees.
void AShockDiamondLeavesItsPickItsDeathAndItsStrike() {
    if (!OriginalArtIsThere("AShockDiamondLeavesItsPickItsDeathAndItsStrike")) return;
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level15b");
    layer.OnAttach(registry);
    CHECK_MSG(layer.SimLevel() != nullptr && layer.ArtError().empty(), layer.LoadError() + layer.ArtError());
    if (layer.SimLevel() == nullptr || !layer.ArtError().empty()) return;
    CloseTheLevelStartPopup(layer, registry);
    for (int tick = 0; tick < 2; ++tick) {
        tickWith(layer, registry, kRest, {}, {});
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    }
    const std::string name = "shock_diamond_ent_1741";
    const MagicPortals::Diamonds::Diamond* diamond = layer.SimLevel()->diamonds.Find(name);
    CHECK(diamond != nullptr && !layer.SimLevel()->minions.minions.empty());
    if (diamond == nullptr || layer.SimLevel()->minions.minions.empty()) return;
    const glm::dvec2 lyingAt = diamond->atPx;
    CHECK_MSG(lyingAt == glm::dvec2(204.0, 124.0), "it lies at its node: " + Point(lyingAt));

    // TAKEN.
    int spawnedBefore = layer.EffectsSpawned();
    for (int tick = 0; tick < 5; ++tick) {
        PutPlayerAt(registry, layer, lyingAt);
        tickWith(layer, registry, kRest, {}, {});
        diamond = layer.SimLevel()->diamonds.Find(name);
        if (diamond != nullptr && diamond->owner != entt::null) break;
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    }
    CHECK_MSG(diamond != nullptr && diamond->owner == layer.SimLevel()->player, "the player takes it");
    // DRAWN WHOLE ON THE TICK IT IS TAKEN (art.json carried_diamond, planning step 146):
    // the pick is the free arm's update; the carried arm's SetAlpha(0.1f) is the next's.
    CHECK_MSG(layer.DrawnPicture(name).alpha == 1.0f, "whole on the tick it is taken");
    // Its sound on the tick (ETHCallback_shock_diamond #180; planning step 142).
    const auto heard = [&layer](const char* event) {
        const std::vector<std::string> sounds = layer.LatchedSounds();
        return static_cast<int>(std::count(sounds.begin(), sounds.end(), std::string(event)));
    };
    CHECK_MSG(heard("shock_picked") == 1 && heard("burned") == 0, "playShockDiamondPickSound, and no burn");
    int count = 0;
    FirstEffect(layer, "shock_diamond_pick.ent", count);
    CHECK_MSG(layer.EffectsSpawned() == spawnedBefore && count == 0, "nothing is added on the tick");
    layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    const MagicPortalsLayer::EffectReport pick = FirstEffect(layer, "shock_diamond_pick.ent", count);
    CHECK_MSG(count == 1 && layer.EffectsSpawned() == spawnedBefore + 1,
              "one shock_diamond_pick on the frame: " + std::to_string(count));
    if (pick.id == 0) return;
    CHECK_MSG(pick.atPx == lyingAt && nearlyU(pick.zUnits, 0.0) && pick.angleDeg == 0.0f,
              "at the diamond, on its own depth, unturned: " + Point(pick.atPx) + " z " + std::to_string(pick.zUnits));
    CHECK_MSG(!pick.drawn && !pick.hasLight && pick.temporary && pick.scriptScale == 1.0 && pick.systems == 2 &&
                  pick.pool == 4 + 1 && pick.systemSizePx.size() == 2 && nearlyU(pick.systemSizePx[0], 30.0) &&
                  nearlyU(pick.systemSizePx[1], 3.0),
              "4 shock cells at 30 all at once and a sparkle from 3: " + std::to_string(pick.pool));
    const int pickCells = CheckShockCut(registry, pick, "shock_diamond_pick");
    CHECK_MSG(pickCells == 4, "its four cells drawn on the frame it is added: " + std::to_string(pickCells));
    const Burnt pickBurnt = BurnDown(layer, registry, pick.id, 120);
    CHECK_MSG(pickBurnt.mostReleased == 5 && pickBurnt.freedOn >= 20 && pickBurnt.freedOn <= 50,
              "all 5 released, freed on frame " + std::to_string(pickBurnt.freedOn) + " (550 +- 250 ms)");

    // CARRIED: the next tick runs the carried arm, and the diamond is drawn at 0.1 -
    // its sprite alone; its lightning is a particle system, which SetAlpha does not reach.
    PutPlayerAt(registry, layer, lyingAt);
    tickWith(layer, registry, kRest, {}, {});
    layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    {
        const MagicPortalsLayer::DrawnPictureReport carried = layer.DrawnPicture(name);
        CHECK_MSG(carried.drawn && std::fabs(carried.alpha - 0.1f) < 1e-6f &&
                      std::fabs(registry.get<MaterialComponent>(carried.quad).albedoColor.a - 0.1f) < 1e-6f,
                  "carried, at SetAlpha(0.1): " + std::to_string(carried.alpha));
    }

    // STRUCK, on a later tick, carried.
    const entt::entity minion = layer.SimLevel()->minions.minions[0].body;
    const double above = layer.SimLevel()->minions.rules.EntityAboveCentrePx();
    spawnedBefore = layer.EffectsSpawned();
    int struck = 0;
    for (int tick = 0; tick < 5 && registry.valid(minion); ++tick) {
        PutPlayerAt(registry, layer, lyingAt);
        auto& at = registry.get<TransformComponent>(minion);
        const glm::vec3 world = MagicPortals::Units::ToWorld(lyingAt.x + 8.0, lyingAt.y);
        at.position = glm::vec3(world.x, world.y, at.position.z);
        tickWith(layer, registry, kRest, {}, {});
        struck = layer.SimLevel()->diamonds.struck;
        if (struck > 0) break;
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    }
    CHECK_MSG(struck == 1 && layer.SimLevel()->diamonds.strikes.size() == static_cast<std::size_t>(1),
              "the minion is struck, and the tick records it");
    CHECK_MSG(heard("shock_struck") == 1, "playShockStrikeSound on the strike's tick (#447)");
    if (layer.SimLevel()->diamonds.strikes.empty()) return;
    const MagicPortals::Diamonds::Strike strike = layer.SimLevel()->diamonds.strikes[0];
    CHECK_MSG(EffectsOf(layer, "shock_death.ent").empty() && EffectsOf(layer, "shock_strike.ent").empty(),
              "nothing is added on the tick");
    layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    int deaths = 0;
    int bolts = 0;
    const MagicPortalsLayer::EffectReport death = FirstEffect(layer, "shock_death.ent", deaths);
    const MagicPortalsLayer::EffectReport bolt = FirstEffect(layer, "shock_strike.ent", bolts);
    // And the minion's own callback, finding itself destroyed, adds blood.ent at its
    // point (ETHCallback_minion #1478-1504; the level's end and a death, step 96): three
    // on the frame since the merge of the two tracks (planning step 112), the blood last.
    int bloods = 0;
    const MagicPortalsLayer::EffectReport blood = FirstEffect(layer, "blood.ent", bloods);
    CHECK_MSG(deaths == 1 && bolts == 1 && bloods == 1 && layer.EffectsSpawned() == spawnedBefore + 3,
              "one shock_death, one shock_strike and the minion's blood on the frame: " + std::to_string(deaths) +
                  " / " + std::to_string(bolts) + " / " + std::to_string(bloods));
    if (death.id == 0 || bolt.id == 0) return;
    CHECK_MSG(death.id < bolt.id && bolt.id < blood.id,
              "in the script's order: the death, the strike, then the minion's blood");
    // AT THE MINION: its entity point, 11.1 over its body's centre, on its 0.711.
    const glm::dvec2 enemyPx = strike.preyCentrePx - glm::dvec2(0.0, above);
    constexpr double kMinionZ = 2.0 / (720.0 / 256.0);
    CHECK_MSG(death.atPx == enemyPx && nearlyU(death.zUnits, kMinionZ) && death.angleDeg == 0.0f,
              "shock_death at the minion's entity point " + Point(enemyPx) + ": " + Point(death.atPx) + " z " +
                  std::to_string(death.zUnits));
    // Put 8 px from the player, whom the diamond sits on: the step pushes the two
    // bodies apart before the strike reads it (about 4 px, the first run's 4.04).
    CHECK_MSG(glm::distance(strike.preyCentrePx, glm::dvec2(lyingAt.x + 8.0, lyingAt.y)) < 8.0,
              "the minion where it was put, less the step's push: " + Point(strike.preyCentrePx));
    CHECK_MSG(death.systems == 2 && death.pool == 8 + 1 && death.systemSizePx.size() == 2 &&
                  nearlyU(death.systemSizePx[0], 22.0) && nearlyU(death.systemSizePx[1], 3.0) && death.temporary &&
                  !death.drawn,
              "8 shock cells at 22 and a sparkle: " + std::to_string(death.pool));
    // THE STRIKE: halfway between the diamond's point and the minion's, z halfway
    // between 0 and 0.711, turned by the radians of atan2f(d.x, d.y), d = normalize(
    // minion - diamond), wrapped into [0, 2 pi) - a number of degrees under 6.3.
    const glm::dvec2 mid = (strike.diamondPx + enemyPx) * 0.5;
    const glm::dvec2 d = glm::normalize(enemyPx - strike.diamondPx);
    double radians = std::atan2(d.x, d.y);
    if (radians < 0.0) radians += 2.0 * 3.14159265358979323846;
    CHECK_MSG(glm::distance(bolt.atPx, mid) < 1e-9 && nearlyU(bolt.zUnits, kMinionZ * 0.5) &&
                  std::fabs(bolt.angleDeg - radians) < 1e-5 && bolt.angleDeg >= 0.0f && bolt.angleDeg < 6.2832f,
              "shock_strike at the midpoint " + Point(mid) + " z " + std::to_string(bolt.zUnits) + ", turned " +
                  std::to_string(bolt.angleDeg) + " (want " + std::to_string(radians) + ")");
    CHECK_MSG(bolt.systems == 2 && bolt.pool == 2 + 1 && bolt.systemSizePx.size() == 2 &&
                  nearlyU(bolt.systemSizePx[0], 32.0) && nearlyU(bolt.systemSizePx[1], 3.0) && bolt.temporary,
              "2 shock cells at 32 all at once and a sparkle: " + std::to_string(bolt.pool));
    const int boltCells = CheckShockCut(registry, bolt, "shock_strike");
    CHECK_MSG(boltCells == 2, "its two cells drawn on the frame it is added: " + std::to_string(boltCells));
    std::printf("  3-16: shock_diamond_pick at %s z %.3f (freed frame %d); struck: shock_death at %s z %.4f, "
                "shock_strike at %s z %.4f turned %.6f 'degrees'\n",
                Point(pick.atPx).c_str(), pick.zUnits, pickBurnt.freedOn, Point(death.atPx).c_str(), death.zUnits,
                Point(bolt.atPx).c_str(), bolt.zUnits, bolt.angleDeg);
    // Both freed by their pools: the death's last cell released at 7/8 of 600 +- 200
    // and living as long again, the strike's 700 ms.
    const Burnt boltBurnt = BurnDown(layer, registry, bolt.id, 150);
    CHECK_MSG(boltBurnt.freedOn >= 40 && boltBurnt.freedOn <= 45 && boltBurnt.mostReleased == 3,
              "shock_strike's 700 ms: freed on frame " + std::to_string(boltBurnt.freedOn));
    layer.OnDetach(registry);
}

// THE FIRE DIAMOND. On 3-32 (level31b): fire_diamond_ent_1256 at (356, 128), eth_z -10,
// taken - burn_projectile a BARE 10 in front of the diamond, -10 + 3.5556 - and a tap
// with it carried, whose shot is burned where it stands: burn_projectile at the shot, at
// a bare 10 of its own, 3.5556, the point the fireball is made at.
void AFireDiamondBurnsWhereItIsTakenAndWhereItsShotIs() {
    if (!OriginalArtIsThere("AFireDiamondBurnsWhereItIsTakenAndWhereItsShotIs")) return;
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level31b");
    layer.OnAttach(registry);
    int ticks = 0;
    if (!ReadyToShoot(layer, registry, ticks)) return;
    const MagicPortals::Diamonds::Diamond* fire = nullptr;
    for (const auto& diamond : layer.SimLevel()->diamonds.diamonds) {
        if (diamond.fire && fire == nullptr) fire = &diamond;
    }
    CHECK_MSG(fire != nullptr, "3-32 places a fire diamond");
    if (fire == nullptr) return;
    const glm::dvec2 lyingAt = fire->atPx;
    // TAKEN is the tick the free arm writes ownerID; hasFireDiamond is the carried
    // arm's, a tick later (the first run of this case waited for that and found the
    // burn already added, as it should be).
    const auto owned = [&layer]() {
        for (const auto& diamond : layer.SimLevel()->diamonds.diamonds) {
            if (diamond.fire && diamond.owner != entt::null) return true;
        }
        return false;
    };
    int spawnedBefore = layer.EffectsSpawned();
    for (int i = 0; i < 5 && !owned(); ++i) {
        PutPlayerAt(registry, layer, lyingAt);
        spawnedBefore = layer.EffectsSpawned();
        tickWith(layer, registry, kRest, {}, {});
        if (owned()) break;
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    }
    CHECK_MSG(owned(), "the player takes the fire diamond");
    // Its sound on the tick: playBurnSound (ETHCallback_fire_diamond #190-192;
    // planning step 142), not a shock diamond's.
    const auto heard = [&layer](const char* event) {
        const std::vector<std::string> sounds = layer.LatchedSounds();
        return static_cast<int>(std::count(sounds.begin(), sounds.end(), std::string(event)));
    };
    CHECK_MSG(heard("burned") == 1 && heard("shock_picked") == 0, "playBurnSound as it is taken");
    CHECK_MSG(layer.EffectsSpawned() == spawnedBefore && EffectsOf(layer, "burn_projectile.ent").empty(),
              "nothing is added on the tick");
    layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    int count = 0;
    const MagicPortalsLayer::EffectReport taken = FirstEffect(layer, "burn_projectile.ent", count);
    CHECK_MSG(count == 1, "one burn_projectile where it is taken: " + std::to_string(count));
    if (taken.id == 0) return;
    CHECK_MSG(taken.atPx == lyingAt && nearlyU(taken.zUnits, -10.0 + kBareTen) && taken.angleDeg == 0.0f,
              "at the diamond " + Point(lyingAt) + ", -10 + 3.5556: " + Point(taken.atPx) + " z " +
                  std::to_string(taken.zUnits));
    CHECK_MSG(taken.systems == 1 && taken.pool == 10 && taken.systemSizePx.size() == 1 &&
                  nearlyU(taken.systemSizePx[0], 48.0) && taken.temporary && !taken.drawn && !taken.hasLight,
              "ten explosion.JPG at 48, all at once: " + std::to_string(taken.pool));

    // A TAP, carried: the shot is burned before it ever flies.
    PutPlayerAt(registry, layer, lyingAt);
    tickWith(layer, registry, kRest, {}, {});
    layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    CHECK_MSG(layer.SimLevel()->diamonds.carrierHasFire, "the fire diamond is carried");
    glm::dvec2 aim = playerPx(registry, layer) + glm::dvec2(60.0, -50.0);
    for (int i = 0; i < 60 && !onScreen(registry, aim); ++i) {
        tickWith(layer, registry, kRest, {}, {});
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
        aim = playerPx(registry, layer) + glm::dvec2(60.0, -50.0);
    }
    shoot(layer, registry, screenOf(registry, aim));
    CHECK_MSG(layer.SimLevel()->portals.flight.has_value(), "the tap fired: " + lastFailure(layer));
    layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    const int converted = layer.SimLevel()->turrets.converted;
    tickWith(layer, registry, kRest, {}, {});
    CHECK_MSG(layer.SimLevel()->turrets.converted == converted + 1 &&
                  layer.SimLevel()->diamonds.burnedPx.size() == static_cast<std::size_t>(1),
              "the shot is burned on the next tick, and the tick records where");
    CHECK_MSG(heard("fireball_spat") == 1, "and addFireball's playFireballSound with it (#87)");
    if (layer.SimLevel()->diamonds.burnedPx.empty()) return;
    const glm::dvec2 burnedAt = layer.SimLevel()->diamonds.burnedPx[0];
    const std::string made = "fire_diamond#" + std::to_string(converted + 1);
    bool madeThere = false;
    for (const auto& ball : layer.SimLevel()->turrets.fireballs) {
        if (ball.name == made) madeThere = ball.atPx == burnedAt;
    }
    CHECK_MSG(madeThere, "the fireball is made where the shot was burned: " + Point(burnedAt));
    const int before = layer.EffectsSpawned();
    layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    MagicPortalsLayer::EffectReport shot;
    for (const MagicPortalsLayer::EffectReport& report : EffectsOf(layer, "burn_projectile.ent")) {
        if (report.id > before) shot = report;
    }
    CHECK_MSG(shot.id != 0 && shot.atPx == burnedAt && nearlyU(shot.zUnits, kBareTen) && shot.pool == 10,
              "burn_projectile at the shot " + Point(burnedAt) + ", a bare 10 of its own: " + Point(shot.atPx) +
                  " z " + std::to_string(shot.zUnits));
    std::printf("  3-32: fire diamond taken at %s: burn_projectile z %.4f; its shot burned at %s: z %.4f\n",
                Point(taken.atPx).c_str(), taken.zUnits, Point(shot.atPx).c_str(), shot.zUnits);
    layer.OnDetach(registry);
}

// On 3-31 (level30b): its fire diamond (384, 134), eth_z 0, taken, then its shot turned
// at the level's one shock agent (224, 384): the fireball destroys the agent, whose
// destroy arm adds shock_death a bare 10 in front of it. Then the diamond carried into
// the gutter mouth below its block, which destroys it: extinguish_fire at the diamond,
// on its own depth.
void AFireDiamondsFireballAndItsDrainLeaveWhatTheScriptAdds() {
    if (!OriginalArtIsThere("AFireDiamondsFireballAndItsDrainLeaveWhatTheScriptAdds")) return;
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level30b");
    layer.OnAttach(registry);
    int ticks = 0;
    if (!ReadyToShoot(layer, registry, ticks)) return;
    const MagicPortals::Diamonds::Diamond* fire = nullptr;
    for (const auto& diamond : layer.SimLevel()->diamonds.diamonds) {
        if (diamond.fire && fire == nullptr) fire = &diamond;
    }
    const MagicPortals::Fields::Field* agent = layer.SimLevel()->fields.FindField("shock_agent_ent_2441");
    CHECK_MSG(fire != nullptr && agent != nullptr, "3-31 places a fire diamond and shock_agent_ent_2441");
    if (fire == nullptr || agent == nullptr) return;
    const glm::dvec2 lyingAt = fire->atPx;
    const glm::dvec2 agentAt = agent->atPx;
    for (int i = 0; i < 5 && !layer.SimLevel()->diamonds.carrierHasFire; ++i) {
        PutPlayerAt(registry, layer, lyingAt);
        tickWith(layer, registry, kRest, {}, {});
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    }
    CHECK_MSG(layer.SimLevel()->diamonds.carrierHasFire, "the fire diamond is carried");

    // THE AGENT: the player held 120 to its right in open air, outside its ring's 94,
    // and a tap between the two; the fireball flies on along it into the agent.
    const glm::dvec2 standAt = agentAt + glm::dvec2(120.0, 0.0);
    for (int i = 0; i < 30; ++i) {
        HoldPlayerAt(registry, layer, standAt);
        tickWith(layer, registry, kRest, {}, {});
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    }
    CHECK_MSG(!layer.SimLevel()->hazards.playerDied, "the player stands clear of the ring");
    // Its ring (art.json shock_ring, step 111) stands until the agent goes.
    const int ringsBefore = Tagged(registry, "Magic Portals Shock Ring");
    {
        const std::vector<MagicPortalsLayer::ShockRingReport> rings = layer.ShockRings();
        const MagicPortalsLayer::ShockRingReport* ring = RingOf(rings, "shock_agent_ent_2441");
        CHECK_MSG(ring != nullptr && ring->quad != entt::null && ringsBefore >= 1,
                  "shock_agent_ent_2441 wears its ring before the fireball");
    }
    const glm::dvec2 aim = agentAt + glm::dvec2(60.0, 0.0);
    CHECK_MSG(onScreen(registry, aim), "the tap is on screen");
    HoldPlayerAt(registry, layer, standAt);
    shoot(layer, registry, screenOf(registry, aim));
    CHECK_MSG(layer.SimLevel()->portals.flight.has_value(), "the tap fired: " + lastFailure(layer));
    layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    bool gone = false;
    for (int i = 0; i < 180 && !gone; ++i) {
        HoldPlayerAt(registry, layer, standAt);
        tickWith(layer, registry, kRest, {}, {});
        agent = layer.SimLevel()->fields.FindField("shock_agent_ent_2441");
        gone = agent != nullptr && agent->gone;
        if (!gone) layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    }
    CHECK_MSG(gone, "the fireball destroyed the agent");
    if (!gone) return;
    // Its sounds on the tick (planning step 142): ETHBeginContactCallback_fireball's
    // huge explosion for a shock agent (#99-118), then the small one every
    // destroyed fireball plays (#153-158) and the burn of the burnable agent
    // (#159-173); and the agent's own strike as it goes (#289-299).
    {
        const std::vector<std::string> sounds = layer.LatchedSounds();
        const auto heard = [&sounds](const char* event) {
            return static_cast<int>(std::count(sounds.begin(), sounds.end(), std::string(event)));
        };
        CHECK_MSG(heard("fireball_on_shock_agent") == 1 && heard("fireball_burst") == 1 && heard("burned") == 1 &&
                      heard("shock_struck") == 1,
                  "the huge explosion, the small, the burn and the strike: " +
                      std::to_string(heard("fireball_on_shock_agent")) + " / " +
                      std::to_string(heard("fireball_burst")) + " / " + std::to_string(heard("burned")) + " / " +
                      std::to_string(heard("shock_struck")));
    }
    // deleteEntity(childID) takes the ring with the agent, on the tick Fields marks it.
    {
        const std::vector<MagicPortalsLayer::ShockRingReport> rings = layer.ShockRings();
        const MagicPortalsLayer::ShockRingReport* ring = RingOf(rings, "shock_agent_ent_2441");
        CHECK_MSG(ring != nullptr && ring->quad == entt::null &&
                      Tagged(registry, "Magic Portals Shock Ring") == ringsBefore - 1,
                  "and its ring goes with it on that tick: " +
                      std::to_string(Tagged(registry, "Magic Portals Shock Ring")) + " of " +
                      std::to_string(ringsBefore) + " left");
    }
    int deaths = 0;
    FirstEffect(layer, "shock_death.ent", deaths);
    CHECK_MSG(deaths == 0, "nothing is added on the tick");
    const int beforeAgent = layer.EffectsSpawned();
    layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    MagicPortalsLayer::EffectReport death;
    for (const MagicPortalsLayer::EffectReport& report : EffectsOf(layer, "shock_death.ent")) {
        if (report.id > beforeAgent) death = report;
    }
    CHECK_MSG(death.id != 0 && death.atPx == agent->atPx && nearlyU(death.zUnits, kBareTen) && death.pool == 8 + 1,
              "shock_death at the agent " + Point(agent->atPx) + ", a bare 10 in front of it: " + Point(death.atPx) +
                  " z " + std::to_string(death.zUnits));
    std::printf("  3-31: shock_agent_ent_2441 destroyed by a fireball: shock_death at %s z %.4f\n",
                Point(death.atPx).c_str(), death.zUnits);

    // THE DRAIN: 10 x 51 hung 46 below the gutter mouth's node at (384, 182).
    const glm::dvec2 inTheMouth(384.0, 182.0 + 46.0);
    const MagicPortals::Diamonds::Diamond* held = nullptr;
    glm::dvec2 drainedAt(0.0);
    bool drained = false;
    for (int i = 0; i < 120 && !drained; ++i) {
        PutPlayerAt(registry, layer, inTheMouth);
        tickWith(layer, registry, kRest, {}, {});
        for (const auto& diamond : layer.SimLevel()->diamonds.diamonds) {
            if (diamond.fire) held = &diamond;
        }
        drained = held != nullptr && held->gone;
        if (drained) drainedAt = held->atPx;
        else layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    }
    CHECK_MSG(drained, "the drain took the diamond");
    if (!drained) return;
    CHECK(EffectsOf(layer, "extinguish_fire.ent").empty());
    layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    int waters = 0;
    const MagicPortalsLayer::EffectReport water = FirstEffect(layer, "extinguish_fire.ent", waters);
    CHECK_MSG(waters == 1 && water.atPx == drainedAt && nearlyU(water.zUnits, 0.0) && water.angleDeg == 0.0f,
              "extinguish_fire at the diamond " + Point(drainedAt) + ", on its own depth: " + Point(water.atPx) +
                  " z " + std::to_string(water.zUnits));
    CHECK_MSG(water.systems == 1 && water.pool == 14 && water.systemSizePx.size() == 1 &&
                  nearlyU(water.systemSizePx[0], 24.0) && water.temporary && !water.drawn,
              "fourteen water.png at 24 over a life: " + std::to_string(water.pool));
    const Burnt burnt = BurnDown(layer, registry, water.id, 150);
    CHECK_MSG(burnt.mostReleased == 14 && burnt.freedOn >= 70 && burnt.freedOn <= 100,
              "all 14 released, freed on frame " + std::to_string(burnt.freedOn) + " (700 + 700 +- 100 ms)");
    std::printf("  3-31: the diamond drained at %s: extinguish_fire z %.4f, freed on frame %d\n",
                Point(water.atPx).c_str(), water.zUnits, burnt.freedOn);
    layer.OnDetach(registry);
}

// THE FIRE SIGNAL, on 4-29 (level28c): the torch lit by Q.1's tap on tick 60 (L1's
// point) and its signal put out by the same tap on tick 250. extinguish_fire goes at
// vector3(originalPos, 10): the torch's point, at a bare 10 of its own.
void AFireSignalPutOutLeavesItsWaterAtItsTorch() {
    if (!OriginalArtIsThere("AFireSignalPutOutLeavesItsWaterAtItsTorch")) return;
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level28c");
    layer.OnAttach(registry);
    CHECK_MSG(layer.SimLevel() != nullptr && layer.ArtError().empty(), layer.LoadError() + layer.ArtError());
    if (layer.SimLevel() == nullptr || !layer.ArtError().empty()) return;
    layer.ScheduleDevTap(60, glm::dvec2(247.0 / 1280.0, 141.0 / 720.0));
    layer.ScheduleDevTap(250, glm::dvec2(247.0 / 1280.0, 141.0 / 720.0));
    bool lit = false;
    glm::dvec2 torchAt(0.0);
    int putOutOn = -1;
    for (int tick = 1; tick <= 400 && putOutOn < 0; ++tick) {
        tickWith(layer, registry, kRest, {}, {});
        const auto& torch = layer.SimLevel()->torch;
        if (torch.signal.present) {
            lit = true;
            torchAt = torch.signal.originPx;
        }
        if (torch.putOut > 0) {
            putOutOn = tick;
            break;
        }
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    }
    CHECK_MSG(lit && putOutOn > 0, "the torch was lit and its signal put out, on tick " + std::to_string(putOutOn));
    if (putOutOn < 0) return;
    {
        // Its sound on that tick: playLightOffSound (ETHCallback_fire_signal #275;
        // planning step 142).
        const std::vector<std::string> sounds = layer.LatchedSounds();
        CHECK_MSG(std::count(sounds.begin(), sounds.end(), std::string("light_off")) == 1,
                  "playLightOffSound on the tick it is put out");
    }
    CHECK_MSG(!layer.SimLevel()->torch.signal.present, "and the signal is gone");
    CHECK(EffectsOf(layer, "extinguish_fire.ent").empty());
    layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    int count = 0;
    const MagicPortalsLayer::EffectReport water = FirstEffect(layer, "extinguish_fire.ent", count);
    const MagicPortals::Torch::Light* light =
        layer.SimLevel()->torch.lights.empty() ? nullptr : &layer.SimLevel()->torch.lights[0];
    CHECK_MSG(count == 1 && light != nullptr && water.atPx == torchAt && torchAt == light->atPx &&
                  nearlyU(water.zUnits, kBareTen) && water.pool == 14,
              "one extinguish_fire at the torch " + Point(torchAt) + ", a bare 10 of its own: " + Point(water.atPx) +
                  " z " + std::to_string(water.zUnits));
    std::printf("  4-29: the signal put out on tick %d: extinguish_fire at %s z %.4f\n", putOutOn,
                Point(water.atPx).c_str(), water.zUnits);
    layer.OnDetach(registry);
}

// THE LIT TORCH IS THE ENTITY ITS SHOT ADDS (the visuals plan's 11.2; effects.json
// light_from_projectile, light_on_sparkles, portal_death_at_lit_torch), on 4-22
// (level21c): L1's tap at the torch, which has no wall and so no signal and no
// bounce. On the tick it lights, the frame adds the three - the lit torch on the
// torch's own point and depth (eth_z -10), its picture on its pivot 16 below it,
// where the unlit one stood; its sparkles there; and portal_death where the shot
// was. The level's own unlit picture goes on the NEXT tick (the `delete` branch).
void AShotLightsTheTorchAsTheEntityItAdds() {
    if (!OriginalArtIsThere("AShotLightsTheTorchAsTheEntityItAdds")) return;
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level21c");
    layer.OnAttach(registry);
    CHECK_MSG(layer.SimLevel() != nullptr && layer.ArtError().empty(), layer.LoadError() + layer.ArtError());
    if (layer.SimLevel() == nullptr || !layer.ArtError().empty() || layer.SimLevel()->torch.lights.empty()) return;
    const glm::dvec2 torchPx = layer.SimLevel()->torch.lights[0].atPx;
    layer.ScheduleDevTap(60, glm::dvec2(692.0 / 1280.0, 113.0 / 720.0));
    int litOn = -1;
    for (int tick = 1; tick <= 200 && litOn < 0; ++tick) {
        tickWith(layer, registry, kRest, {}, {});
        if (layer.SimLevel()->torch.lights[0].lit) {
            litOn = tick;
            break;
        }
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    }
    CHECK_MSG(litOn > 0, "L1's tap lit 4-22's torch, on tick " + std::to_string(litOn));
    if (litOn < 0) return;
    {
        // Its sound on that tick: playLightOnSound (ETHCallback_light_off #145;
        // planning step 142).
        const std::vector<std::string> sounds = layer.LatchedSounds();
        CHECK_MSG(std::count(sounds.begin(), sounds.end(), std::string("light_on")) == 1,
                  "playLightOnSound on the tick it is lit");
    }
    // The tick it is lit: queued, not added; the unlit picture still stands.
    CHECK(EffectsOf(layer, "light_from_projectile.ent").empty() && EffectsOf(layer, "light_on_sparkles.ent").empty());
    std::vector<MagicPortalsLayer::TorchReport> torches = layer.TorchReports();
    CHECK_MSG(torches.size() == 1 && torches[0].levelPicture && !torches[0].unlitGone && nearlyU(torches[0].z, -10.0),
              "the unlit picture still stands on the tick it is lit, at eth_z -10");
    const std::optional<glm::dvec2> spent = layer.SimLevel()->torch.spentAtPx;
    CHECK_MSG(spent.has_value() && glm::distance(*spent, torchPx) < 24.0, "the shot spent within 24 of the torch");
    layer.OnUpdate(registry, MagicPortalsLayer::kTick);

    int count = 0;
    const MagicPortalsLayer::EffectReport lit = FirstEffect(layer, "light_from_projectile.ent", count);
    CHECK_MSG(count == 1 && lit.atPx == torchPx && nearlyU(lit.zUnits, -10.0) && lit.angleDeg == 0.0f &&
                  !lit.temporary && lit.drawn && lit.hasLight && lit.hasHalo,
              "the lit torch on the torch " + Point(torchPx) + ", z -10, a picture, a light and a halo, not temporary: " +
                  Point(lit.atPx) + " z " + std::to_string(lit.zUnits));
    CHECK_MSG(lit.systems == 1 && lit.pool == 12 && lit.bounceScale == glm::dvec2(1.0),
              "its flame, 12 fire.png, and no bounce where there is no wall");
    if (lit.quad != entt::null) {
        const TransformComponent& placed = registry.get<TransformComponent>(lit.quad);
        const glm::dvec2 centre = MagicPortals::Units::ToPixels(placed.position);
        const glm::dvec2 size = glm::dvec2(placed.scale.x, placed.scale.y) * MagicPortals::Units::kPixelsPerMetre;
        CHECK_MSG(glm::distance(centre, torchPx + glm::dvec2(0.0, 16.0)) < 1e-3 && nearlyU(size.x, 32.0, 1e-3) &&
                      nearlyU(size.y, 64.0, 1e-3) && placed.rotation.z == 0.0f,
                  "torch_small.png, 32 x 64, centred 16 below the torch on its PivotAdjust (0, -16): " + Point(centre) +
                      " " + Point(size));
    }
    const MagicPortalsLayer::EffectReport sparkles = FirstEffect(layer, "light_on_sparkles.ent", count);
    CHECK_MSG(count == 1 && sparkles.atPx == torchPx && nearlyU(sparkles.zUnits, -10.0) && sparkles.temporary &&
                  sparkles.systems == 2 && !sparkles.drawn,
              "light_on_sparkles on the torch, z -10: onda and 28 sparkles, temporary");
    const MagicPortalsLayer::EffectReport burst = FirstEffect(layer, "portal_death.ent", count);
    CHECK_MSG(count == 1 && spent.has_value() && burst.atPx == *spent && nearlyU(burst.zUnits, 0.0),
              "portal_death where the shot was spent, its bare 0: " + Point(burst.atPx));

    // The next tick runs the `delete` branch: the level's unlit torch and its spark
    // go, drawn once with the lit torch on the frame before.
    tickWith(layer, registry, kRest, {}, {});
    layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    torches = layer.TorchReports();
    CHECK_MSG(torches.size() == 1 && !torches[0].levelPicture && torches[0].unlitGone,
              "the level's unlit picture gone on the tick after");
    CHECK_EQ(EffectsOf(layer, "light_from_projectile.ent").size(), std::size_t{1});
    // And it stays: a lit torch on a level with no wall burns for good.
    for (int frame = 0; frame < 180; ++frame) {
        tickWith(layer, registry, kRest, {}, {});
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    }
    CHECK_MSG(EffectsOf(layer, "light_from_projectile.ent").size() == 1 && EffectsOf(layer, "light_on_sparkles.ent").empty(),
              "three seconds on, the lit torch burns on and its sparkles are over");
    std::printf("  4-22: the torch lit on tick %d: light_from_projectile at %s z %.1f, its sparkles, the burst at %s\n",
                litOn, Point(lit.atPx).c_str(), lit.zUnits, Point(burst.atPx).c_str());
    layer.OnDetach(registry);
}

// PUT OUT AND BROUGHT BACK, on 4-29 (level28c), by L1's two taps and a third: the
// lit torch bounces (the level has a wall) and its signal rides the orbit; the wall
// goes with its dust, turned by it; the signal shot takes the lit torch and the
// signal and adds the torch back - light_off.ent at vector3(originalPos, 10), a
// vertical entity bottom-centred on its pivot - its sparkles, the burst at the shot,
// and the wall back at the ghost with its smoke, fading in over a second. Lit again,
// the torch put back goes on the tick after, and the wall that comes back is the
// one that goes, where the ghost put it.
void ATorchPutOutComesBackAndItsWallFadesIn() {
    if (!OriginalArtIsThere("ATorchPutOutComesBackAndItsWallFadesIn")) return;
    namespace Torch = MagicPortals::Torch;
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level28c");
    layer.OnAttach(registry);
    CHECK_MSG(layer.SimLevel() != nullptr && layer.ArtError().empty(), layer.LoadError() + layer.ArtError());
    if (layer.SimLevel() == nullptr || !layer.ArtError().empty() || layer.SimLevel()->torch.lights.empty() ||
        !layer.SimLevel()->torch.wall.present) {
        return;
    }
    const glm::dvec2 torchPx = layer.SimLevel()->torch.lights[0].atPx;
    const glm::dvec2 wallPx(192.0, 96.0);
    constexpr double kGhostZ = 2.0 - 4.0 / (720.0 / 256.0);
    const glm::dvec2 point(247.0 / 1280.0, 141.0 / 720.0);
    layer.ScheduleDevTap(60, point);
    layer.ScheduleDevTap(250, point);
    layer.ScheduleDevTap(430, point);
    int litOn = -1;
    int wallGoneOn = -1;
    int outOn = -1;
    int relitOn = -1;
    int wallGoneAgainOn = -1;
    const Torch::State* torch = &layer.SimLevel()->torch;
    for (int tick = 1; tick <= 640; ++tick) {
        const int wasLit = torch->lit;
        const int wasGone = torch->wallsGone;
        const int wasOut = torch->putOut;
        tickWith(layer, registry, kRest, {}, {});
        torch = &layer.SimLevel()->torch;
        const bool lightingNow = torch->lit > wasLit;
        const bool goneNow = torch->wallsGone > wasGone;
        const bool outNow = torch->putOut > wasOut;
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
        int count = 0;
        if (lightingNow && litOn < 0) {
            litOn = tick;
            const MagicPortalsLayer::EffectReport lit = FirstEffect(layer, "light_from_projectile.ent", count);
            const MagicPortals::Art::Pulse pulse{glm::dvec2(1.04), glm::dvec2(0.96), 160.0};
            const glm::dvec2 first = pulse.ScaleAt(kScriptMs);
            CHECK_MSG(count == 1 && nearlyU(lit.zUnits, -12.0) && nearlyU(lit.bounceScale.x, first.x, 1e-9) &&
                          lit.bounceScale.x > 1.02 && lit.bounceScale.x < 1.04,
                      "4-29's lit torch, z -12, bouncing from 1.04 - one frame in: " + std::to_string(lit.bounceScale.x));
            const MagicPortalsLayer::EffectReport signal = FirstEffect(layer, "fire_signal.ent", count);
            CHECK_MSG(count == 1 && signal.atPx == torchPx && nearlyU(signal.zUnits, -12.0) && !signal.temporary &&
                          signal.systems == 2,
                      "the fire signal on the torch, z -12, its two systems: " + Point(signal.atPx));
        } else if (litOn > 0 && tick == litOn + 1) {
            const MagicPortalsLayer::EffectReport signal = FirstEffect(layer, "fire_signal.ent", count);
            CHECK_MSG(count == 1 && signal.atPx == torch->signal.atPx && signal.atPx.y < torchPx.y - 17.0 &&
                          signal.atPx.x > torchPx.x,
                      "a tick on, riding the signal just past the top: " + Point(signal.atPx - torchPx));
            const std::vector<MagicPortalsLayer::TorchReport> torches = layer.TorchReports();
            CHECK_MSG(torches.size() == 1 && !torches[0].levelPicture, "and the level's unlit torch gone");
        }
        if (goneNow && wallGoneOn < 0) {
            wallGoneOn = tick;
            const MagicPortalsLayer::EffectReport dust = FirstEffect(layer, "wall_destroy.ent", count);
            CHECK_MSG(count == 1 && dust.atPx == wallPx && nearlyU(dust.zUnits, 2.0) && dust.angleDeg == 0.0f &&
                          dust.scriptScale == 1.0,
                      "the light wall's dust on it, z 2, unturned, x1: " + Point(dust.atPx));
        }
        if (outNow && outOn < 0) {
            outOn = tick;
            CHECK_MSG(EffectsOf(layer, "light_from_projectile.ent").empty() && EffectsOf(layer, "fire_signal.ent").empty(),
                      "the lit torch and the signal gone with the shot");
            const MagicPortalsLayer::EffectReport back = FirstEffect(layer, "light_off.ent", count);
            CHECK_MSG(count == 1 && back.atPx == torchPx && nearlyU(back.zUnits, kBareTen) && !back.temporary &&
                          back.systems == 2,
                      "the torch put back at vector3(originalPos, 10): " + Point(back.atPx) + " z " +
                          std::to_string(back.zUnits));
            if (back.quad != entt::null) {
                const TransformComponent& placed = registry.get<TransformComponent>(back.quad);
                const glm::dvec2 centre = MagicPortals::Units::ToPixels(placed.position);
                CHECK_MSG(glm::distance(centre, torchPx + glm::dvec2(0.0, 16.0)) < 1e-3 && placed.rotation.z == 0.0f,
                          "type 2, bottom-centred on (0, -48): the same 16 below as the lit one: " + Point(centre));
            }
            const MagicPortalsLayer::EffectReport sparkles = FirstEffect(layer, "light_off_sparkles.ent", count);
            CHECK_MSG(count == 1 && sparkles.atPx == torchPx && nearlyU(sparkles.zUnits, kBareTen),
                      "light_off_sparkles there too");
            const MagicPortalsLayer::EffectReport smoke = FirstEffect(layer, "light_wall_create.ent", count);
            CHECK_MSG(count == 1 && smoke.atPx == wallPx && nearlyU(smoke.zUnits, kGhostZ, 1e-9) &&
                          smoke.angleDeg == 0.0f && smoke.temporary,
                      "light_wall_create at the ghost, the wall's depth less 4 raw px: z " +
                          std::to_string(smoke.zUnits));
            const MagicPortalsLayer::EffectReport wall = FirstEffect(layer, "light_wall.ent", count);
            CHECK_MSG(count == 1 && wall.atPx == wallPx && nearlyU(wall.zUnits, kGhostZ, 1e-9) && wall.drawn &&
                          nearlyU(wall.alpha, kScriptMs / 1000.0, 1e-6),
                      "the wall back at the ghost, one frame into its fade: alpha " + std::to_string(wall.alpha));
        }
        if (outOn > 0 && tick == outOn + TicksOf(1000.0)) {
            int count2 = 0;
            const MagicPortalsLayer::EffectReport wall = FirstEffect(layer, "light_wall.ent", count2);
            CHECK_MSG(count2 == 1 && nearlyU(wall.alpha, 1.0), "a second on, whole: " + std::to_string(wall.alpha));
        }
        if (outOn > 0 && lightingNow && relitOn < 0) relitOn = tick;
        if (relitOn > 0 && tick == relitOn) {
            const MagicPortalsLayer::EffectReport lit = FirstEffect(layer, "light_from_projectile.ent", count);
            CHECK_MSG(count == 1 && nearlyU(lit.zUnits, kBareTen),
                      "lit again, on the depth the torch was put back at: z " + std::to_string(lit.zUnits));
            CHECK_EQ(EffectsOf(layer, "light_off.ent").size(), std::size_t{1});
        }
        if (relitOn > 0 && tick == relitOn + 1) {
            CHECK_MSG(EffectsOf(layer, "light_off.ent").empty(), "and the torch put back goes on the tick after");
        }
        if (relitOn > 0 && goneNow && tick > wallGoneOn) {
            wallGoneAgainOn = tick;
            CHECK_MSG(EffectsOf(layer, "light_wall.ent").empty(), "the rebuilt wall goes at its 1500 ms");
            bool atGhost = false;
            for (const MagicPortalsLayer::EffectReport& dust : EffectsOf(layer, "wall_destroy.ent")) {
                if (dust.atPx == wallPx && nearlyU(dust.zUnits, kGhostZ, 1e-9)) atGhost = true;
            }
            CHECK_MSG(atGhost, "and its dust is where it stood, at the ghost's depth");
            break;
        }
    }
    CHECK_MSG(litOn > 0 && wallGoneOn > litOn && outOn > wallGoneOn && relitOn > outOn && wallGoneAgainOn > relitOn,
              "lit " + std::to_string(litOn) + ", wall gone " + std::to_string(wallGoneOn) + ", put out " +
                  std::to_string(outOn) + ", lit again " + std::to_string(relitOn) + ", wall gone again " +
                  std::to_string(wallGoneAgainOn));
    std::printf("  4-29: lit on tick %d, the wall gone %d, put out %d, lit again %d, the wall gone again %d\n", litOn,
                wallGoneOn, outOn, relitOn, wallGoneAgainOn);
    layer.OnDetach(registry);
}

// THE TRAIL (effects.json movement_trail) on 4-05 (level4c), a weightless level:
// none at rest; at 0.5 m/s the first tick adds one at once - the clock ran on at rest
// - riding on the player at its own depth and drawn in front of it; then one every
// 24th tick; and none at 0.4 exactly. None where the world has gravity (1-01).
void AWeightlessPlayerLeavesATrail() {
    if (!OriginalArtIsThere("AWeightlessPlayerLeavesATrail")) return;
    constexpr double kPlayerZ = 4.0 / (720.0 / 256.0);
    for (const char* name : {"level4c", "level0"}) {
        const bool weightless = std::string(name) == "level4c";
        entt::registry registry;
        publishViewport(registry);
        MagicPortalsLayer layer(TestPaths(), name);
        layer.OnAttach(registry);
        CHECK_MSG(layer.SimLevel() != nullptr && layer.ArtError().empty(), layer.LoadError() + layer.ArtError());
        if (layer.SimLevel() == nullptr || !layer.ArtError().empty()) return;
        CloseTheLevelStartPopup(layer, registry);
        const entt::entity player = layer.SimLevel()->player;
        const auto trails = [&layer]() { return EffectsOf(layer, "movement_trail.ent"); };
        // addTrail reads the original's velocity, and the port carries the player at twice that (Player.hpp):
        // `speed` is the original's metres a second, 0.4 the strict gate. Pushed LEFT: level4c's pillar stands
        // 44 units to the right of the player, which twice the carried velocity reaches inside the case, and
        // a player pressed against it has no speed to read.
        const auto push = [&registry, player, &layer](float speed) {
            const float ratio = static_cast<float>(MagicPortals::ScriptClock::SimRatio(layer.TickStep()));
            registry.get<RigidBodyComponent>(player).velocity = glm::vec3(-speed * ratio, 0.0f, 0.0f);
        };
        for (int tick = 0; tick < 30; ++tick) {
            push(0.0f);
            tickWith(layer, registry, kRest, {}, {});
            layer.OnUpdate(registry, MagicPortalsLayer::kTick);
        }
        CHECK_MSG(trails().empty(), std::string(name) + ": none at rest");
        // 0.4 exactly: the test is strictly above.
        for (int tick = 0; tick < 5; ++tick) {
            push(0.4f);
            tickWith(layer, registry, kRest, {}, {});
            layer.OnUpdate(registry, MagicPortalsLayer::kTick);
        }
        CHECK_MSG(trails().empty(), std::string(name) + ": none at 0.4 m/s");
        std::vector<int> ids;
        std::vector<int> on;
        for (int tick = 1; tick <= 60; ++tick) {
            push(0.5f);
            tickWith(layer, registry, kRest, {}, {});
            layer.OnUpdate(registry, MagicPortalsLayer::kTick);
            for (const MagicPortalsLayer::EffectReport& trail : trails()) {
                if (std::find(ids.begin(), ids.end(), trail.id) != ids.end()) continue;
                ids.push_back(trail.id);
                on.push_back(tick);
                const glm::dvec2 playerPx =
                    MagicPortals::Units::ToPixels(registry.get<TransformComponent>(player).position);
                CHECK_MSG(glm::distance(trail.atPx, playerPx) < 1e-6 && nearlyU(trail.zUnits, kPlayerZ) &&
                              trail.temporary && trail.systems == 1 && trail.pool == 10 && !trail.drawn,
                          "a trail on the player " + Point(playerPx) + " at its z " + std::to_string(trail.zUnits) +
                              ": 10 portal_particle.png, temporary");
                CHECK_MSG(trail.systemZ.size() == 1 && trail.systemZ[0] > layer.PlayerSlotZ(),
                          "drawn over the body, as F10 has it");
            }
        }
        if (weightless) {
            // 400 ms of 16 is 25 ticks, and the clock must be strictly past it: the 26th (every 24th at 16.667).
            CHECK_MSG(on.size() == 3 && on[0] == 1 && on[1] == 27 && on[2] == 53,
                      "level4c: the first at once, then every 26th tick: " +
                          (on.empty() ? std::string("none") : std::to_string(on[0])) + " of " +
                          std::to_string(on.size()));
            std::printf("  4-05: at 0.5 m/s, trails on ticks %d, %d and %d of 60\n", on.size() > 0 ? on[0] : -1,
                        on.size() > 1 ? on[1] : -1, on.size() > 2 ? on[2] : -1);
        } else {
            CHECK_MSG(on.empty(), "level0 has the world's gravity: no trail");
        }
        layer.OnDetach(registry);
    }
}

// A LAP ROUND A WELL (gravitywell.json roundabout; effects.json roundabout_effect),
// on 4-17 (level16c): the player walked counter-clockwise round its well. On the tick
// the lap is run the frame adds roundabout_effect at the well's area - its xy, a
// bare -5 - the sound is latched, and the agent's picture, which stood at a whole
// turn (none), starts its turn: counter-clockwise, past a whole turn a quarter of a
// second in, and settled again at 3000 ms.
void ALapRoundAWellFlashesAndTurnsItsAgent() {
    if (!OriginalArtIsThere("ALapRoundAWellFlashesAndTurnsItsAgent")) return;
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level16c");
    layer.OnAttach(registry);
    CHECK_MSG(layer.SimLevel() != nullptr && layer.ArtError().empty(), layer.LoadError() + layer.ArtError());
    if (layer.SimLevel() == nullptr || !layer.ArtError().empty() || layer.SimLevel()->wells.wells.empty()) return;
    CloseTheLevelStartPopup(layer, registry);
    const MagicPortals::GravityWell::Well well = layer.SimLevel()->wells.wells.front();
    const MagicPortals::GravityWell::Roundabout rules = layer.SimLevel()->wells.rules.roundabout;
    const entt::entity agent = SpriteOf(registry, "Magic Portals Sprite", "/gravity_agent.png");
    CHECK(agent != entt::null);
    if (agent == entt::null) return;
    CHECK_MSG(layer.WellSpinDegrees(0) == 360.0 && registry.get<TransformComponent>(agent).rotation.z == 0.0f,
              "at rest a whole turn, drawn as none");
    const entt::entity player = layer.SimLevel()->player;
    int lapOn = -1;
    for (int tick = 0; tick < 200 && lapOn < 0; ++tick) {
        const double rad = tick * 4.0 * 3.14159265358979323846 / 180.0;
        PutPlayerAt(registry, layer, well.atPx + glm::dvec2(std::cos(rad), -std::sin(rad)) * (well.radiusPx * 0.5));
        registry.get<RigidBodyComponent>(player).velocity = glm::vec3(0.0f);
        tickWith(layer, registry, kRest, {}, {});
        // The sweep is stepped in BeforeStep, after the tick's latch: the lap is
        // read by the next tick's, as everything BeforeStep records is.
        if (!layer.SimLevel()->wells.lapsNow.empty()) {
            lapOn = tick;
            layer.OnUpdate(registry, MagicPortalsLayer::kTick);
            tickWith(layer, registry, kRest, {}, {});
            const std::vector<std::string> sounds = layer.LatchedSounds();
            CHECK_MSG(std::find(sounds.begin(), sounds.end(), "roundabout") != sounds.end(),
                      "the lap latches playRoundaboutSound's event");
            CHECK(EffectsOf(layer, "roundabout_effect.ent").empty());
        }
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    }
    CHECK_MSG(lapOn > 0, "the player lapped the well, on tick " + std::to_string(lapOn));
    if (lapOn < 0) return;
    int count = 0;
    const MagicPortalsLayer::EffectReport flash = FirstEffect(layer, "roundabout_effect.ent", count);
    CHECK_MSG(count == 1 && flash.atPx == well.atPx && nearlyU(flash.zUnits, -5.0 / (720.0 / 256.0)) &&
                  flash.temporary && flash.systems == 2,
              "roundabout_effect at the well's area " + Point(well.atPx) + ", z -5 bare: " + Point(flash.atPx) + " z " +
                  std::to_string(flash.zUnits));
    // The latch zeroed the agent's clock and set its sign, and the same tick's
    // callback step took it one frame on before its picture was placed.
    const double tickMs = kScriptMs;
    {
        const double spin = layer.WellSpinDegrees(0);
        CHECK_MSG(nearlyU(spin, MagicPortals::GravityWell::SpinDegrees(rules, tickMs, 1.0), 1e-9) && spin > 0.0,
                  "the lap's tick: zeroed and one step on, counter-clockwise: " + std::to_string(spin));
        const float drawn = registry.get<TransformComponent>(agent).rotation.z;
        CHECK_MSG(std::fabs(static_cast<double>(drawn) - std::fmod(spin, 360.0) * 3.14159265358979323846 / 180.0) < 1e-5,
                  "and its picture turned by it, +z: " + std::to_string(drawn));
    }
    double most = 0.0;
    int mostOn = -1;
    for (int tick = 2; tick <= 200; ++tick) {
        tickWith(layer, registry, kRest, {}, {});
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
        const double spin = layer.WellSpinDegrees(0);
        CHECK_MSG(nearlyU(spin, MagicPortals::GravityWell::SpinDegrees(rules, tickMs * tick, 1.0), 1e-3),
                  "its clock a tick a tick: " + std::to_string(spin));
        if (spin > most) {
            most = spin;
            mostOn = tick;
        }
    }
    CHECK_MSG(most > 480.0 && mostOn > 10 && mostOn < 22, "past a whole turn a quarter of a second in: " +
                                                              std::to_string(most) + " on tick " + std::to_string(mostOn));
    CHECK_MSG(layer.WellSpinDegrees(0) == 360.0 && registry.get<TransformComponent>(agent).rotation.z == 0.0f,
              "and settled on the turn by 3000 ms, drawn as none again");
    std::printf("  4-17: a lap round %s on tick %d: roundabout_effect at %s z %.4f; the agent turns to %.1f degrees\n",
                well.name.c_str(), lapOn, Point(flash.atPx).c_str(), flash.zUnits, most);
    layer.OnDetach(registry);
}

// THE RING'S KILL, on 3-25 (level24b): the player put in a shock ring dies to it, and
// ETHCallback_shock_area adds shock_death at the character's own point and depth (R10's
// 4 / 2.8125) - once. And a player already dead is not killed again: one put in a
// ring after falling out of the level adds none (isCharacterDead).
void AShockRingsKillLeavesShockDeathAtThePlayer() {
    if (!OriginalArtIsThere("AShockRingsKillLeavesShockDeathAtThePlayer")) return;
    constexpr double kPlayerZ = 4.0 / (720.0 / 256.0);
    for (const bool fallFirst : {false, true}) {
        entt::registry registry;
        publishViewport(registry);
        MagicPortalsLayer layer(TestPaths(), "level24b");
        layer.OnAttach(registry);
        CHECK_MSG(layer.SimLevel() != nullptr && layer.ArtError().empty(), layer.LoadError() + layer.ArtError());
        if (layer.SimLevel() == nullptr || !layer.ArtError().empty()) return;
        CloseTheLevelStartPopup(layer, registry);
        for (int tick = 0; tick < 3; ++tick) {
            tickWith(layer, registry, kRest, {}, {});
            layer.OnUpdate(registry, MagicPortalsLayer::kTick);
        }
        CHECK_MSG(!layer.SimLevel()->fields.fields.empty(), "3-25 places a shock ring");
        if (layer.SimLevel()->fields.fields.empty()) return;
        const std::string ring = layer.SimLevel()->fields.fields[0].name;
        if (fallFirst) {
            const glm::dvec2 under(layer.BoundsPx().x * 0.5,
                                   layer.BoundsPx().y + layer.SimLevel()->hazards.marginPx.y + 64.0);
            for (int tick = 0; tick < 5 && !layer.SimLevel()->hazards.playerDied; ++tick) {
                PutPlayerAt(registry, layer, under);
                tickWith(layer, registry, kRest, {}, {});
                layer.OnUpdate(registry, MagicPortalsLayer::kTick);
            }
            CHECK_MSG(layer.SimLevel()->hazards.playerDied && layer.SimLevel()->hazards.diedByFalling,
                      "the player fell out first");
        }
        const int before = layer.EffectsSpawned();
        glm::dvec2 killedAt(0.0);
        bool claimed = false;
        for (int tick = 0; tick < 5 && !claimed; ++tick) {
            const MagicPortals::Fields::Field* field = layer.SimLevel()->fields.FindField(ring);
            if (field == nullptr) break;
            PutPlayerAt(registry, layer, field->atPx);
            tickWith(layer, registry, kRest, {}, {});
            claimed = layer.SimLevel()->fields.playerKilled;
            if (claimed) killedAt = playerPx(registry, layer);
            else layer.OnUpdate(registry, MagicPortalsLayer::kTick);
        }
        CHECK_MSG(claimed, "the ring claims the player");
        if (!claimed) return;
        {
            // Its strike's sound on the same rule as its shock_death (ETHCallback_shock_area
            // #136-151; planning step 142): heard only where the ring's is the death.
            const std::vector<std::string> sounds = layer.LatchedSounds();
            const auto strikes = std::count(sounds.begin(), sounds.end(), std::string("shock_struck"));
            CHECK_MSG(strikes == (fallFirst ? 0 : 1), "playShockStrikeSound " + std::to_string(strikes) + " time(s)");
        }
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
        int deaths = 0;
        const MagicPortalsLayer::EffectReport death = FirstEffect(layer, "shock_death.ent", deaths);
        if (fallFirst) {
            CHECK_MSG(deaths == 0 && layer.SimLevel()->hazards.killedBy != ring,
                      "a player dead already is not killed again: " + std::to_string(deaths));
        } else {
            CHECK_MSG(layer.SimLevel()->hazards.playerDied && layer.SimLevel()->hazards.killedBy == ring,
                      "the ring's is the death: " + layer.SimLevel()->hazards.killedBy);
            // And checkGameLost's blood.ent, the hp branch every death but a fall takes
            // (step 96): two on the frame since the merge of the two tracks (planning
            // step 112), the ring's first.
            int bloods = 0;
            const MagicPortalsLayer::EffectReport blood = FirstEffect(layer, "blood.ent", bloods);
            CHECK_MSG(deaths == 1 && bloods == 1 && layer.EffectsSpawned() == before + 2 && death.id < blood.id &&
                          death.atPx == killedAt && nearlyU(death.zUnits, kPlayerZ) && death.pool == 8 + 1,
                      "one shock_death at the player " + Point(killedAt) + ", on its 1.4222: " + Point(death.atPx) +
                          " z " + std::to_string(death.zUnits) + ", then its blood");
            // Held in the ring, the player is not killed twice.
            for (int tick = 0; tick < 10; ++tick) {
                const MagicPortals::Fields::Field* field = layer.SimLevel()->fields.FindField(ring);
                if (field != nullptr) PutPlayerAt(registry, layer, field->atPx);
                tickWith(layer, registry, kRest, {}, {});
                layer.OnUpdate(registry, MagicPortalsLayer::kTick);
            }
            FirstEffect(layer, "shock_death.ent", deaths);
            CHECK_MSG(deaths == 1, "and only once: " + std::to_string(deaths));
            std::printf("  3-25: killed by %s: shock_death at %s z %.4f\n", ring.c_str(), Point(death.atPx).c_str(),
                        death.zUnits);
        }
        layer.OnDetach(registry);
    }
}

// ---- what a wall, a stone and a lift door leave (the visuals plan's 11.1) --------

// How far apart an effect's drawn particles lie, across (x) and down (y) the
// level: its live quads' centres, as placeSprite put them.
glm::dvec2 QuadSpreadPx(entt::registry& registry, const MagicPortalsLayer::EffectReport& effect, int& read) {
    glm::dvec2 low(1e12);
    glm::dvec2 high(-1e12);
    read = 0;
    for (const entt::entity quad : effect.particleQuads) {
        if (!registry.valid(quad)) continue;
        const glm::dvec2 at = MagicPortals::Units::ToPixels(registry.get<TransformComponent>(quad).position);
        low = glm::min(low, at);
        high = glm::max(high, at);
        ++read;
    }
    return read > 0 ? high - low : glm::dvec2(0.0);
}

// A stone thrown at a breakable wall: on the tick it breaks nothing is added; on
// the frame one wall_destroy at the wall's NODE, on its eth_z, turned by its angle
// and at its size - its 22 dirt and 10 smoke specks along a line that runs down
// the screen on 1-09's upright wall and across it on 1-13's, which the .tscn turns
// 1.5708 clockwise (the original's -90): D4 section 2.2b's 13 of 33.
void ABreakableWallLeavesItsDustTurnedByTheWall() {
    if (!OriginalArtIsThere("ABreakableWallLeavesItsDustTurnedByTheWall")) return;
    struct Throw {
        const char* level;
        const char* tag;
        glm::dvec2 wallPx;
        glm::dvec2 fromPx;
        glm::dvec2 velocityPx;
        bool lying;
    };
    const Throw throws[] = {{"level8", "1-09", {320.0, 124.0}, {305.0 - 30.0 - 20.0, 95.0}, {300.0, 0.0}, false},
                            {"level12", "1-13", {192.0, 282.0}, {192.0, 282.0 - 16.0 - 30.0 - 20.0}, {0.0, 300.0}, true}};
    for (const Throw& thrown : throws) {
        const std::string row = std::string(thrown.tag) + " (" + thrown.level + ")";
        entt::registry registry;
        publishViewport(registry);
        MagicPortalsLayer layer(TestPaths(), thrown.level);
        layer.OnAttach(registry);
        CHECK_MSG(layer.SimLevel() != nullptr && layer.ArtError().empty(), layer.LoadError() + layer.ArtError());
        if (layer.SimLevel() == nullptr || !layer.ArtError().empty()) return;
        CHECK_MSG(layer.SimLevel()->demolish.stones.size() == 1, row + ": one stone");
        if (layer.SimLevel()->demolish.stones.size() != 1) continue;
        CloseTheLevelStartPopup(layer, registry);
        for (int tick = 0; tick < 3; ++tick) {
            tickWith(layer, registry, kRest, {}, {});
            layer.OnUpdate(registry, MagicPortalsLayer::kTick);
        }
        const entt::entity stone = layer.SimLevel()->demolish.stones.front().body;
        auto& transform = registry.get<TransformComponent>(stone);
        const glm::vec3 at = MagicPortals::Units::ToWorld(thrown.fromPx.x, thrown.fromPx.y);
        transform.position = glm::vec3(at.x, at.y, transform.position.z);
        registry.get<RigidBodyComponent>(stone).velocity =
            glm::vec3(MagicPortals::Units::ToMetres(thrown.velocityPx.x),
                      -MagicPortals::Units::ToMetres(thrown.velocityPx.y), 0.0f);
        int spawnedBefore = layer.EffectsSpawned();
        bool broke = false;
        for (int tick = 0; tick < 40 && !broke; ++tick) {
            spawnedBefore = layer.EffectsSpawned();
            tickWith(layer, registry, kRest, {}, {});
            broke = layer.SimLevel()->demolish.Broken() == 1;
            if (!broke) layer.OnUpdate(registry, MagicPortalsLayer::kTick);
        }
        CHECK_MSG(broke, row + ": the stone broke its wall");
        if (!broke) continue;
        int count = 0;
        FirstEffect(layer, "wall_destroy.ent", count);
        CHECK_MSG(layer.EffectsSpawned() == spawnedBefore && count == 0, row + ": nothing is added on the tick");
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
        const MagicPortalsLayer::EffectReport dust = FirstEffect(layer, "wall_destroy.ent", count);
        CHECK_MSG(count == 1, row + ": one wall_destroy on the frame: " + std::to_string(count));
        if (dust.id == 0) continue;
        const float wantDeg = thrown.lying ? static_cast<float>(-1.5708 * 180.0 / 3.14159265358979323846) : 0.0f;
        CHECK_MSG(dust.atPx == thrown.wallPx && nearlyU(dust.zUnits, -2.0) && static_cast<float>(dust.angleDeg) == wantDeg &&
                      dust.scriptScale == 1.0,
                  row + ": at the wall's node " + Point(thrown.wallPx) + ", its -2, turned " + std::to_string(wantDeg) +
                      ", x1: " + Point(dust.atPx) + " z " + std::to_string(dust.zUnits) + " turned " +
                      std::to_string(dust.angleDeg) + " x" + std::to_string(dust.scriptScale));
        CHECK_MSG(!dust.drawn && !dust.hasLight && dust.temporary && dust.systems == 2 && dust.pool == 22 + 10 &&
                      dust.systemSizePx.size() == 2 && nearlyU(dust.systemSizePx[0], 19.0) &&
                      nearlyU(dust.systemSizePx[1], 60.0),
                  row + ": 22 dirt at 19 and 10 smoke at 60, temporary");
        CHECK_MSG(dust.systemZ.size() == 2 && dust.systemZ[0] > layer.PlayerSlotZ() &&
                      dust.systemZ[1] > layer.PlayerSlotZ(),
                  row + ": both at their StartPoint's 32 in front of the wall, so of the player");
        // THE TURN, as drawn: every speck released at once along RandStartPoint (0,
        // 101) and (0, 102), turned by the wall.
        int read = 0;
        const glm::dvec2 spread = QuadSpreadPx(registry, dust, read);
        const double along = thrown.lying ? spread.x : spread.y;
        const double across = thrown.lying ? spread.y : spread.x;
        std::printf("  %s: the wall broken; wall_destroy at %s z %.1f turned %.5f, %d specks spread %.2f along the "
                    "wall's line and %.2f across it\n",
                    row.c_str(), Point(dust.atPx).c_str(), dust.zUnits, static_cast<double>(dust.angleDeg), read,
                    along, across);
        CHECK_MSG(read == 32 && along > 60.0 && along <= 102.0 + 8.0 && across < 8.0,
                  row + ": its specks along the wall's line (" + std::string(thrown.lying ? "across" : "down") +
                      " the screen): " + std::to_string(along) + " along, " + std::to_string(across) + " across, " +
                      std::to_string(read) + " read");
        const Burnt burnt = BurnDown(layer, registry, dust.id, 150);
        CHECK_MSG(burnt.freedOn >= 66 && burnt.freedOn <= 110 && burnt.freed >= 1,
                  row + ": freed by its pools, the dirt's 1100-1800 ms: frame " + std::to_string(burnt.freedOn));
        layer.OnDetach(registry);
    }
}

// 4-32's wall 2217, the one wall that carries destroyEffectScale (2): broken by
// the dark dragon's summon - a script's destroy(), no stone - once the torch's
// light wall has gone, as step 101's case drives it. Its dust at twice the size:
// every system's numbers doubled with the entity's (ETHParticleSystem.cpp:27-40).
void The432WallsDustIsTwiceTheSize() {
    if (!OriginalArtIsThere("The432WallsDustIsTwiceTheSize")) return;
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level31c");
    layer.OnAttach(registry);
    CHECK_MSG(layer.SimLevel() != nullptr && layer.ArtError().empty(), layer.LoadError() + layer.ArtError());
    if (layer.SimLevel() == nullptr || !layer.ArtError().empty() || layer.SimLevel()->torch.lights.empty()) return;
    int ticks = CloseTheLevelStartPopup(layer, registry);
    quakeTickWith(layer, registry, ticks);
    quakeTickWith(layer, registry, ticks);
    const glm::dvec2 torchPx = layer.SimLevel()->torch.lights.front().atPx;
    PutPlayerAt(registry, layer, glm::dvec2(240.0, 190.0));
    for (int waited = 0; waited < 600 && (waited < 60 || !onScreen(registry, torchPx)); ++waited) {
        quakeTickWith(layer, registry, ticks);
    }
    shoot(layer, registry, screenOf(registry, torchPx));
    ticks += 2;
    tickUntilUp(layer, registry, ticks, 400, [](const PlayedLevel& played) { return played.torch.lit; });
    CHECK_MSG(layer.SimLevel()->torch.lit > 0, "4-32: the shot lit the torch; the last shot: " + lastFailure(layer));
    if (layer.SimLevel()->torch.lit == 0) return;
    layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    const std::string wallNode = layer.SimLevel()->darkDragon.wallNode;
    const QuakeEdge arrived = tickUntilUp(layer, registry, ticks, 1000, [](const PlayedLevel& played) {
        for (const auto& breakable : played.demolish.breakables) {
            if (breakable.name == played.darkDragon.wallNode && breakable.broken) return 1;
        }
        return 0;
    });
    CHECK_MSG(arrived.tick > 0 && wallNode == "breakable_wall_2217", "4-32: the summon took " + wallNode);
    if (arrived.tick <= 0) return;
    int count = 0;
    FirstEffect(layer, "wall_destroy.ent", count);
    CHECK_MSG(count == 0, "4-32: nothing added on the tick");
    layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    // Two, as this case adds them (no frame between the lighting and the summon):
    // 2217's, and - since the visuals plan's 11.2 - the light wall's own, where it
    // went 1500 ms after the torch was lit: at its node (64, 240), its -4, turned
    // by it (-1.5708 in the .tscn, the original's +90) and at 1.
    MagicPortalsLayer::EffectReport dust;
    MagicPortalsLayer::EffectReport lightWall;
    int lightWalls = 0;
    for (const MagicPortalsLayer::EffectReport& report : EffectsOf(layer, "wall_destroy.ent")) {
        if (report.atPx == glm::dvec2(32.0, 128.0)) {
            dust = report;
            ++count;
        } else {
            lightWall = report;
            ++lightWalls;
        }
    }
    CHECK_MSG(lightWalls == 1 && lightWall.atPx == glm::dvec2(64.0, 240.0) && nearlyU(lightWall.zUnits, -4.0) &&
                  nearlyU(lightWall.angleDeg, 90.0, 1e-3) && lightWall.scriptScale == 1.0,
              "4-32: the light wall's dust at its node, -4, turned 90, at 1: " + Point(lightWall.atPx) + " angle " +
                  std::to_string(lightWall.angleDeg));
    std::printf("  4-32: %s gone on tick %d: wall_destroy at %s z %.1f x%.1f, sizes %.1f and %.1f\n",
                wallNode.c_str(), arrived.tick, Point(dust.atPx).c_str(), dust.zUnits, dust.scriptScale,
                dust.systemSizePx.empty() ? 0.0 : dust.systemSizePx[0],
                dust.systemSizePx.size() < 2 ? 0.0 : dust.systemSizePx[1]);
    CHECK_MSG(count == 1 && dust.atPx == glm::dvec2(32.0, 128.0) && nearlyU(dust.zUnits, -2.0) &&
                  dust.angleDeg == 0.0f && dust.scriptScale == 2.0,
              "4-32: one wall_destroy at 2217's node, its -2, unturned, at 2: " + Point(dust.atPx) + " x" +
                  std::to_string(dust.scriptScale));
    CHECK_MSG(dust.systemSizePx.size() == 2 && nearlyU(dust.systemSizePx[0], 38.0) &&
                  nearlyU(dust.systemSizePx[1], 120.0) && dust.pool == 22 + 10,
              "4-32: dirt at 38 and smoke at 120 - twice 19 and 60");
    int read = 0;
    const glm::dvec2 spread = QuadSpreadPx(registry, dust, read);
    CHECK_MSG(read == 32 && spread.y > 120.0 && spread.y <= 204.0 + 12.0 && spread.x < 14.0,
              "4-32: its line twice as long, down the screen: " + std::to_string(spread.y) + " down, " +
                  std::to_string(spread.x) + " across");
    layer.OnDetach(registry);
}

// A destroyable stone that breaks a wall (planning step 175), on 1-13 (level12): its stone is one of the twelve a level places
// with `destroyable` 1, and ETHBeginContactCallback_breakable_wall #42-60 destroys it with the wall (the first it breaks). On the
// tick nothing is added; on the frame one rolling_stone_destroy where the step left it, at depth 32 and 1.3 - and the wall's own
// wall_destroy - and the stone is gone from the level: no body, no picture, no stone the demolisher or the portals hold.
void ADestroyableStoneThatBreaksAWallLeavesItsPuffAndIsGone() {
    if (!OriginalArtIsThere("ADestroyableStoneThatBreaksAWallLeavesItsPuffAndIsGone")) return;
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level12");
    layer.OnAttach(registry);
    CHECK_MSG(layer.SimLevel() != nullptr && layer.ArtError().empty(), layer.LoadError() + layer.ArtError());
    if (layer.SimLevel() == nullptr || !layer.ArtError().empty()) return;
    CHECK_MSG(layer.SimLevel()->demolish.stones.size() == 1 && layer.SimLevel()->demolish.stones.front().destroyable,
              "1-13's one stone is destroyable");
    if (layer.SimLevel()->demolish.stones.size() != 1) return;
    CloseTheLevelStartPopup(layer, registry);
    for (int tick = 0; tick < 3; ++tick) {
        tickWith(layer, registry, kRest, {}, {});
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    }
    const std::string name = layer.SimLevel()->demolish.stones.front().name;
    const entt::entity stone = layer.SimLevel()->demolish.stones.front().body;
    // Thrown down at its lying wall from 20 px short, at 300 carried px/s (150 of the original's: above the gate's 75).
    auto& transform = registry.get<TransformComponent>(stone);
    const glm::vec3 at = MagicPortals::Units::ToWorld(192.0, 282.0 - 16.0 - 30.0 - 20.0);
    transform.position = glm::vec3(at.x, at.y, transform.position.z);
    registry.get<RigidBodyComponent>(stone).velocity = glm::vec3(0.0f, -MagicPortals::Units::ToMetres(300.0), 0.0f);
    int spawnedBefore = layer.EffectsSpawned();
    bool broke = false;
    for (int tick = 0; tick < 40 && !broke; ++tick) {
        spawnedBefore = layer.EffectsSpawned();
        tickWith(layer, registry, kRest, {}, {});
        broke = layer.SimLevel()->demolish.Broken() == 1;
        if (!broke) layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    }
    CHECK_MSG(broke, "the stone breaks 1-13's wall");
    if (!broke) return;
    const MagicPortals::Demolish::State& demolish = layer.SimLevel()->demolish;
    CHECK_MSG(demolish.takenNow.size() == 1 && demolish.takenNow.front().stone.name == name,
              "and the wall takes it: " + std::to_string(demolish.takenNow.size()));
    if (demolish.takenNow.size() != 1) return;
    const MagicPortals::Demolish::Taken gone = demolish.takenNow.front();
    CHECK_MSG(!registry.valid(stone) && demolish.stones.empty() && demolish.FindStone(name) != nullptr,
              "its body is gone and the level holds no stone - but the tick's latches can still name it");
    CHECK_MSG(demolish.contactsNow.size() == 1 && demolish.contactsNow.front().broke && demolish.contactsNow.front().stoneDied &&
                  demolish.contactsNow.front().speedMs > demolish.rules.wallBreaksAboveMs,
              "one begin, above the gate, the stone destroyed");
    int count = 0;
    FirstEffect(layer, "rolling_stone_destroy.ent", count);
    CHECK_MSG(layer.EffectsSpawned() == spawnedBefore && count == 0, "nothing is added on the tick");
    layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    const MagicPortalsLayer::EffectReport puff = FirstEffect(layer, "rolling_stone_destroy.ent", count);
    std::printf("  1-13: %s destroyed by the wall it broke: rolling_stone_destroy at %s z %.1f x%.2f\n", name.c_str(),
                Point(puff.atPx).c_str(), puff.zUnits, puff.scriptScale);
    CHECK_MSG(count == 1 && puff.atPx == gone.atPx && nearlyU(puff.zUnits, 32.0) && nearlyU(puff.scriptScale, 1.3),
              "one rolling_stone_destroy at the stone " + Point(gone.atPx) + ", z 32, x1.3: " + Point(puff.atPx) + " z " +
                  std::to_string(puff.zUnits));
    int wallDust = 0;
    FirstEffect(layer, "wall_destroy.ent", wallDust);
    CHECK_MSG(wallDust == 1, "and the wall's own dust: " + std::to_string(wallDust));
    // Nothing of it stays: a later tick has no taken stone, and no stone for the portals to carry.
    tickWith(layer, registry, kRest, {}, {});
    CHECK_MSG(layer.SimLevel()->demolish.takenNow.empty() && layer.SimLevel()->demolish.stones.empty(), "gone for good");
    layer.OnDetach(registry);
}

// A thrown stone a despawner takes, on 1-24 (level23) left to run: on the tick
// nothing is added; on the frame one rolling_stone_destroy where the step left it
// (Launchers' record), at a depth of its own, 32, and at 1.3 - two smoke puffs at
// 68 x 1.3. The thrower's entity is rolling_stone.ent, the entity whose callback
// adds it; so is the beholder's rock (test_mp_boss pins boss.json's).
void AStoneADespawnerTakesLeavesItsPuff() {
    if (!OriginalArtIsThere("AStoneADespawnerTakesLeavesItsPuff")) return;
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level23");
    layer.OnAttach(registry);
    CHECK_MSG(layer.SimLevel() != nullptr && layer.ArtError().empty(), layer.LoadError() + layer.ArtError());
    if (layer.SimLevel() == nullptr || !layer.ArtError().empty()) return;
    CHECK_MSG(layer.SimLevel()->launchers.launchers.size() == 1 &&
                  layer.SimLevel()->launchers.launchers.front().entity == "rolling_stone.ent",
              "1-24 throws rolling_stone.ent");
    CloseTheLevelStartPopup(layer, registry);
    int spawnedBefore = layer.EffectsSpawned();
    int tick = 0;
    bool taken = false;
    for (; tick < 400 && !taken; ++tick) {
        spawnedBefore = layer.EffectsSpawned();
        tickWith(layer, registry, kRest, {}, {});
        taken = layer.SimLevel()->launchers.despawned > 0;
        if (!taken) layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    }
    CHECK_MSG(taken && layer.SimLevel()->launchers.despawnedNow.size() == 1,
              "a despawner takes a stone within 400 ticks");
    if (!taken || layer.SimLevel()->launchers.despawnedNow.size() != 1) return;
    const MagicPortals::Launchers::StoneGone gone = layer.SimLevel()->launchers.despawnedNow.front();
    {
        // Its sound on that tick: playStoneHitSound(1) (ETHBeginContactCallback_rolling_stone
        // #91-94; planning step 142), at its argument's volume, 1.
        const std::vector<std::string> sounds = layer.LatchedSounds();
        const std::vector<double> volumes = layer.LatchedVolumes();
        int broken = 0;
        for (std::size_t i = 0; i < sounds.size() && i < volumes.size(); ++i) {
            if (sounds[i] == "stone_broken" && volumes[i] == 1.0) ++broken;
        }
        CHECK_MSG(broken == 1, "stone_broken at volume 1 on the tick: " + std::to_string(broken));
        CHECK_MSG(std::count(sounds.begin(), sounds.end(), std::string("stone_thrown")) == 0,
                  "and no launcher's throw is ever heard: ETHCallback_entity_launcher calls no audio");
    }
    int count = 0;
    FirstEffect(layer, "rolling_stone_destroy.ent", count);
    CHECK_MSG(layer.EffectsSpawned() == spawnedBefore && count == 0, "nothing is added on the tick");
    layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    const MagicPortalsLayer::EffectReport puff = FirstEffect(layer, "rolling_stone_destroy.ent", count);
    std::printf("  1-24: %s taken by the destroyier on tick %d: rolling_stone_destroy at %s z %.1f x%.2f, %d at "
                "%.2f\n",
                gone.name.c_str(), tick, Point(puff.atPx).c_str(), puff.zUnits, puff.scriptScale, puff.pool,
                puff.systemSizePx.empty() ? 0.0 : puff.systemSizePx[0]);
    CHECK_MSG(count == 1 && puff.atPx == gone.atPx && nearlyU(puff.zUnits, 32.0) && nearlyU(puff.scriptScale, 1.3) &&
                  puff.angleDeg == 0.0f,
              "one rolling_stone_destroy at the stone " + Point(gone.atPx) + ", z 32, x1.3: " + Point(puff.atPx) +
                  " z " + std::to_string(puff.zUnits));
    CHECK_MSG(!puff.drawn && !puff.hasLight && puff.temporary && puff.systems == 1 && puff.pool == 2 &&
                  puff.systemSizePx.size() == 1 && nearlyU(puff.systemSizePx[0], 68.0 * 1.3) &&
                  puff.systemZ[0] > layer.PlayerSlotZ(),
              "two smoke at 88.4, temporary, in front of the player");
    const Burnt burnt = BurnDown(layer, registry, puff.id, 120);
    CHECK_MSG(burnt.freedOn >= 50 && burnt.freedOn <= 66 && burnt.freed >= 1,
              "freed by its pools, 950 +- 100 ms: frame " + std::to_string(burnt.freedOn));
    layer.OnDetach(registry);
}

// 3-15 (level14b) left to run: step 76's knight on button_1656 opens a switched
// door and later lets it close (step 101's ticks). On each turn nothing is added
// on the tick; on the frame one door_lift_particles at the door's point where the
// tick BEGAN - the watch's progress, not the one BeforeStep has just stepped -
// half its 128 up as it opens (the shut door's top edge) and half down as it
// closes (the raised door's bottom edge), unturned, on its depth.
void ALiftDoorLeavesItsDustAsItOpensAndCloses() {
    if (!OriginalArtIsThere("ALiftDoorLeavesItsDustAsItOpensAndCloses")) return;
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level14b");
    layer.OnAttach(registry);
    CHECK_MSG(layer.SimLevel() != nullptr && layer.ArtError().empty(), layer.LoadError() + layer.ArtError());
    if (layer.SimLevel() == nullptr || !layer.ArtError().empty()) return;
    CHECK(!layer.SimLevel()->channels.doors.empty());
    CloseTheLevelStartPopup(layer, registry);
    int tick = 0;
    std::vector<int> seenIds;
    for (const bool opening : {true, false}) {
        const std::string what = opening ? "opening" : "closing";
        std::size_t turned = 0;
        float fromProgress = 0.0f;
        int spawnedBefore = layer.EffectsSpawned();
        bool found = false;
        for (int n = 0; n < 600 && !found; ++n) {
            const auto& doors = layer.SimLevel()->channels.doors;
            std::vector<char> was;
            std::vector<float> progress;
            for (const auto& door : doors) {
                was.push_back(door.motion.opening ? char{1} : char{0});
                progress.push_back(door.motion.progress);
            }
            spawnedBefore = layer.EffectsSpawned();
            tickWith(layer, registry, kRest, {}, {});
            ++tick;
            for (std::size_t i = 0; i < doors.size() && !found; ++i) {
                if ((doors[i].motion.opening ? char{1} : char{0}) == was[i]) continue;
                CHECK_MSG(doors[i].motion.opening == opening, "the first turn after the last is the " + what);
                found = true;
                turned = i;
                fromProgress = progress[i];
            }
            if (!found) layer.OnUpdate(registry, MagicPortalsLayer::kTick);
        }
        CHECK_MSG(found, "3-15: a door starts " + what);
        if (!found) return;
        const MagicPortals::Puzzle::SwitchedDoor& door = layer.SimLevel()->channels.doors[turned];
        CHECK_MSG(layer.EffectsSpawned() == spawnedBefore, "3-15: nothing is added on the tick the door starts " + what);
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
        CHECK_MSG(layer.EffectsSpawned() == spawnedBefore + 1, "3-15: one added on the frame");
        MagicPortalsLayer::EffectReport dust;
        for (const MagicPortalsLayer::EffectReport& report : layer.EffectReports()) {
            if (report.entity == "door_lift_particles.ent" &&
                std::find(seenIds.begin(), seenIds.end(), report.id) == seenIds.end()) {
                dust = report;
            }
        }
        CHECK_MSG(dust.id != 0, "3-15: the door's " + what + " dust");
        if (dust.id == 0) return;
        seenIds.push_back(dust.id);
        const glm::dvec2 from =
            MagicPortals::Units::ToPixels(glm::mix(door.motion.closed, door.motion.open, fromProgress));
        const double wantDy = opening ? -64.0 : 64.0;
        std::printf("  3-15: %s %s on tick %d from %s (progress %.4f): door_lift_particles at %s z %.4f, %d at %.1f\n",
                    door.name.c_str(), what.c_str(), tick, Point(from).c_str(), static_cast<double>(fromProgress),
                    Point(dust.atPx).c_str(), dust.zUnits, dust.pool,
                    dust.systemSizePx.empty() ? 0.0 : dust.systemSizePx[0]);
        CHECK_MSG(std::fabs(dust.atPx.x - from.x) < 1e-3 && std::fabs(dust.atPx.y - from.y - wantDy) < 1e-3,
                  "3-15: at the door's point where the tick began, " + std::to_string(wantDy) + " down: " +
                      Point(dust.atPx) + " against " + Point(from));
        // And where that is, absolutely (step 133's verifier, done in planning step
        // 146): door_lift_1677 shut at y 32, so the opening dust at 32 - 64, and the
        // closing dust at the raised door's 32 - RisePx() (0.8 x 128 = 102.4) + 64.
        const double rise = layer.SimLevel()->channels.doorRules.RisePx();
        const double wantY = opening ? 32.0 - 64.0 : 32.0 - rise + 64.0;
        CHECK_MSG(NearD(rise, 102.4, 1e-9) && std::fabs(dust.atPx.x - 430.0) < 1e-3 &&
                      std::fabs(dust.atPx.y - wantY) < 1e-3,
                  "3-15: the " + what + " dust at (430, " + std::to_string(wantY) + "): " + Point(dust.atPx));
        CHECK_MSG(opening ? fromProgress == 0.0f : fromProgress == 1.0f,
                  "3-15: the door " + std::string(opening ? "shut" : "fully raised") + " as it turns: " +
                      std::to_string(fromProgress));
        // door_lift_1677 (430, 32), channel 1, which carries no eth_z: its depth 0.
        CHECK_MSG(door.name == "door_lift_1677" && nearlyU(dust.zUnits, 0.0) && dust.angleDeg == 0.0f &&
                      dust.scriptScale == 1.0,
                  "3-15: door_lift_1677's, on its 0, unturned, x1: " + door.name + " z " +
                      std::to_string(dust.zUnits));
        CHECK_MSG(!dust.drawn && !dust.hasLight && dust.temporary && dust.systems == 1 && dust.pool == 22 &&
                      dust.systemSizePx.size() == 1 && nearlyU(dust.systemSizePx[0], 18.0) &&
                      dust.systemZ[0] < layer.PlayerSlotZ(),
                  "3-15: 22 dirt at 18, temporary, on the door's depth behind the player");
        // Its specks start at alpha 0 (Color0), which draws nothing, so they are
        // read six frames on: along the edge, RandStartPoint (24, 0), each moved by
        // at most its RandomizeDir (1, 0.6) and gravity's 0.03 a frame since.
        for (int frame = 0; frame < 6; ++frame) layer.OnUpdate(registry, MagicPortalsLayer::kTick);
        int read = 0;
        const glm::dvec2 spread = QuadSpreadPx(registry, ByIdIn(layer.EffectReports(), dust.id), read);
        CHECK_MSG(read == 22 && spread.x > 12.0 && spread.x <= 24.0 + 7.0 && spread.y < 5.0,
                  "3-15: its specks along the edge six frames on: " + std::to_string(spread.x) + " across, " +
                      std::to_string(spread.y) + " down, " + std::to_string(read) + " read");
    }
    layer.OnDetach(registry);
}

// ---- The shock rings (the visuals plan's 13.1, step 111) ---------------------
//
// shock_area.ent, which each shock agent adds round itself on its first frame (art.json
// shock_ring; decode D6 and its check): at the field's point, the lethal diameter
// across, (0.4, 0.5, 0.5) added, at the ABSOLUTE depth -10; turned 20 degrees a second
// of game time, which a pause holds; and scaled every frame by a fresh factor in
// [0.993, 1.007] about that diameter, which a pause does not hold.

const MagicPortalsLayer::ShockRingReport* RingOf(const std::vector<MagicPortalsLayer::ShockRingReport>& rings,
                                                 const std::string& field) {
    for (const MagicPortalsLayer::ShockRingReport& ring : rings) {
        if (ring.field == field) return &ring;
    }
    return nullptr;
}

// How many of the level's own pictures stand behind and in front of a depth.
void PicturesAbout(entt::registry& registry, float z, int& behind, int& inFront) {
    behind = 0;
    inFront = 0;
    for (auto [entity, tag, transform] : registry.view<TagComponent, TransformComponent>().each()) {
        (void)entity;
        if (tag.tag != "Magic Portals Sprite") continue;
        if (transform.position.z < z) ++behind;
        if (transform.position.z > z) ++inFront;
    }
}

void AShockAgentWearsItsRing() {
    if (!OriginalArtIsThere("AShockAgentWearsItsRing")) return;
    // 3-24 (level23b): agent 2048 at (320, 44), areaRadius 80, and 2023 at (256, 192),
    // areaRadius 60 - the two rings the gate reads against the library's h6.3.
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level23b");
    layer.OnAttach(registry);
    CHECK_MSG(layer.SimLevel() != nullptr && layer.ArtError().empty(), layer.LoadError() + layer.ArtError());
    if (layer.SimLevel() == nullptr || !layer.ArtError().empty()) return;
    CloseTheLevelStartPopup(layer, registry);
    tickWith(layer, registry, kRest, {}, {});
    layer.OnUpdate(registry, MagicPortalsLayer::kTick);

    const std::vector<MagicPortalsLayer::ShockRingReport> rings = layer.ShockRings();
    CHECK_EQ(rings.size(), std::size_t{2});
    CHECK_EQ(Tagged(registry, "Magic Portals Shock Ring"), 2);
    const struct Want {
        const char* field;
        glm::dvec2 atPx;
        double radius;
    } wants[] = {{"shock_agent_2048", {320.0, 44.0}, 80.0}, {"shock_agent_2023", {256.0, 192.0}, 60.0}};
    float ringZ = 0.0f;
    for (const Want& want : wants) {
        const MagicPortalsLayer::ShockRingReport* ring = RingOf(rings, want.field);
        CHECK_MSG(ring != nullptr && ring->quad != entt::null && registry.valid(ring->quad),
                  std::string(want.field) + " wears a ring");
        if (ring == nullptr || ring->quad == entt::null || !registry.valid(ring->quad)) continue;
        const auto& transform = registry.get<TransformComponent>(ring->quad);
        const auto& material = registry.get<MaterialComponent>(ring->quad);
        // Its .ent's picture, as the original's loader picks its tier: hd/white_ring.png.
        CHECK_MSG(EndsWith(material.albedoTexturePath, "/entities/hd/white_ring.png"),
                  std::string(want.field) + ": hd/white_ring.png, not " + material.albedoTexturePath);
        CHECK_MSG(material.blend == MaterialComponent::BlendMode::Additive && ring->additive,
                  std::string(want.field) + "'s ring is added (blendMode 1)");
        CHECK_MSG(material.albedoColor == glm::vec4(0.4f, 0.5f, 0.5f, 1.0f),
                  std::string(want.field) + "'s ring is (0.4, 0.5, 0.5), not (" +
                      std::to_string(material.albedoColor.r) + ", " + std::to_string(material.albedoColor.g) + ", " +
                      std::to_string(material.albedoColor.b) + ", " + std::to_string(material.albedoColor.a) + ")");
        CHECK_MSG(ring->atPx == want.atPx &&
                      glm::distance(MagicPortals::Units::ToPixels(transform.position), want.atPx) < 1e-3,
                  std::string(want.field) + "'s ring at its field's point " + Point(want.atPx) + ": " +
                      Point(ring->atPx));
        CHECK_MSG(ring->baseUnits == want.radius * 2.0, std::string(want.field) + ": the lethal diameter, " +
                                                             std::to_string(ring->baseUnits));
        CHECK_MSG(ring->jitters == 1 && ring->jitter >= 0.993 && ring->jitter <= 1.007,
                  std::string(want.field) + ": one frame's factor, in [0.993, 1.007]: " +
                      std::to_string(ring->jitter));
        const float across = MagicPortals::Units::ToMetres(ring->baseUnits * ring->jitter);
        CHECK_MSG(std::fabs(transform.scale.x - across) < 1e-6f && transform.scale.y == transform.scale.x,
                  std::string(want.field) + " is drawn its diameter times the factor, both ways");
        CHECK_MSG(ring->lookZ == -10.0, std::string(want.field) + ": at the absolute -10, not " +
                                            std::to_string(ring->lookZ));
        ringZ = ring->z;
    }

    // AFTER THE ART AT OR BELOW -10 AND BEFORE THE NEXT: 3-24's sky (-70), arch and
    // wall (-20), doorway (-19), door (-18) and orange light (-14) behind it, and the
    // platforms, the agents and everything else in front - a slot's 0.53125 before the
    // first of them, the table's own fraction.
    int behind = 0;
    int inFront = 0;
    PicturesAbout(registry, ringZ, behind, inFront);
    CHECK_MSG(behind == 6, "3-24: 6 pictures behind the rings, " + std::to_string(behind));
    float agentZ = 0.0f;
    for (auto [entity, tag, material, transform] :
         registry.view<TagComponent, MaterialComponent, TransformComponent>().each()) {
        (void)entity;
        if (tag.tag == "Magic Portals Sprite" && EndsWith(material.albedoTexturePath, "/shock_agent.png")) {
            agentZ = transform.position.z;
        }
    }
    CHECK_MSG(agentZ > ringZ, "and the agent's own picture in front of its ring");
    std::printf("  3-24: two rings at z %.6f, %d pictures behind and %d in front\n", static_cast<double>(ringZ),
                behind, inFront);
    layer.OnDetach(registry);

    // 4-07 (level6c): a ring on a dark weightless level with a door glow at -22, whose
    // picture is pushed into m_sprites after the rings are resolved - counted, it would
    // put the ring a slot too deep. Behind it: the sky (-100), the spiral (-96), the
    // planet (-90), the doorway (-19), the door (-14), the antiportal (-12), and the
    // button, the lift door and the button at -10, which it is drawn over (at or below).
    entt::registry dark;
    publishViewport(dark);
    MagicPortalsLayer level6c(TestPaths(), "level6c");
    level6c.OnAttach(dark);
    CHECK_MSG(level6c.SimLevel() != nullptr && level6c.ArtError().empty(), level6c.LoadError() + level6c.ArtError());
    if (level6c.SimLevel() == nullptr || !level6c.ArtError().empty()) return;
    CloseTheLevelStartPopup(level6c, dark);
    tickWith(level6c, dark, kRest, {}, {});
    level6c.OnUpdate(dark, MagicPortalsLayer::kTick);
    const std::vector<MagicPortalsLayer::ShockRingReport> darkRings = level6c.ShockRings();
    CHECK_EQ(darkRings.size(), std::size_t{1});
    CHECK_EQ(Tagged(dark, "Magic Portals Door Highlight"), 1);
    if (darkRings.size() == 1 && darkRings[0].quad != entt::null) {
        PicturesAbout(dark, darkRings[0].z, behind, inFront);
        CHECK_MSG(behind == 9, "4-07: 9 pictures behind the ring, the door glow not counted: " +
                                   std::to_string(behind));
        const entt::entity glow = FirstTagged(dark, "Magic Portals Door Highlight");
        CHECK_MSG(glow != entt::null && dark.get<TransformComponent>(glow).position.z < darkRings[0].z,
                  "the glow at -22 behind the ring at -10");
        CHECK_MSG(dark.get<MaterialComponent>(darkRings[0].quad).albedoColor == glm::vec4(0.4f, 0.5f, 0.5f, 1.0f),
                  "the ring's own colour on a dark level: emissive 1 takes no ambient");
        std::printf("  4-07: one ring at z %.6f, %d pictures behind and %d in front\n",
                    static_cast<double>(darkRings[0].z), behind, inFront);
    }
    level6c.OnDetach(dark);

    // A level with no shock agent has no ring.
    entt::registry none;
    publishViewport(none);
    MagicPortalsLayer plain(TestPaths(), "level0");
    plain.OnAttach(none);
    CHECK_EQ(Tagged(none, "Magic Portals Shock Ring"), 0);
    CHECK(plain.ShockRings().empty());
    plain.OnDetach(none);
}

// THE TWO CLOCKS (00_order 8.13's 13.1 row, D6_check section 5.5): the turn is game
// time - 20 degrees a second, stepped on the tick, held by a pause - and the scale is
// the frame's - a fresh factor in [0.993, 1.007] about the fixed base every frame,
// the pause or not.
void AShockRingTurnsOnGameTimeAndJittersEveryFrame() {
    if (!OriginalArtIsThere("AShockRingTurnsOnGameTimeAndJittersEveryFrame")) return;
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level23b");
    layer.OnAttach(registry);
    CHECK_MSG(layer.SimLevel() != nullptr && layer.ArtError().empty(), layer.LoadError() + layer.ArtError());
    if (layer.SimLevel() == nullptr || !layer.ArtError().empty()) return;
    CloseTheLevelStartPopup(layer, registry);
    tickWith(layer, registry, kRest, {}, {});
    layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    const auto read = [&layer]() {
        const std::vector<MagicPortalsLayer::ShockRingReport> rings = layer.ShockRings();
        const MagicPortalsLayer::ShockRingReport* ring = RingOf(rings, "shock_agent_2048");
        return ring != nullptr ? *ring : MagicPortalsLayer::ShockRingReport{};
    };
    const MagicPortalsLayer::ShockRingReport first = read();
    CHECK_MSG(first.quad != entt::null, "3-24's upper ring is there");
    if (first.quad == entt::null) return;
    const entt::entity quad = first.quad;
    const double base = first.baseUnits;
    // unitsPerSecond(20) over one tick, as Motion::Advance takes it: 20 x frame ms / 1000.
    const double stepDeg = 20.0 * (kScriptMs) / 1000.0;
    int turnWrong = 0;
    int drawnWrong = 0;
    int outside = 0;
    int repeated = 0;
    double lo = 2.0;
    double hi = 0.0;
    double sum = 0.0;
    int frames = 0;
    MagicPortalsLayer::ShockRingReport last = read();
    for (int tick = 0; tick < 400; ++tick) {
        tickWith(layer, registry, kRest, {}, {});
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
        const MagicPortalsLayer::ShockRingReport now = read();
        // One step a tick, counter-clockwise, which the engine's +z is.
        if (std::fabs(now.turnedDeg - (last.turnedDeg + stepDeg)) > 1e-9) ++turnWrong;
        const auto& transform = registry.get<TransformComponent>(quad);
        const float turnedRad = static_cast<float>(now.turnedDeg * 3.14159265358979323846 / 180.0);
        // Drawn at the base times THIS frame's factor: never the last frame's times it.
        if (std::fabs(transform.rotation.z - turnedRad) > 1e-5f ||
            std::fabs(transform.scale.x - MagicPortals::Units::ToMetres(base * now.jitter)) > 1e-6f ||
            now.baseUnits != base || now.jitters != last.jitters + 1) {
            ++drawnWrong;
        }
        if (now.jitter < 0.993 || now.jitter > 1.007) ++outside;
        if (now.jitter == last.jitter) ++repeated;
        lo = std::min(lo, now.jitter);
        hi = std::max(hi, now.jitter);
        sum += now.jitter;
        ++frames;
        last = now;
    }
    const double mean = sum / frames;
    CHECK_MSG(turnWrong == 0, "20 degrees a second, one step a tick: " + std::to_string(turnWrong) + " ticks wrong");
    CHECK_MSG(std::fabs(last.turnedDeg - first.turnedDeg - 400.0 * stepDeg) < 1e-6,
              "133.3 degrees in 400 ticks: " + std::to_string(last.turnedDeg - first.turnedDeg));
    CHECK_MSG(drawnWrong == 0, "every frame drawn at its turn and at base x its own factor: " +
                                   std::to_string(drawnWrong) + " wrong");
    CHECK_MSG(outside == 0 && repeated == 0,
              "400 factors in [0.993, 1.007], each fresh: " + std::to_string(outside) + " outside, " +
                  std::to_string(repeated) + " repeated");
    CHECK_MSG(lo < 0.9935 && hi > 1.0065 && std::fabs(mean - 1.0) < 0.001,
              "spread over the whole range about the base, no drift: " + std::to_string(lo) + " to " +
                  std::to_string(hi) + ", mean " + std::to_string(mean));

    // A PAUSE HOLDS THE TURN AND NOT THE JITTER.
    press(layer, registry, MagicPortalsLayer::kBack);
    CHECK_MSG(layer.Paused(), "Escape pauses 3-24");
    layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    const MagicPortalsLayer::ShockRingReport held = read();
    int pausedTurned = 0;
    int pausedHeld = 0;
    int pausedWrong = 0;
    last = held;
    for (int frame = 0; frame < 60; ++frame) {
        tickWith(layer, registry, kRest, {}, {});
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
        const MagicPortalsLayer::ShockRingReport now = read();
        if (now.turnedDeg != held.turnedDeg) ++pausedTurned;
        if (now.jitter == last.jitter || now.jitters != last.jitters + 1) ++pausedHeld;
        const auto& transform = registry.get<TransformComponent>(quad);
        if (now.jitter < 0.993 || now.jitter > 1.007 ||
            std::fabs(transform.scale.x - MagicPortals::Units::ToMetres(base * now.jitter)) > 1e-6f) {
            ++pausedWrong;
        }
        last = now;
    }
    CHECK_MSG(pausedTurned == 0, "the pause holds the turn: " + std::to_string(pausedTurned) + " frames turned");
    CHECK_MSG(pausedHeld == 0, "and not the jitter: a fresh factor every paused frame, " +
                                   std::to_string(pausedHeld) + " held");
    CHECK_MSG(pausedWrong == 0, "each in [0.993, 1.007] about the base: " + std::to_string(pausedWrong) + " wrong");
    press(layer, registry, MagicPortalsLayer::kBack);
    CHECK_MSG(!layer.Paused(), "and Escape again resumes it");
    tickWith(layer, registry, kRest, {}, {});
    layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    CHECK_MSG(read().turnedDeg > held.turnedDeg, "and the turn goes on");
    std::printf("  3-24: 400 ticks turned %.4f degrees; factors %.5f to %.5f, mean %.5f; 60 paused frames: "
                "the turn held, 60 fresh factors\n",
                last.turnedDeg - first.turnedDeg, lo, hi, mean);
    layer.OnDetach(registry);
}

// 3-28's (level27b) swinging ring is where its field is, as the area's own
// linearMotion puts it: the ring IS the lethal centre Fields moves.
void AMovingShockRingIsWhereItsFieldIs() {
    if (!OriginalArtIsThere("AMovingShockRingIsWhereItsFieldIs")) return;
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level27b");
    layer.OnAttach(registry);
    CHECK_MSG(layer.SimLevel() != nullptr && layer.ArtError().empty(), layer.LoadError() + layer.ArtError());
    if (layer.SimLevel() == nullptr || !layer.ArtError().empty()) return;
    CloseTheLevelStartPopup(layer, registry);
    CHECK_EQ(layer.ShockRings().size(), std::size_t{3});
    int wrong = 0;
    double travel = 0.0;
    for (int tick = 0; tick < 90; ++tick) {
        tickWith(layer, registry, kRest, {}, {});
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
        const MagicPortals::Fields::Field* field = layer.SimLevel()->fields.FindField("shock_agent_2128");
        const std::vector<MagicPortalsLayer::ShockRingReport> rings = layer.ShockRings();
        const MagicPortalsLayer::ShockRingReport* ring = RingOf(rings, "shock_agent_2128");
        if (field == nullptr || ring == nullptr || ring->quad == entt::null) {
            ++wrong;
            continue;
        }
        const glm::dvec2 drawn = MagicPortals::Units::ToPixels(registry.get<TransformComponent>(ring->quad).position);
        if (ring->atPx != field->atPx || glm::distance(drawn, field->atPx) > 1e-3) ++wrong;
        travel = std::max(travel, std::fabs(field->atPx.y - field->centrePx.y));
    }
    CHECK_MSG(wrong == 0, "the ring at its field's point every tick: " + std::to_string(wrong) + " wrong");
    CHECK_MSG(travel > 60.0, "and the field swings its stride of 64: " + std::to_string(travel));
    layer.OnDetach(registry);
}

// K8 (the inherited reading): the rings' factors come off the effects' stream and
// the level's own particles are untouched by them. Two layers on 3-24 draw the same
// until one of them spawns an effect, which takes draws off that stream: its rings'
// factors part from the other's from then on, and the level's emitters never do.
void AShockRingsJitterIsTheEffectsStreamsAlone() {
    if (!OriginalArtIsThere("AShockRingsJitterIsTheEffectsStreamsAlone")) return;
    entt::registry plain;
    entt::registry withEffect;
    publishViewport(plain);
    publishViewport(withEffect);
    MagicPortalsLayer a(TestPaths(), "level23b");
    MagicPortalsLayer b(TestPaths(), "level23b");
    a.OnAttach(plain);
    b.OnAttach(withEffect);
    CHECK_MSG(a.SimLevel() != nullptr && a.ArtError().empty(), a.LoadError() + a.ArtError());
    if (a.SimLevel() == nullptr || !a.ArtError().empty()) return;
    CloseTheLevelStartPopup(a, plain);
    CloseTheLevelStartPopup(b, withEffect);
    int emittersDiffered = 0;
    int compared = 0;
    int ringsApartBefore = 0;
    int ringsApartAfter = 0;
    for (int frame = 0; frame < 120; ++frame) {
        tickWith(a, plain, kRest, {}, {});
        tickWith(b, withEffect, kRest, {}, {});
        a.OnUpdate(plain, MagicPortalsLayer::kTick);
        b.OnUpdate(withEffect, MagicPortalsLayer::kTick);
        if (frame == 20) {
            MagicPortalsLayer::EffectSpawn spawn;
            spawn.entity = "sparkles.ent";
            spawn.atPx = glm::dvec2(300.0, 100.0);
            spawn.zUnits = 32.0;
            CHECK(b.SpawnEffect(withEffect, spawn) > 0);
        }
        const std::vector<MagicPortalsLayer::EmitterReport> left = a.EmitterReports();
        const std::vector<MagicPortalsLayer::EmitterReport> right = b.EmitterReports();
        if (left.size() != right.size()) {
            ++emittersDiffered;
        } else {
            for (std::size_t i = 0; i < left.size(); ++i) {
                ++compared;
                if (left[i].node != right[i].node || left[i].active != right[i].active ||
                    left[i].drawn != right[i].drawn || left[i].newestBornPx != right[i].newestBornPx ||
                    left[i].newestAgeMs != right[i].newestAgeMs) {
                    ++emittersDiffered;
                }
            }
        }
        const std::vector<MagicPortalsLayer::ShockRingReport> ringsA = a.ShockRings();
        const std::vector<MagicPortalsLayer::ShockRingReport> ringsB = b.ShockRings();
        bool apart = ringsA.size() != ringsB.size();
        for (std::size_t i = 0; !apart && i < ringsA.size(); ++i) apart = ringsA[i].jitter != ringsB[i].jitter;
        if (apart) ++(frame <= 20 ? ringsApartBefore : ringsApartAfter);
    }
    // 3-24's six systems of its own - the two agents' lightning among them - over 120 frames.
    CHECK_MSG(compared == 6 * 120, "the level's emitters were compared: " + std::to_string(compared));
    CHECK_MSG(emittersDiffered == 0, "the rings' draws move no particle of the level's own: " +
                                         std::to_string(emittersDiffered) + " reading(s) differ");
    CHECK_MSG(ringsApartBefore == 0, "the two layers' rings draw alike until the effect: " +
                                         std::to_string(ringsApartBefore) + " frames apart");
    CHECK_MSG(ringsApartAfter > 90, "and part once it has taken draws off the same stream: " +
                                        std::to_string(ringsApartAfter) + " of 99 frames apart");
    std::printf("  K8 (13.1): %d emitter readings the same; ring factors apart on %d of the 99 frames after an "
                "effect\n",
                compared, ringsApartAfter);
    a.OnDetach(plain);
    b.OnDetach(withEffect);
}

// ---- The music as the original plays it (the program's P7, planning step 121) ----
//
// WantedTrack is AudioManager.currentTrack and its one MediaPlayer as the
// original's calls leave them, with or without a device: Game::preLoop's
// playGameMusic(isBossFight) or, on a no_music level, turnMusicOff (#485-509);
// PortalMainMenu::preLoop's playMenuMusic (#368), and no call at all on chapter or
// level select; the bosses' own starts and stops; and a switch turned back on
// resuming currentTrack (resumeMusic).

// The data the rule reads: the four levels whose `properties` carry no_music, and
// every world 32 levels long, so that m_levelIndex == 31 is each world's last.
void FourLevelsSetNoMusicAndEachWorldsLastIsItsBossFight() {
    std::vector<std::string> silent;
    std::error_code ec;
    for (const auto& entry : std::filesystem::directory_iterator(kLevels, ec)) {
        if (entry.path().extension() != ".tscn") continue;
        std::ifstream in(entry.path(), std::ios::binary);
        std::ostringstream text;
        text << in.rdbuf();
        if (text.str().find("metadata/no_music = ") != std::string::npos) silent.push_back(entry.path().stem().string());
    }
    std::sort(silent.begin(), silent.end());
    const std::vector<std::string> four{"level0c", "level18c", "level31b", "level31c"};
    CHECK_MSG(silent == four, "no_music on 4-01, 4-19, 3-32 and 4-32 only: " + std::to_string(silent.size()) + " levels");
    MagicPortals::Chapters::Table chapters;
    std::string error;
    CHECK_MSG(MagicPortals::Chapters::Load(kChapters, chapters, error), error);
    std::array<int, 4> perWorld{};
    for (const MagicPortals::Chapters::Level& level : chapters.levels) {
        if (level.world >= 0 && level.world < 4) ++perWorld[static_cast<std::size_t>(level.world)];
    }
    CHECK_MSG(chapters.levels.size() == 128 && perWorld == (std::array<int, 4>{32, 32, 32, 32}),
              "four worlds of 32: index 31 is each world's last");
    int lasts = 0;
    for (std::size_t at = 0; at < chapters.levels.size(); ++at) {
        if (chapters.Next(static_cast<int>(at)) >= 0) continue;
        ++lasts;
        CHECK_MSG(chapters.levels[at].index == 31, chapters.levels[at].name + " ends its world at index " +
                                                       std::to_string(chapters.levels[at].index));
    }
    CHECK_EQ(lasts, 4);
}

// Game::preLoop on each kind of level, as it loads.
void EachLevelOpensOnTheTrackItsPreLoopAsksFor() {
    const struct Case {
        const char* level;
        const char* label;
        const char* track;
    } cases[] = {
        {"level0", "1-01", "game"},  {"level30", "1-31", "game"},  {"level31", "1-32", "boss"},
        {"level0a", "2-01", "game"}, {"level31a", "2-32", "boss"}, {"level30b", "3-31", "game"},
        {"level31b", "3-32", ""},    {"level0c", "4-01", ""},      {"level17c", "4-18", "game"},
        {"level18c", "4-19", ""},    {"level30c", "4-31", "game"}, {"level31c", "4-32", ""},
    };
    for (const Case& one : cases) {
        entt::registry registry;
        publishViewport(registry);
        MagicPortalsLayer layer(TestPaths(), one.level);
        layer.OnAttach(registry);
        CHECK_MSG(layer.SimLevel() != nullptr, std::string(one.level) + ": " + layer.LoadError());
        CHECK_MSG(layer.WantedTrack() == one.track, std::string(one.label) + " (" + one.level + ") opens on '" +
                                                        one.track + "', not '" + layer.WantedTrack() + "'");
        layer.OnDetach(registry);
    }
}

// Back out of a level to the main menu, one Back at a time; the screens it passed.
void BackUntilTheMainMenu(MagicPortalsLayer& layer, entt::registry& registry, std::vector<std::string>& heard) {
    using Screen = MagicPortalsLayer::Screen;
    MagicPortalsLayer::MenuButton back;
    back.kind = MagicPortalsLayer::MenuButton::Kind::Back;
    for (int press = 0; press < 12 && layer.MenuScreen() != Screen::Main; ++press) {
        const Screen before = layer.MenuScreen();
        if (!layer.PressMenu(registry, back)) break;
        if (layer.MenuScreen() != before) {
            heard.push_back(std::string(layer.MenuScreen() == Screen::Worlds ? "worlds" : "main") + ":" +
                            layer.WantedTrack());
        }
    }
}

// The level's track goes on under the medal, the level grid and chapter select;
// the main menu is the one state that changes it; a level picked from the grid
// starts its own.
void TheLevelsTrackCarriesIntoTheSelectors() {
    if (!OriginalArtIsThere("TheLevelsTrackCarriesIntoTheSelectors")) return;
    using Screen = MagicPortalsLayer::Screen;
    using Kind = MagicPortalsLayer::MenuButton::Kind;
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level0");
    layer.OnAttach(registry);
    if (!layer.LoadError().empty()) {
        CHECK_MSG(false, layer.LoadError());
        return;
    }
    CHECK_MSG(layer.WantedTrack() == "game", "1-01's own track: " + layer.WantedTrack());
    for (int tick = 0; tick < 600 && layer.MenuScreen() != Screen::Finished; ++tick) {
        tickWith(layer, registry, kRest, {MagicPortalsLayer::kRight}, {});
    }
    CHECK_MSG(layer.MenuScreen() == Screen::Finished && layer.WantedTrack() == "game",
              "and under its medal: " + layer.WantedTrack());
    MagicPortalsLayer::MenuButton list;
    list.kind = Kind::List;
    CHECK(layer.PressMenu(registry, list));
    CHECK_MSG(layer.MenuScreen() == Screen::Levels && layer.WantedTrack() == "game",
              "the level grid carries it (the port used to switch to the menu's here): '" + layer.WantedTrack() + "'");
    std::vector<std::string> heard;
    BackUntilTheMainMenu(layer, registry, heard);
    CHECK_MSG(heard == (std::vector<std::string>{"worlds:game", "main:menu"}),
              "chapter select still the level's, the main menu its own: " +
                  (heard.empty() ? std::string("nothing") : heard.front() + " / " + heard.back()));
    const MagicPortalsLayer::MenuButton* play = MenuButtonOf(layer, Kind::Play);
    if (play == nullptr) {
        CHECK_MSG(false, "the main menu has no play button");
        return;
    }
    layer.PressMenu(registry, *play);
    CHECK_MSG(layer.MenuScreen() == Screen::Worlds && layer.WantedTrack() == "menu", "chapter select from the menu: the menu's");
    const MagicPortalsLayer::MenuButton* world = MenuButtonOf(layer, Kind::World, 0);
    if (world == nullptr) {
        CHECK_MSG(false, "chapter select has no world button");
        return;
    }
    layer.PressMenu(registry, *world);
    CHECK_MSG(layer.MenuScreen() == Screen::Levels && layer.WantedTrack() == "menu", "and the grid under it");
    const MagicPortalsLayer::MenuButton* first = MenuButtonOf(layer, Kind::Level, 0);
    if (first == nullptr) {
        CHECK_MSG(false, "the grid has no level button");
        return;
    }
    layer.PressMenu(registry, *first);
    CHECK_MSG(IsAt(layer, "level0") && layer.WantedTrack() == "game", "and 1-01 picked from it starts its own");
    layer.OnDetach(registry);
}

// A no_music level's silence carries into the grid and chapter select just the
// same, a retry is silent again, and only the main menu brings a track back.
void ANoMusicLevelsSilenceCarriesIntoTheSelectors() {
    using Screen = MagicPortalsLayer::Screen;
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level0c");
    layer.OnAttach(registry);
    if (!layer.LoadError().empty()) {
        CHECK_MSG(false, layer.LoadError());
        return;
    }
    CHECK_MSG(layer.WantedTrack().empty(), "4-01 opens silent: '" + layer.WantedTrack() + "'");
    CloseTheLevelStartPopup(layer, registry);
    for (int tick = 0; tick < 30; ++tick) tickWith(layer, registry, kRest, {}, {});
    press(layer, registry, MagicPortalsLayer::kRetry);
    CHECK_MSG(IsAt(layer, "level0c") && layer.WantedTrack().empty(), "and a retry of it is silent again");
    MagicPortalsLayer::MenuButton list;
    list.kind = MagicPortalsLayer::MenuButton::Kind::List;
    CHECK(layer.PressMenu(registry, list));
    CHECK_MSG(layer.MenuScreen() == Screen::Levels && layer.WantedTrack().empty(), "the grid after it is silent");
    std::vector<std::string> heard;
    BackUntilTheMainMenu(layer, registry, heard);
    CHECK_MSG(heard == (std::vector<std::string>{"worlds:", "main:menu"}),
              "chapter select silent too, and the main menu's track at the main menu");
    layer.OnDetach(registry);
}

// turnMusicOff on a no_music level is pauseMusic: the track stops and stays
// currentTrack. A switch turned off and on again resumes it - the original's, and
// it sounds like a bug: 4-19 reached by a skip from 4-18 plays 4-18's track again.
// The sound switch resumes only while the music switch is on.
void ASwitchBackOnResumesTheTrackANoMusicLevelStopped() {
    if (!OriginalArtIsThere("ASwitchBackOnResumesTheTrackANoMusicLevelStopped")) return;
    namespace Pause = MagicPortals::Pause;
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level17c");
    layer.OnAttach(registry);
    if (!layer.LoadError().empty()) {
        CHECK_MSG(false, layer.LoadError());
        return;
    }
    CHECK_MSG(layer.WantedTrack() == "game", "4-18's own track");
    CloseTheLevelStartPopup(layer, registry);
    for (int tick = 0; tick < 30; ++tick) tickWith(layer, registry, kRest, {}, {});
    press(layer, registry, MagicPortalsLayer::kSkip);
    CHECK_MSG(IsAt(layer, "level18c") && layer.WantedTrack().empty(), "4-19 skipped to: silent");
    const auto pauseIt = [&layer, &registry]() {
        CloseTheLevelStartPopup(layer, registry);
        for (int tick = 0; tick < 30; ++tick) tickWith(layer, registry, kRest, {}, {});
        press(layer, registry, MagicPortalsLayer::kBack);
        for (int tick = 0; tick < 60; ++tick) tickWith(layer, registry, kRest, {}, {});
        return layer.Paused();
    };
    CHECK_MSG(pauseIt(), "the pause over 4-19");
    CHECK_MSG(layer.PressPause(registry, Pause::Button::Music) && !layer.MusicOn() && layer.WantedTrack().empty(),
              "the music switch off");
    CHECK_MSG(layer.PressPause(registry, Pause::Button::Music) && layer.MusicOn() && layer.WantedTrack() == "game",
              "and on again: resumeMusic plays currentTrack, 4-18's: '" + layer.WantedTrack() + "'");

    // Stopped again by a retry, then the sound switch.
    CHECK(layer.PressPause(registry, Pause::Button::Resume));
    for (int tick = 0; tick < 60 && layer.Paused(); ++tick) tickWith(layer, registry, kRest, {}, {});
    press(layer, registry, MagicPortalsLayer::kRetry);
    CHECK_MSG(IsAt(layer, "level18c") && layer.WantedTrack().empty(), "a retry: turnMusicOff again");
    CHECK_MSG(pauseIt(), "the pause again");
    CHECK_MSG(layer.PressPause(registry, Pause::Button::Sound) && !layer.SoundOn() && layer.WantedTrack().empty(),
              "the sound switch off");
    CHECK_MSG(layer.PressPause(registry, Pause::Button::Sound) && layer.SoundOn() && layer.WantedTrack() == "game",
              "and on again with the music on: turnGlobalVolumeOn resumes it");
    // With the music off, the sound back on resumes nothing; the music back on does.
    for (int tick = 0; tick < 60; ++tick) tickWith(layer, registry, kRest, {}, {});
    CHECK(layer.PressPause(registry, Pause::Button::Music) && !layer.MusicOn());
    CHECK(layer.PressPause(registry, Pause::Button::Sound) && !layer.SoundOn());
    CHECK_MSG(layer.PressPause(registry, Pause::Button::Sound) && layer.SoundOn() && layer.WantedTrack().empty(),
              "the sound back on with the music off: nothing");
    for (int tick = 0; tick < 60; ++tick) tickWith(layer, registry, kRest, {}, {});
    CHECK_MSG(layer.PressPause(registry, Pause::Button::Music) && layer.MusicOn() && layer.WantedTrack() == "game",
              "the music back on: resumed");
    layer.OnDetach(registry);
}

// 1-32: the boss's track from its load, on through the fight, stopped while the
// beholder is dead (ETHCallback_beholder #1139-1159, every update in
// BEHOLDER_STATE_DEAD) and silent after it has gone - the port used to play on,
// its beholder never cleared. Each rock it drops is put rising into its eye, the
// three hits TheBeholderHurtShakesTheView's one is.
void TheBeholdersDeathStopsItsTrack() {
    using MagicPortals::Boss::Phase;
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level31");
    layer.OnAttach(registry);
    CHECK_MSG(layer.SimLevel() != nullptr, layer.LoadError());
    if (layer.SimLevel() == nullptr || !layer.SimLevel()->boss.beholder.has_value()) return;
    CHECK_MSG(layer.WantedTrack() == "boss", "1-32 opens on the boss's track: " + layer.WantedTrack());
    CloseTheLevelStartPopup(layer, registry);
    const MagicPortals::Game::Level& level = *layer.SimLevel();
    const MagicPortals::Boss::Beholder& beholder = *level.boss.beholder;
    const auto step = [&layer, &registry]() {
        tickWith(layer, registry, kRest, {}, {});
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    };
    int thrown = 0;
    int shoved = 0;
    int offWhileAlive = 0;
    int ticks = 0;
    for (; ticks < 12000 && beholder.phase != Phase::Dead; ++ticks) {
        step();
        if (beholder.phase != Phase::Dead && layer.WantedTrack() != "boss") ++offWhileAlive;
        if (beholder.rocksThrown > thrown && !level.boss.rocks.empty()) {
            thrown = beholder.rocksThrown;
            const entt::entity rock = level.boss.rocks.back().body;
            if (!registry.valid(rock)) continue;
            const glm::vec3 inside = MagicPortals::Units::ToWorld(beholder.atPx.x, beholder.atPx.y + 10.0);
            auto& at = registry.get<TransformComponent>(rock);
            at.position = glm::vec3(inside.x, inside.y, at.position.z);
            registry.get<RigidBodyComponent>(rock).velocity =
                glm::vec3(0.0f, MagicPortals::Units::ToMetres(200.0), 0.0f);
            ++shoved;
        }
    }
    CHECK_MSG(beholder.phase == Phase::Dead && beholder.hits == 3,
              "three rocks rising into it kill it: " + std::to_string(beholder.hits) + " hits of " +
                  std::to_string(shoved) + " rocks put, " + std::to_string(ticks) + " ticks");
    CHECK_MSG(offWhileAlive == 0, "the boss's track through the whole fight: " + std::to_string(offWhileAlive) +
                                      " ticks without it");
    CHECK_MSG(layer.WantedTrack().empty(), "dead: stopped on that tick: '" + layer.WantedTrack() + "'");
    int heard = 0;
    for (int tick = 0; tick < 400 && !beholder.gone; ++tick) {
        step();
        if (!layer.WantedTrack().empty()) ++heard;
    }
    for (int tick = 0; tick < 60; ++tick) {
        step();
        if (!layer.WantedTrack().empty()) ++heard;
    }
    CHECK_MSG(beholder.gone && level.boss.buttonRaised && heard == 0,
              "silent through its death and after it has gone, its button raised: " + std::to_string(heard) +
                  " ticks with a track");
    std::printf("  1-32: the beholder dead on tick %d after %d rocks; the track stopped with it\n", ticks, shoved);
    // A retry is a fresh Game::preLoop: playGameMusic(true) starts the stopped track again.
    MagicPortalsLayer::MenuButton retry;
    retry.kind = MagicPortalsLayer::MenuButton::Kind::Retry;
    CHECK(layer.PressMenu(registry, retry));
    CHECK_MSG(IsAt(layer, "level31") && layer.WantedTrack() == "boss", "a retry: the boss's track again");
    layer.OnDetach(registry);
}

// 2-32: the boss's track from its load (isBossFight: the world's last level), and
// the take-off's StopSample (ETHCallback_dragon #409-431), once, as it climbs away
// past take_off - about 51.6 s in.
void TheDragonsTakeOffStopsTheBossTrack() {
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level31a");
    layer.OnAttach(registry);
    CHECK_MSG(layer.SimLevel() != nullptr, layer.LoadError());
    if (layer.SimLevel() == nullptr || !layer.SimLevel()->dragon.present) return;
    CHECK_MSG(layer.WantedTrack() == "boss", "2-32 opens on the boss's track (it played the level's): " +
                                                 layer.WantedTrack());
    CloseTheLevelStartPopup(layer, registry);
    const MagicPortals::Dragon::State& dragon = layer.SimLevel()->dragon;
    // And its take-off's sound (ETHCallback_dragon #409-437, planning step 142),
    // once: the dragon's turn is taken in Game::BeforeStep, after the tick's
    // latches are read, so its edge is latched on the tick after.
    std::vector<int> tookOffSounds;
    const auto countTakeOffs = [&layer, &tookOffSounds](int tick) {
        for (const std::string& event : layer.LatchedSounds()) {
            if (event == "dragon_took_off") tookOffSounds.push_back(tick);
        }
    };
    int offBefore = 0;
    int ticks = 0;
    for (; ticks < 4000 && !dragon.tookOff; ++ticks) {
        tickWith(layer, registry, kRest, {}, {});
        countTakeOffs(ticks);
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
        if (!dragon.tookOff && layer.WantedTrack() != "boss") ++offBefore;
    }
    CHECK_MSG(dragon.tookOff && offBefore == 0, "the boss's track until the take-off, on tick " + std::to_string(ticks));
    CHECK_MSG(layer.WantedTrack().empty(), "and none from its tick: '" + layer.WantedTrack() + "'");
    int heard = 0;
    for (int tick = 0; tick < 120; ++tick) {
        tickWith(layer, registry, kRest, {}, {});
        countTakeOffs(ticks + tick);
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
        if (!layer.WantedTrack().empty()) ++heard;
    }
    CHECK_MSG(heard == 0, "nor after it: " + std::to_string(heard));
    std::string at;
    for (const int tick : tookOffSounds) at += " " + std::to_string(tick);
    // The loop's last tick, ticks - 1, is the one the take-off was taken on.
    CHECK_MSG(tookOffSounds.size() == 1 && tookOffSounds[0] >= ticks - 1 && tookOffSounds[0] <= ticks,
              "dragon_took_off once, as it takes off on tick " + std::to_string(ticks - 1) + ": latched on" +
                  (at.empty() ? std::string(" none") : at));
    std::printf("  2-32: the dragon took off on tick %d, and the boss's track stopped with it; dragon_took_off on%s\n",
                ticks, at.empty() ? " none" : at.c_str());
    layer.OnDetach(registry);
}

// ---- the win cutscenes (planning step 123) ---------------------------------------

// Puts the player's body in the level's exit and ticks until the layer says the door
// was reached. Returns the layer's tick it was reached on, or -1.
int ReachTheDoor(MagicPortalsLayer& layer, entt::registry& registry, const glm::dvec2& exitPx) {
    CloseTheLevelStartPopup(layer, registry);
    for (int tick = 0; tick < 10 && !layer.Finishing(); ++tick) {
        PutPlayerAt(registry, layer, exitPx);
        auto& rigid = registry.get<RigidBodyComponent>(layer.SimLevel()->player);
        rigid.velocity = glm::vec3(0.0f);
        tickWith(layer, registry, kRest, {}, {});
    }
    CHECK_MSG(layer.Finishing(), "the door was reached");
    return layer.Finishing() ? layer.LayerTicks() : -1;
}

// The restart button of the finished or the lost screen, as a player presses it:
// over either screen R is not read, the screen's buttons are.
bool RestartFromTheScreen(MagicPortalsLayer& layer, entt::registry& registry) {
    for (const MagicPortalsLayer::MenuButton& button : layer.MenuButtons()) {
        if (button.kind != MagicPortalsLayer::MenuButton::Kind::Retry) continue;
        layer.PressMenu(registry, button); // by value: pressing clears the list
        return true;
    }
    CHECK_MSG(false, "the screen has a restart button");
    return false;
}

// A level with no end_delay keeps level_end's 1400 ms and plays no cutscene.
void ALevelWithoutAnEndDelayKeepsTheBeat() {
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level0");
    layer.OnAttach(registry);
    CHECK_MSG(layer.SimLevel() != nullptr, layer.LoadError());
    if (layer.SimLevel() == nullptr) return;
    CHECK(layer.WonDelayMs() == 1400.0 && layer.LevelEndRules().wonDelayMs == 1400.0);
    const MagicPortalsLayer::CutsceneReport report = layer.CutscenePicture(registry);
    CHECK(!report.launchPlaced && !report.landingPlaced && !report.knight.placed);
    layer.OnDetach(registry);
}

// 4-01 (level0c): rocket_launch from the door's own tick - the rocket door up
// (0, -390) over 7600 ms, the bridge left without a clamp, a shake every 6th tick
// for 6 s, the rocket's track - and the medal 5000 ms after the door, the launch
// running on under it. Only pictures move: the bridge's box stays.
void TheRocketLaunchesAfter4_01sDoor() {
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level0c");
    layer.OnAttach(registry);
    CHECK_MSG(layer.SimLevel() != nullptr, layer.LoadError());
    if (layer.SimLevel() == nullptr) return;
    CHECK(layer.WonDelayMs() == 5000.0);
    MagicPortalsLayer::CutsceneReport before = layer.CutscenePicture(registry);
    CHECK(before.launchPlaced && !before.landingPlaced && !before.knight.placed);
    CHECK_MSG(before.bridgeQuad != entt::null, "the rocket_bridge is drawn");
    const glm::dvec2 doorRest = before.doorCentrePx;
    const glm::dvec2 bridgeRest = before.bridgeCentrePx;
    CHECK(layer.WantedTrack().empty()); // no_music

    const int door = ReachTheDoor(layer, registry, glm::dvec2(757.0, 140.0));
    if (door < 0) return;
    MagicPortalsLayer::CutsceneReport now = layer.CutscenePicture(registry);
    CHECK_EQ(now.launchStartedTick, door);
    CHECK(now.launch.running && now.launch.elapsedMs >= 16.0 && now.launch.elapsedMs < 17.0);
    CHECK_MSG(layer.WantedTrack() == "rocket", layer.WantedTrack());

    int screenAt = -1;
    for (int tick = door + 1; tick <= door + 480; ++tick) {
        tickWith(layer, registry, kRest, {}, {});
        if (screenAt < 0 && layer.MenuScreen() == MagicPortalsLayer::Screen::Finished) screenAt = tick;
        if (tick == door + 228) {
            // 3800 ms: the bridge at its -32, the door at -390 x smoothBeginning(0.5).
            now = layer.CutscenePicture(registry);
            const double t = now.launch.elapsedMs;
            CHECK_MSG(std::fabs(now.bridgeCentrePx.x - bridgeRest.x - now.launch.pose.bridgeOffsetPx.x) < 1e-6 &&
                          std::fabs(now.launch.pose.bridgeOffsetPx.x + 32.0 * (1.0 - std::cos(t / 3800.0 * 1.5707963))) <
                              1e-3,
                      Point(now.bridgeCentrePx) + " at " + std::to_string(t));
            CHECK_MSG(std::fabs(now.doorCentrePx.y - doorRest.y - now.launch.pose.doorOffsetPx.y) < 1e-6 &&
                          now.launch.pose.doorOffsetPx.y < -100.0,
                      Point(now.doorCentrePx));
            // The box the level built for it has not moved.
            CHECK_MSG(glm::length(now.bridgeRestPx - glm::dvec2(716.0, 178.0)) < 0.5, Point(now.bridgeRestPx));
        }
    }
    // 5000 ms of the script's clock: the 313rd tick of 16 ms (300 of 16.667).
    CHECK_MSG(screenAt == door + 313, "the medal " + std::to_string(screenAt - door) + " ticks after the door");
    now = layer.CutscenePicture(registry);
    // Behind the medal the launch went on and stopped at its last pose below 7600,
    // the 474th update's at 7584 ms (the 455th's at 7583.3 of 16.667): the door 388.7 up of its 390,
    // the bridge past -63.9 of its unclamped -64.
    const double last = 474.0 * kScriptMs;
    CHECK_MSG(std::fabs(now.launch.pose.doorOffsetPx.y + 390.0 * (1.0 - std::cos(last / 7600.0 * 1.5707963))) < 1e-3 &&
                  now.launch.pose.doorOffsetPx.y < -388.0,
              Point(now.launch.pose.doorOffsetPx));
    CHECK_MSG(now.launch.pose.bridgeOffsetPx.x < -63.9 && now.launch.pose.bridgeOffsetPx.x > -64.0,
              Point(now.launch.pose.bridgeOffsetPx));
    CHECK_MSG(std::fabs(now.doorCentrePx.y - doorRest.y - now.launch.pose.doorOffsetPx.y) < 1e-6,
              Point(now.doorCentrePx));
    // startEarthquake(3, 0) each time the counter passes 100 below 6000 ms. The script's frame is a
    // whole number of ms, 16 at 60 fps (planning step 147), which passes 100 after seven (112; six are
    // 96): 53 calls, every seventh update to the 371st. The port's old tick of 16.6666675 ms made six of
    // them 100.000005 and shook on every sixth: 59 calls.
    CHECK_EQ(now.quakes, 53);
    CHECK_MSG(layer.WantedTrack() == "rocket", layer.WantedTrack());
    std::printf("  4-01: door on tick %d, medal %d ticks later, rocket at %s, bridge %s, %d shakes\n", door,
                screenAt - door, Point(now.launch.pose.doorOffsetPx).c_str(),
                Point(now.launch.pose.bridgeOffsetPx).c_str(), now.quakes);

    // A restart forgets it: the rocket and the bridge back where the level put them.
    if (!RestartFromTheScreen(layer, registry)) return;
    tickWith(layer, registry, kRest, {}, {});
    now = layer.CutscenePicture(registry);
    CHECK(!now.launch.running && now.launchStartedTick < 0 && now.quakes == 0);
    CHECK_MSG(glm::length(now.doorCentrePx - doorRest) < 1e-6 && glm::length(now.bridgeCentrePx - bridgeRest) < 1e-6,
              Point(now.doorCentrePx) + " " + Point(now.bridgeCentrePx));
    layer.OnDetach(registry);
}

// 4-19 (level18c): rocket_landing from the door's tick - the rocket door down
// (256, 400) over 12500 ms on its bob, the camera on it, the key shrinking, the
// eclipse up to the view's bottom, the spiral dimmed to a tenth, back_home - and
// the medal 14500 ms after the door.
void TheRocketLandsAfter4_19sDoor() {
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level18c");
    layer.OnAttach(registry);
    CHECK_MSG(layer.SimLevel() != nullptr, layer.LoadError());
    if (layer.SimLevel() == nullptr) return;
    CHECK(layer.WonDelayMs() == 14500.0);
    const MagicPortalsLayer::CutsceneReport before = layer.CutscenePicture(registry);
    CHECK(!before.launchPlaced && before.landingPlaced && !before.knight.placed);
    const glm::vec4 spiralBefore = before.spiralColour;

    const int door = ReachTheDoor(layer, registry, glm::dvec2(590.0, 134.0));
    if (door < 0) return;
    CHECK_EQ(layer.CutscenePicture(registry).landingStartedTick, door);
    CHECK_MSG(layer.WantedTrack() == "back_home", layer.WantedTrack());
    int screenAt = -1;
    double keyAtTen = 0.0;
    for (int tick = door + 1; tick <= door + 920; ++tick) {
        tickWith(layer, registry, kRest, {}, {});
        if (screenAt < 0 && layer.MenuScreen() == MagicPortalsLayer::Screen::Finished) screenAt = tick;
        if (tick == door + 10) keyAtTen = layer.CutscenePicture(registry).keyScale;
    }
    // 14500 ms: the 907th tick of 16 ms (870 of 16.667).
    CHECK_MSG(screenAt == door + 907, "the medal " + std::to_string(screenAt - door) + " ticks after the door");
    CHECK_MSG(std::fabs(keyAtTen - std::pow(0.9, 11.0)) < 1e-9, std::to_string(keyAtTen));
    const MagicPortalsLayer::CutsceneReport now = layer.CutscenePicture(registry);
    CHECK(now.landing.elapsedMs >= 12500.0 && now.landing.elapsedMs < 12500.0 + 17.0);
    const MagicPortalsLayer::DoorReport doorNow = layer.DoorPicture();
    // The door's point: its node (590, 128), its bob, and the landing's (256, 400).
    const glm::dvec2 expected = glm::dvec2(590.0, 128.0) + doorNow.offsetPx + glm::dvec2(256.0, 400.0);
    // The landing's clock stops on the first update at or past 12500 ms, which at 16 ms is 12512: the
    // door lands 0.4 units (12 ms of its 256) past its mark, as the original's sum overshoots.
    CHECK_MSG(glm::length(now.doorAtPx - expected) < 1.0, Point(now.doorAtPx) + " against " + Point(expected));
    // The camera was given that point, and the eclipse is at the view's bottom, 0
    // below its corner's 256.
    CHECK_MSG(glm::length(now.cameraTargetPx - now.doorAtPx) < 1.0, Point(now.cameraTargetPx));
    const glm::dvec2 corner = layer.CameraCentrePx() - layer.ViewPx() * 0.5;
    CHECK_MSG(std::fabs(now.eclipseAtPx.y - (corner.y + layer.ViewPx().y)) < 0.01,
              Point(now.eclipseAtPx) + " against the view's bottom " + std::to_string(corner.y + layer.ViewPx().y));
    CHECK_MSG(std::fabs(now.spiralColour.r - spiralBefore.r * 0.1f) < 1e-4f && spiralBefore.r > 0.5f,
              std::to_string(now.spiralColour.r) + " from " + std::to_string(spiralBefore.r));
    std::printf("  4-19: door on tick %d, medal %d ticks later, door at %s, eclipse at %s, spiral %.3f\n", door,
                screenAt - door, Point(now.doorAtPx).c_str(), Point(now.eclipseAtPx).c_str(),
                static_cast<double>(now.spiralColour.r));
    layer.OnDetach(registry);
}

// 2-32 (level31a): the knight its spawn adds on the door's tick walks in before the
// medal, 6600 ms after the door, with the door's own effect and sound; black, on
// minion.png's cut, its aura carried. A death adds it too, and a retry takes it.
void TheKnightWalksIntoTheDoorAfter2_32() {
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level31a");
    layer.OnAttach(registry);
    CHECK_MSG(layer.SimLevel() != nullptr, layer.LoadError());
    if (layer.SimLevel() == nullptr) return;
    CHECK(layer.WonDelayMs() == 6600.0);
    CHECK(layer.CutscenePicture(registry).knight.placed);

    const int door = ReachTheDoor(layer, registry, glm::dvec2(2554.0, 181.0));
    if (door < 0) return;
    MagicPortalsLayer::CutsceneReport now = layer.CutscenePicture(registry);
    CHECK_EQ(now.knightSpawnedTick, door);
    CHECK(now.knight.body != entt::null);
    const auto doorSounds = [&layer] {
        const std::vector<std::string> sounds = layer.LatchedSounds();
        return static_cast<int>(std::count(sounds.begin(), sounds.end(), std::string("level_finished")));
    };
    const int soundsAtDoor = doorSounds();
    int screenAt = -1;
    bool drawn = false;
    bool walkedRight = false;
    for (int tick = door + 1; tick <= door + 420; ++tick) {
        tickWith(layer, registry, kRest, {}, {});
        now = layer.CutscenePicture(registry);
        if (now.knightQuad != entt::null) drawn = true;
        if (now.knight.walked && now.knight.row == 2) walkedRight = true;
        if (screenAt < 0 && layer.MenuScreen() == MagicPortalsLayer::Screen::Finished) screenAt = tick;
    }
    // 6600 ms: the 413th tick of 16 ms (396 of 16.667).
    CHECK_MSG(screenAt == door + 413, "the medal " + std::to_string(screenAt - door) + " ticks after the door");
    CHECK(drawn && walkedRight && now.knightAuraQueued);
    CHECK_MSG(now.knightEnteredTick > door && now.knightEnteredTick < door + 413,
              "in on tick " + std::to_string(now.knightEnteredTick));
    CHECK_MSG(glm::length(now.knightEnteredAtPx - glm::dvec2(2548.0, 175.0)) < 16.0, Point(now.knightEnteredAtPx));
    CHECK(now.knight.gone && now.knightQuad == entt::null);
    CHECK_EQ(Tagged(registry, "Magic Portals Knight"), 0);
    CHECK_EQ(doorSounds(), soundsAtDoor + 1);
    std::printf("  2-32: door on tick %d, the knight in %d ticks later at %s, the medal %d ticks after the door\n", door,
                now.knightEnteredTick - door, Point(now.knightEnteredAtPx).c_str(), screenAt - door);

    // Killed instead: isFinished is the death too, so the spawn adds it on that tick,
    // and the lost screen keeps its own 1400 ms.
    if (!RestartFromTheScreen(layer, registry)) return;
    CHECK(!layer.Finishing() && !layer.Dying());
    now = layer.CutscenePicture(registry);
    CHECK(now.knightSpawnedTick < 0 && now.knight.body == entt::null && !now.knight.spawned);
    auto& transform = registry.get<TransformComponent>(layer.SimLevel()->player);
    const glm::vec3 below = MagicPortals::Units::ToWorld(300.0, 600.0);
    transform.position = glm::vec3(below.x, below.y, transform.position.z);
    tickWith(layer, registry, kRest, {}, {});
    CHECK(layer.Dying());
    now = layer.CutscenePicture(registry);
    CHECK_EQ(now.knightSpawnedTick, layer.LayerTicks());
    for (int tick = 0; tick < TicksOf(1400.0); ++tick) tickWith(layer, registry, kRest, {}, {});
    CHECK_MSG(layer.MenuScreen() == MagicPortalsLayer::Screen::Dead, "the lost screen at its own 1400 ms");
    CHECK_MSG(Tagged(registry, "Magic Portals Knight") == 1, "with the knight falling behind it");
    // A restart from there takes the knight, its body and its picture.
    if (!RestartFromTheScreen(layer, registry)) return;
    tickWith(layer, registry, kRest, {}, {});
    now = layer.CutscenePicture(registry);
    CHECK(!now.knight.spawned && now.knight.body == entt::null && now.knightQuad == entt::null);
    CHECK_EQ(Tagged(registry, "Magic Portals Knight"), 0);
    layer.OnDetach(registry);
}

// 2-20'S HANDLE (handle.json, planning step 139): a finger that goes down on
// arrows.ent and stays down drags it one for one on the screen, whole while held and
// faint at rest; the camera's finger is locked meanwhile (shouldLockCamera) and the
// held touch stops its follow, the drag fires nothing, the flame eases after the
// handle - picture and light - and the lesson hand goes, with smoke_vanish 32 above
// it, on the first held tick.
void TwoTwentyDragsTheHandle() {
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level19a");
    layer.OnAttach(registry);
    if (!layer.LoadError().empty()) {
        CHECK_MSG(false, layer.LoadError());
        return;
    }
    layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    for (int tick = 0; tick < 90; ++tick) tickWith(layer, registry, kRest, {}, {});
    std::vector<MagicPortalsLayer::HandleReport> handles = layer.HandleReports();
    CHECK_MSG(handles.size() == 1u, "2-20 draws one handle");
    if (handles.size() != 1u) return;
    CHECK_MSG(handles[0].drawn && std::fabs(handles[0].alpha - 0.3f) < 1e-6f,
              "at rest it is drawn at 0.3: " + std::to_string(handles[0].alpha));
    MagicPortalsLayer::LessonReport lesson = layer.LessonState();
    CHECK_MSG(lesson.placed && lesson.drawn && !lesson.lesson.gone, "and its lesson hand is there");
    const glm::dvec2 start = layer.SimLevel()->handles.handles.front().atPx;
    CHECK(start == glm::dvec2(162.0, 192.0));
    const int shotsBefore = layer.SimLevel()->portals.shotsFired;

    // Down on the handle's point, 100 right and 50 up the screen over ten ticks,
    // nine of them held: the handle goes 9/10 of it.
    const glm::dvec2 view = layer.ViewPx();
    const glm::dvec2 corner = layer.CameraCentrePx() - view * 0.5;
    const glm::dvec2 from = (start - corner) / view;
    const glm::dvec2 to = from + glm::dvec2(100.0, -50.0) / view;
    layer.ScheduleDevDrag(1, from, to, 11);
    tickWith(layer, registry, kRest, {}, {}); // down
    const glm::dvec2 cameraAtDown = layer.CameraCentrePx();
    tickWith(layer, registry, kRest, {}, {}); // the first held tick
    handles = layer.HandleReports();
    CHECK_MSG(std::fabs(handles[0].alpha - 1.0f) < 1e-6f, "held, it is drawn whole");
    lesson = layer.LessonState();
    CHECK_MSG(lesson.lesson.gone && !lesson.drawn, "the lesson hand goes the tick the handle is first held");
    // Where its last call put it, which it keeps once deleted.
    const glm::dvec2 lessonAt = lesson.lesson.AtPx(layer.SimLevel()->handles.rules);
    // What the tick queued, a frame adds.
    layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    const auto smoke = EffectsOf(layer, "smoke_vanish.ent");
    CHECK_MSG(smoke.size() == 1u, "with one smoke_vanish: " + std::to_string(smoke.size()));
    if (smoke.size() == 1u) {
        CHECK_MSG(glm::length(smoke[0].atPx - (lessonAt + glm::dvec2(0.0, -32.0))) < 1e-6,
                  "32 above where the hand was: " + Point(smoke[0].atPx) + " against " + Point(lessonAt));
    }
    bool still = layer.CameraCentrePx() == cameraAtDown;
    for (int tick = 0; tick < 8; ++tick) {
        tickWith(layer, registry, kRest, {}, {});
        still = still && layer.CameraCentrePx() == cameraAtDown;
    }
    CHECK_MSG(still, "the view neither pans nor follows while the handle is held");
    tickWith(layer, registry, kRest, {}, {}); // up
    const glm::dvec2 dragged = layer.SimLevel()->handles.handles.front().atPx;
    CHECK_MSG(glm::length(dragged - (start + glm::dvec2(90.0, -45.0))) < 1e-6,
              "the handle went with the finger, one for one: " + Point(dragged));
    CHECK_MSG(layer.SimLevel()->portals.shotsFired == shotsBefore, "and the drag fired nothing");
    handles = layer.HandleReports();
    CHECK_MSG(std::fabs(handles[0].alpha - 0.3f) < 1e-6f, "let go, faint again");
    CHECK_MSG(glm::length(handles[0].centrePx - dragged) < 1e-9, "and drawn where it was left");

    // The flame follows: two seconds on it stands on the handle, its light's owner
    // with it.
    for (int tick = 0; tick < 120; ++tick) tickWith(layer, registry, kRest, {}, {});
    const std::vector<MagicPortalsLayer::FollowerReport> followers = layer.FollowerReports();
    CHECK_MSG(followers.size() == 1u, "one follower drawn");
    if (followers.size() == 1u) {
        const glm::dvec2 agent = layer.SimLevel()->handles.followers.front().atPx;
        CHECK_MSG(glm::length(agent - dragged) < 1.0, "the flame eased after it: " + Point(agent));
        CHECK_MSG(glm::length(followers[0].ownerPx - agent) < 1e-9, "its picture's owner, which its light and flame "
                                                                    "hang off, is where it is");
    }
    layer.OnDetach(registry);
}

// A LIFT WAITS UNTIL A TOUCH SENDS IT, AND THAT TOUCH FIRES NOTHING (movers.json
// `lift`; planning step 140). 1-28 (level27) places lift_ent_694 on its marker a at
// (96, 240). Untouched it stays there, blinking 0.6 grey to white on the level's
// age; a touch down on its picture sends it on that tick (ETHCallback_lift moves it
// in the frame it is sent), disables the touch so its release fires no shot, and
// latches one lift_sent (playElevatorSound) - and nothing when it stops on b; a touch
// off it fires as any does.
void OneTwentyEightsLiftIsSentByATouchAndFiresNothing() {
    namespace Mover = MagicPortals::Mover;
    Mover::Rules movers;
    std::string moversError;
    CHECK_MSG(Mover::LoadRules(std::string(MAGICPORTALS_PORT_DATA_DIR) + "/movers.json", movers, moversError),
              moversError);
    const MagicPortals::Art::Blink blink{movers.liftBlinkFrom, movers.liftBlinkTo, movers.liftBlinkStrideMs};
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level27");
    layer.OnAttach(registry);
    if (!layer.LoadError().empty() || layer.SimLevel() == nullptr) {
        CHECK_MSG(false, layer.LoadError());
        return;
    }
    layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    CloseTheLevelStartPopup(layer, registry);
    const Mover::Lift* theLift = layer.SimLevel()->movers.FindLift("lift_ent_694");
    CHECK_MSG(theLift != nullptr, "1-28 places lift_ent_694");
    if (theLift == nullptr) return;
    const glm::dvec2 a(96.0, 240.0);
    const glm::dvec2 b(96.0, 112.0);
    const auto liftSent = [&layer]() {
        const std::vector<std::string> sounds = layer.LatchedSounds();
        return std::count(sounds.begin(), sounds.end(), "lift_sent");
    };

    // Its picture, by lift.png's name (not door_lift.png) and where it stands.
    const auto liftQuad = [&registry](const glm::dvec2& atPx) {
        entt::entity found = entt::null;
        for (auto [entity, tag, material, transform] :
             registry.view<TagComponent, MaterialComponent, TransformComponent>().each()) {
            if (tag.tag != "Magic Portals Sprite") continue;
            if (std::filesystem::path(material.albedoTexturePath).filename() != "lift.png") continue;
            if (glm::distance(MagicPortals::Units::ToPixels(transform.position), atPx) > 0.5) continue;
            found = entity;
        }
        return found;
    };
    // 120 ticks untouched: on a, and every tick's picture the blink's grey.
    int wrong = 0;
    double lows = 2.0;
    double highs = 0.0;
    bool waits = true;
    for (int tick = 0; tick < 120; ++tick) {
        tickWith(layer, registry, kRest, {}, {});
        waits = waits && theLift->motion.atPx == a && !theLift->motion.Moving();
        const entt::entity quad = liftQuad(a);
        const glm::dvec3 want = blink.At(layer.LevelAgeMs());
        if (quad == entt::null) {
            ++wrong;
            continue;
        }
        const glm::vec4 got = registry.get<MaterialComponent>(quad).albedoColor;
        if (std::fabs(got.r - static_cast<float>(want.x)) > 1e-6f || got.g != got.r || got.b != got.r ||
            got.a != 1.0f) {
            ++wrong;
        }
        lows = std::min(lows, want.x);
        highs = std::max(highs, want.x);
    }
    CHECK_MSG(waits, "untouched for 120 ticks, the lift waits on its marker a");
    CHECK_MSG(wrong == 0, "its picture is the blink's grey on every tick: " + std::to_string(wrong) + " wrong");
    // The blink's legs are 300 ms and a tick is 16: 0.6 at 1200 ms (the 75th tick), 1 between the 18th and
    // the 19th, within a tick's step 0.4 x 16 / 300.
    CHECK_MSG(lows < 0.6 + 1e-3 && highs < 1.0 + 1e-6 && highs > 1.0 - 0.4 * 16.0 / 300.0 - 1e-6,
              "reaching both ends, 0.6 and 1: " + std::to_string(lows) + " to " + std::to_string(highs));
    CHECK_MSG(liftSent() == 0, "and no lift_sent while nothing sends it");

    // A touch down on it, and up the next tick where it went down.
    CHECK_MSG(onScreen(registry, a), "1-28's view shows the lift");
    const glm::vec2 pixel = screenOf(registry, a + glm::dvec2(10.0, -4.0));
    const int shotsBefore = layer.SimLevel()->portals.shotsFired;
    tap(layer, registry, pixel);
    CHECK_MSG(theLift->motion.Moving() && theLift->motion.destPx == b && theLift->motion.sends == 1,
              "the touch sends it toward b");
    CHECK_MSG(std::fabs(glm::distance(theLift->motion.atPx, a) - 60.0 * kScriptMs / 1000.0) < 1e-9,
              "and it moves on the tick it is sent: " + Point(theLift->motion.atPx));
    lift(layer, registry, pixel);
    CHECK_MSG(layer.SimLevel()->portals.shotsFired == shotsBefore && !layer.SimLevel()->portals.flight,
              "its release fires no shot");
    // What a tick did is latched at the start of the next (latchSimSounds, after the
    // app's physics step), so the send shows on the release's tick.
    CHECK_MSG(liftSent() == 1, "with one lift_sent");
    for (int tick = 0; tick < 200; ++tick) tickWith(layer, registry, kRest, {}, {});
    CHECK_MSG(theLift->motion.atPx == b && !theLift->motion.Moving(), "it stops on b and stays");
    CHECK_MSG(liftSent() == 1, "and nothing more plays when it arrives");
    CHECK_MSG(layer.SimLevel()->portals.shotsFired == shotsBefore, "no shot left in all that time");

    // A touch off it fires, as any touch does, and sends nothing.
    const glm::dvec2 elsewhere = layer.CameraCentrePx() + glm::dvec2(60.0, -40.0);
    shoot(layer, registry, screenOf(registry, elsewhere));
    CHECK_MSG(layer.SimLevel()->portals.shotsFired == shotsBefore + 1, "a touch off the lift fires its shot");
    CHECK_MSG(theLift->motion.sends == 1 && theLift->motion.atPx == b, "and the lift is left where it is");
    layer.OnDetach(registry);
}

// THE MEDAL IS SAVED ON THE DOOR'S TICK (planning step 141; step 123's MEDIUM row):
// checkGameEnd calls writeScore on the frame the character goes in (#75), whose
// setScore writes the file there and then (#48), and only the screen waits for the
// level's gameWonDelay. On level0, walked to its door, the file has the medal on
// that tick and the screen comes 84 ticks (1400 ms) later; on 4-19 (level18c), whose
// end_delay is 14500 ms, R pressed 60 ticks after the door - which the port reads in
// the beat - restarts the level with the medal kept, and no screen came up. Into a
// directory of its own, emptied first and last, never a player's save.
void TheMedalIsSavedOnTheDoorsTick() {
    namespace Scores = MagicPortals::Scores;
    const std::filesystem::path dir = std::filesystem::temp_directory_path() / "supersonic-test-mp-layer-medals";
    std::error_code ec;
    std::filesystem::remove_all(dir, ec);
    std::filesystem::create_directories(dir, ec);
    MagicPortalsLayer::Paths paths = TestPaths();
    paths.saveDir = dir.string();
    // What the file says, read as the next run would read it.
    const auto saved = [&dir](int world, int level) {
        Scores::Store store;
        std::string why;
        return store.Open(dir.string(), why) ? store.Get(world, level) : -1;
    };
    const auto earned = [](const MagicPortalsLayer& layer) {
        const auto& c = layer.LastCleared();
        return c ? MagicPortals::LevelEnd::ComputeScore(c->portalsUsed, c->goldenScore, c->crystals, c->crystalsTotal)
                 : -1;
    };

    // level0 (1-01), walked to its door.
    {
        entt::registry registry;
        publishViewport(registry);
        MagicPortalsLayer layer(paths, "level0");
        layer.OnAttach(registry);
        CHECK_MSG(layer.SimLevel() != nullptr, layer.LoadError());
        if (layer.SimLevel() == nullptr) return;
        CHECK_EQ(saved(0, 0), Scores::kUnplayed);
        for (int tick = 0; tick < 600 && !layer.Finishing(); ++tick) {
            std::vector<std::string> pressed;
            if (tick == 0) pressed.push_back(MagicPortalsLayer::kRight);
            tickWith(layer, registry, kRest, {MagicPortalsLayer::kRight}, std::move(pressed));
        }
        CHECK_MSG(layer.Finishing(), "level0's door is reached by walking right");
        if (!layer.Finishing()) return;
        const int door = layer.LayerTicks();
        const int medal = earned(layer);
        CHECK_MSG(medal > Scores::kUnplayed && saved(0, 0) == medal,
                  "on the door's tick the file holds " + std::to_string(saved(0, 0)) + ", the play earned " +
                      std::to_string(medal));
        CHECK(layer.MenuScreen() == MagicPortalsLayer::Screen::None);
        int screenAt = -1;
        for (int tick = door + 1; tick <= door + 90 && screenAt < 0; ++tick) {
            tickWith(layer, registry, kRest, {}, {});
            if (layer.MenuScreen() == MagicPortalsLayer::Screen::Finished) screenAt = tick;
        }
        CHECK_MSG(screenAt == door + 88, "the medal screen " + std::to_string(screenAt - door) + " ticks after the door");
        CHECK_EQ(saved(0, 0), medal);
        std::printf("  1-01: door on tick %d, medal %d in the file on it, the screen %d ticks later\n", door, medal,
                    screenAt - door);
        layer.OnDetach(registry);
    }

    // 4-19 (level18c): the door, then R in the 14.5 s beat.
    {
        entt::registry registry;
        publishViewport(registry);
        MagicPortalsLayer layer(paths, "level18c");
        layer.OnAttach(registry);
        CHECK_MSG(layer.SimLevel() != nullptr, layer.LoadError());
        if (layer.SimLevel() == nullptr) return;
        CHECK_EQ(saved(3, 18), Scores::kUnplayed);
        const int door = ReachTheDoor(layer, registry, glm::dvec2(590.0, 134.0));
        if (door < 0) return;
        const int medal = earned(layer);
        CHECK_MSG(medal > Scores::kUnplayed && saved(3, 18) == medal,
                  "on the door's tick the file holds " + std::to_string(saved(3, 18)) + ", the play earned " +
                      std::to_string(medal));
        for (int tick = 0; tick < 60; ++tick) tickWith(layer, registry, kRest, {}, {});
        CHECK(layer.Finishing() && layer.MenuScreen() == MagicPortalsLayer::Screen::None);
        press(layer, registry, MagicPortalsLayer::kRetry);
        CHECK_MSG(IsAt(layer, "level18c") && layer.SimLevel() != nullptr && !layer.Finishing(),
                  "R in the beat restarts 4-19");
        CHECK_MSG(saved(3, 18) == medal, "and the medal stays saved: " + std::to_string(saved(3, 18)));
        CHECK_MSG(saved(0, 0) > Scores::kUnplayed, "beside 1-01's");
        std::printf("  4-19: door on tick %d, medal %d in the file on it, kept through R 60 ticks later\n", door, medal);
        layer.OnDetach(registry);
    }
    std::filesystem::remove_all(dir, ec);
}

// 4-19'S KEY SPARKLES SHRINK WITH IT (planning step 141; step 123's deviation 1):
// rocket_landing calls the key's Scale(0.9) every frame from the door's (#185-227),
// and ETHEntity::Scale(float) scales the entity's systems too (ETHEntity.cpp:591-599,
// ETHParticleSystem.cpp:27-40, PARTICLE::Scale). Each frame both of key_2701's
// sparkles systems are 12 x the key's scale, every particle drawn no larger than
// 17 x it (size 12 plus its spread of 5, shrinking from there), and 30 frames on
// none is drawn over two thirds of a unit. Nothing else on the level is scaled.
void TheLandingKeysSparklesShrinkWithIt() {
    if (!OriginalArtIsThere("TheLandingKeysSparklesShrinkWithIt")) return;
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level18c");
    layer.OnAttach(registry);
    CHECK_MSG(layer.SimLevel() != nullptr && layer.ArtError().empty(), layer.LoadError() + layer.ArtError());
    if (layer.SimLevel() == nullptr || !layer.ArtError().empty()) return;
    CloseTheLevelStartPopup(layer, registry);
    const auto keys = [&layer] {
        std::vector<MagicPortalsLayer::EmitterReport> found;
        for (const MagicPortalsLayer::EmitterReport& report : layer.EmitterReports()) {
            if (report.node == "key_2701") found.push_back(report);
        }
        return found;
    };
    // The level's other systems, by size, to see that the landing scales none of them.
    const auto others = [&layer] {
        std::vector<double> sizes;
        for (const MagicPortalsLayer::EmitterReport& report : layer.EmitterReports()) {
            if (report.node != "key_2701") sizes.push_back(report.systemSize);
        }
        return sizes;
    };

    double largestBefore = 0.0;
    for (int f = 0; f < 60; ++f) {
        tickWith(layer, registry, kRest, {}, {});
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
        for (const MagicPortalsLayer::EmitterReport& key : keys()) {
            largestBefore = std::max(largestBefore, key.largestDrawnSize);
        }
    }
    const std::vector<MagicPortalsLayer::EmitterReport> before = keys();
    CHECK_EQ(before.size(), 2u);
    for (const MagicPortalsLayer::EmitterReport& key : before) CHECK(key.systemSize == 12.0);
    CHECK_MSG(largestBefore > 5.0, "the key's sparkles are drawn before the door: " + std::to_string(largestBefore));
    const std::vector<double> othersBefore = others();

    const int door = ReachTheDoor(layer, registry, glm::dvec2(590.0, 134.0));
    if (door < 0) return;
    int wrongSystem = 0;
    int tooLarge = 0;
    double largestAt30 = -1.0;
    int drawnAt30 = 0;
    for (int f = 0; f <= 40; ++f) {
        // The door's tick has run; its frame draws now, then each tick and its frame.
        if (f > 0) tickWith(layer, registry, kRest, {}, {});
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
        const MagicPortalsLayer::CutsceneReport now = layer.CutscenePicture(registry);
        const double scale = now.keyScale;
        if (f == 0) CHECK(now.landing.keyScalings == 1 && std::fabs(scale - 0.9) < 1e-12);
        for (const MagicPortalsLayer::EmitterReport& key : keys()) {
            if (std::fabs(key.systemSize - 12.0 * scale) > 1e-9 * 12.0 * scale) ++wrongSystem;
            if (key.largestDrawnSize > 17.0 * scale * (1.0 + 1e-9)) ++tooLarge;
            if (f == 30) {
                largestAt30 = std::max(largestAt30, key.largestDrawnSize);
                drawnAt30 += key.drawn;
            }
        }
    }
    CHECK_MSG(wrongSystem == 0, std::to_string(wrongSystem) + " frames' systems not at 12 x the key's scale");
    CHECK_MSG(tooLarge == 0, std::to_string(tooLarge) + " frames drew a sparkle over 17 x the key's scale");
    CHECK_MSG(largestAt30 >= 0.0 && largestAt30 < 17.0 * std::pow(0.9, 31.0) * (1.0 + 1e-9) && largestAt30 < 0.67,
              "30 frames after the door the largest drawn is " + std::to_string(largestAt30) + " units (" +
                  std::to_string(drawnAt30) + " drawn)");
    CHECK_MSG(others() == othersBefore, "no other system on the level was scaled");
    std::printf("  4-19: the key's sparkles at most %.3f units before the door, %.4f 30 frames after it (%d drawn)\n",
                largestBefore, largestAt30, drawnAt30);
    layer.OnDetach(registry);
}

// PLANNING STEP 142, the sound pass: the begin-contact callbacks' sounds, each on
// its own gate and at the volume it hands its hook. On 1-05 (level4), whose crate
// lies on a floor: the player put 30 px over its floor and sent down at 400 px/s
// begins it well above playFallSound's 3.5 and is heard at hit / 18
// (ETHBeginContactCallback_dark_mage #82-90); let fall 8 px from rest, it begins it
// under 3.5 and is not; and the level's crate is one the impact watch reads for
// crateContactCallback (#31-56). Each volume is read off the tick's own begins. Put
// up and not down onto the floor: the watch must see the body leave what it stood on
// after a step for its meeting something again to be a begin.
void TheContactsAreHeardAtTheirCallbacksVolumes() {
    using Kind = MagicPortals::Impacts::Kind;
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level4");
    layer.OnAttach(registry);
    CHECK_MSG(layer.SimLevel() != nullptr, layer.LoadError());
    if (layer.SimLevel() == nullptr) return;
    CloseTheLevelStartPopup(layer, registry);
    for (int tick = 0; tick < 60; ++tick) tickWith(layer, registry, kRest, {}, {});
    layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    const MagicPortals::Earthquake::Rules rules = quakeRules();

    struct Drop {
        std::vector<double> hits;         // each begin of the body's, its hitIntensity
        std::vector<std::string> sounds;  // what the tick latched
        std::vector<double> volumes;
    };
    // One throw of `body`: put at `putAt` and given `downPxS` (up, where it is
    // negative), then ticked to the first tick whose begins of the
    // body's include a hitIntensity above `needAbove` in size (any begin, below 0):
    // that tick's begins' hits along their normals, and the sounds it latched.
    const auto drop = [&](entt::entity body, Kind kind, const glm::dvec2& putAt, double downPxS, double needAbove) {
        Drop seen;
        PutBodyAt(registry, body, putAt);
        registry.get<RigidBodyComponent>(body).velocity =
            glm::vec3(0.0f, -MagicPortals::Units::ToMetres(downPxS), 0.0f);
        std::string path;
        bool found = false;
        for (int tick = 0; tick < 90 && !found; ++tick) {
            tickWith(layer, registry, kRest, {}, {});
            path += " " + std::to_string(MagicPortals::Units::ToPixels(registry.get<TransformComponent>(body).position).y);
            std::vector<double> hits;
            for (const auto& begin : layer.ImpactBegins()) {
                if (begin.body == body || begin.other == body) {
                    path += " [begin kind " + std::to_string(static_cast<int>(begin.kind)) +
                            (begin.body == body ? " of it" : " on it") + " on tick " + std::to_string(tick) + "]";
                }
                if (begin.body != body || begin.kind != kind) continue;
                hits.push_back(glm::dot(begin.Approaching(begin.normal), begin.normal) / rules.hitPxPerUnit);
                found = found || std::fabs(hits.back()) > needAbove;
            }
            if (found) {
                seen.hits = hits;
                seen.sounds = layer.LatchedSounds();
                seen.volumes = layer.LatchedVolumes();
            }
            layer.OnUpdate(registry, MagicPortalsLayer::kTick);
        }
        if (!found) std::printf("  1-05: no begin found; the body's y from %.3f:%s\n", putAt.y, path.c_str());
        for (int tick = 0; tick < 30; ++tick) tickWith(layer, registry, kRest, {}, {});
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
        return seen;
    };
    // The volumes a tick latched for `event`, in its order.
    const auto volumesOf = [](const Drop& seen, const char* event) {
        std::vector<double> out;
        for (std::size_t i = 0; i < seen.sounds.size() && i < seen.volumes.size(); ++i) {
            if (seen.sounds[i] == event) out.push_back(seen.volumes[i]);
        }
        return out;
    };
    const auto describeHits = [](const std::vector<double>& hits) {
        std::string text;
        for (double hit : hits) text += " " + std::to_string(hit);
        return text;
    };

    const entt::entity player = layer.SimLevel()->player;
    const Drop hard = drop(player, Kind::Player, playerPx(registry, layer) - glm::dvec2(0.0, 30.0), 400.0, 3.5);
    CHECK_MSG(!hard.hits.empty() && *std::max_element(hard.hits.begin(), hard.hits.end()) > 3.5,
              "the hard landing begins its floor above 3.5:" + describeHits(hard.hits));
    std::vector<double> want;
    for (double hit : hard.hits) {
        if (hit > 3.5) want.push_back(hit / 18.0);
    }
    const std::vector<double> thumps = volumesOf(hard, "player_landed");
    bool same = thumps.size() == want.size();
    for (std::size_t i = 0; same && i < want.size(); ++i) same = std::fabs(thumps[i] - want[i]) < 1e-9;
    CHECK_MSG(same && !want.empty(), "playFallSound at hit / 18 for each begin above 3.5: " +
                                         std::to_string(thumps.size()) + " latched, hits" + describeHits(hard.hits));
    std::printf("  1-05: the player's hard landing, hits%s, thump at %s\n", describeHits(hard.hits).c_str(),
                thumps.empty() ? "none" : std::to_string(thumps[0]).c_str());

    const Drop soft = drop(player, Kind::Player, playerPx(registry, layer) - glm::dvec2(0.0, 8.0), 0.0, -1.0);
    CHECK_MSG(!soft.hits.empty() && *std::max_element(soft.hits.begin(), soft.hits.end()) < 3.5,
              "the soft one begins it under 3.5:" + describeHits(soft.hits));
    CHECK_MSG(volumesOf(soft, "player_landed").empty(), "and is not heard");

    // The crate: level4's one, a body of crateContactCallback's.
    entt::entity crate = entt::null;
    for (const auto& [name, entity] : layer.SimLevel()->built.entities) {
        const std::string entityName = layer.EntityNameOf(entity);
        if (entityName == "crate" || entityName == "crate.ent") crate = entity;
    }
    CHECK_MSG(crate != entt::null && registry.all_of<RigidBodyComponent>(crate), "1-05 places a crate that moves");
    if (crate == entt::null || !registry.all_of<RigidBodyComponent>(crate)) return;
    const std::vector<entt::entity>& watched = layer.WatchedCrates();
    CHECK_MSG(watched.size() == 1 && watched[0] == crate,
              "and the impact watch reads it: " + std::to_string(watched.size()) + " watched");

    // THE CRATE'S FALL (step 142's fix round). Each drop puts the crate at rest over
    // `onto` and lets it fall. The crate's begin with `onto` must come on the tick it
    // reaches it, and the tick's latch must be crateContactCallback's (#17-56):
    // crate_knocked at |hit| / 30 against anything but the character, crate_dragged
    // against the character. The knock's volume is held to what this case saw the
    // crate fall at, not to the begin's own reading: the fastest velocity it carried
    // into a step, straight down onto a flat face, over hit_px_per_unit and 30. Each
    // tick of a drop is printed with the watch's reach, the old and the new, and the
    // gap and normal to `onto`, which is the diagnosis.
    struct CrateDrop {
        int tick = -1;                  // of the crate's begin with `onto`; -1 where none came
        double hit = 0.0;               // that begin's |hitIntensity| along its normal
        glm::dvec2 normal{0.0};
        std::vector<std::string> sounds; // what that tick latched
        std::vector<double> volumes;
        double fastestDownPxS = 0.0;     // the fastest +y velocity the crate carried into a step
        double firstMovePx = -1.0;       // its first step's travel: g dt^2 where it was let go touching nothing
    };
    const double dtS = static_cast<double>(MagicPortalsLayer::kTick);
    const double touchPx = MagicPortals::Earthquake::ToUnits(rules, rules.touchPx);
    const auto* physics = registry.ctx().find<PhysicsSettings>();
    const double gravityPx =
        physics != nullptr ? glm::length(glm::dvec2(physics->gravity.x, physics->gravity.y)) * MagicPortals::Units::kPixelsPerMetre
                           : 0.0;
    // The layer's own world: the original's 10 m/s^2 at the tick's SimRatio squared, 2000 units a second squared
    // (planning step 152) - on the first tick as on every one after (Game::BeforeStep writes it again), and not the
    // Godot project's 980.
    CHECK_MSG(std::fabs(gravityPx - 2000.0) < 1e-3,
              "the layer's world falls at 2000 px/s^2, not " + std::to_string(gravityPx));
    const auto bodyAtPx = [&registry](entt::entity body) {
        return MagicPortals::Units::ToPixels(registry.get<TransformComponent>(body).position);
    };
    const auto masksOf = [&registry](entt::entity body) {
        std::uint32_t layerBits = 0;
        std::uint32_t with = 0;
        if (const auto* box = registry.try_get<BoxColliderComponent>(body)) {
            layerBits = box->layer;
            with = box->collidesWith;
        } else if (const auto* capsule = registry.try_get<CapsuleColliderComponent>(body)) {
            layerBits = capsule->layer;
            with = capsule->collidesWith;
        } else if (const auto* hull = registry.try_get<ConvexHullColliderComponent>(body)) {
            layerBits = hull->layer;
            with = hull->collidesWith;
        }
        return "layer " + std::to_string(layerBits) + " collidesWith " + std::to_string(with);
    };
    const auto crateDrop = [&](const glm::dvec2& putAt, entt::entity onto, const char* what) {
        CrateDrop seen;
        PutBodyAt(registry, crate, putAt);
        char line[240];
        std::string trace;
        for (int tick = 0; tick < 90 && seen.tick < 0; ++tick) {
            const glm::dvec2 before = bodyAtPx(crate);
            const glm::dvec2 velocity = MagicPortals::Units::ToPixels(registry.get<RigidBodyComponent>(crate).velocity);
            seen.fastestDownPxS = std::max(seen.fastestDownPxS, velocity.y);
            tickWith(layer, registry, kRest, {}, {});
            const double moved = glm::length(bodyAtPx(crate) - before);
            if (tick == 0) seen.firstMovePx = moved;
            const double oldReach = glm::length(velocity) * dtS + touchPx;
            MagicPortals::Impacts::Shape a;
            MagicPortals::Impacts::Shape b;
            MagicPortals::Impacts::Gap gap;
            gap.px = std::numeric_limits<double>::quiet_NaN();
            if (MagicPortals::Impacts::ShapeOf(registry, crate, a) && MagicPortals::Impacts::ShapeOf(registry, onto, b)) {
                gap = MagicPortals::Impacts::Between(a, b);
            }
            std::snprintf(line, sizeof line,
                          "\n    %2d: x %.3f y %.3f turned %.3f v %.1f moved %.3f reach %.3f/%.3f gap %.3f n (%.3f, %.3f)",
                          tick, bodyAtPx(crate).x, bodyAtPx(crate).y,
                          static_cast<double>(registry.get<TransformComponent>(crate).rotation.z), velocity.y, moved,
                          oldReach, oldReach + gravityPx * dtS * dtS, gap.px, gap.normal.x, gap.normal.y);
            trace += line;
            for (const auto& begin : layer.ImpactBegins()) {
                if (begin.body != crate || begin.kind != Kind::Crate) continue;
                trace += " [begin on " + layer.EntityNameOf(begin.other) + "]";
                if (begin.other != onto) continue;
                seen.tick = tick;
                seen.normal = begin.normal;
                seen.hit = std::fabs(glm::dot(begin.Approaching(begin.normal), begin.normal) / rules.hitPxPerUnit);
                seen.sounds = layer.LatchedSounds();
                seen.volumes = layer.LatchedVolumes();
            }
            layer.OnUpdate(registry, MagicPortalsLayer::kTick);
        }
        std::printf("  1-05 %s: the crate from %s (crate %s; it %s), per tick: x, y, turned (rad), v in px/s, "
                    "moved, reach old/new, gap and normal to it:%s\n",
                    what, Point(putAt).c_str(), masksOf(crate).c_str(), masksOf(onto).c_str(), trace.c_str());
        for (int tick = 0; tick < 30; ++tick) {
            tickWith(layer, registry, kRest, {}, {});
            layer.OnUpdate(registry, MagicPortalsLayer::kTick);
        }
        return seen;
    };
    const auto describeDrop = [](const CrateDrop& seen) {
        std::string text = "tick " + std::to_string(seen.tick) + ", hit " + std::to_string(seen.hit) + ", normal (" +
                           std::to_string(seen.normal.x) + ", " + std::to_string(seen.normal.y) + "), fell at " +
                           std::to_string(seen.fastestDownPxS) + " px/s; latched";
        for (std::size_t i = 0; i < seen.sounds.size(); ++i) {
            text += " " + seen.sounds[i] + (i < seen.volumes.size() ? "@" + std::to_string(seen.volumes[i]) : "");
        }
        return text;
    };

    // The knocks: onto the open top of platform_ent_658 (x -57.6 to 185.6 at y 126),
    // down to its rest at y 97 - 40 px at x 72, and 25 px at x 36, 11 px under the
    // corner block over x 32 and y 32 (2 px under it, the solver still pushed the
    // crate out of it on its first step). At x 72 the line between the centres leans
    // 10 degrees off the face; at x 36, 32 - which the begin's normal must not take.
    const double releasePx = gravityPx * dtS * dtS;
    const auto platform = layer.SimLevel()->built.entities.find("platform_ent_658");
    CHECK_MSG(platform != layer.SimLevel()->built.entities.end(), "1-05 builds platform_ent_658");
    if (platform == layer.SimLevel()->built.entities.end()) return;
    for (const glm::dvec2 putAt : {glm::dvec2(72.0, 57.0), glm::dvec2(36.0, 72.0)}) {
        const std::string where = "knock at x " + std::to_string(static_cast<int>(putAt.x));
        const CrateDrop knock = crateDrop(putAt, platform->second, where.c_str());
        CHECK_MSG(std::fabs(knock.firstMovePx - releasePx) < 0.01,
                  where + ": let go at rest, touching nothing: its first step " + std::to_string(knock.firstMovePx) + " px");
        CHECK_MSG(knock.tick >= 0, where + ": the crate's begin with the platform, as it reaches it");
        if (knock.tick < 0) continue;
        // The crate is carried at SimRatio times the original's velocity (planning step 152), and the callback reads the
        // original's: what it fell at is the carried speed over the ratio.
        const double fellAt = knock.fastestDownPxS / MagicPortals::ScriptClock::SimRatio(layer.TickStep()) / rules.hitPxPerUnit;
        CHECK_MSG(knock.normal.y > 0.9999 && knock.hit > 2.0 && std::fabs(knock.hit - fellAt) <= 0.01 * fellAt,
                  where + ": along the face's normal, at the speed it fell: " + describeDrop(knock));
        const std::vector<double> knocks = [&] {
            std::vector<double> out;
            for (std::size_t i = 0; i < knock.sounds.size() && i < knock.volumes.size(); ++i) {
                if (knock.sounds[i] == "crate_knocked") out.push_back(knock.volumes[i]);
            }
            return out;
        }();
        const bool dragged = std::find(knock.sounds.begin(), knock.sounds.end(), "crate_dragged") != knock.sounds.end();
        CHECK_MSG(knocks.size() == 1 && !dragged && std::fabs(knocks[0] - fellAt / 30.0) <= 0.01 * fellAt / 30.0 &&
                      std::fabs(knocks[0] - knock.hit / 30.0) < 1e-9,
                  where + ": playRandomWoodSound(|hit| / 30), once, and no drag: " + describeDrop(knock));
        std::printf("  1-05 %s: %s\n", where.c_str(), describeDrop(knock).c_str());
    }

    // The drag: the crate let fall 20 px onto the head of the player, stood on that
    // platform's top at x 72 - the crate clear of the corner block over x 32 and the
    // block over x 112, and under the ceiling at y 0. The crate is parked first where
    // it was made.
    PutBodyAt(registry, crate, glm::dvec2(158.0, 194.0));
    MagicPortals::Impacts::Shape playerShape;
    CHECK_MSG(MagicPortals::Impacts::ShapeOf(registry, player, playerShape), "the player has a solid shape");
    const auto extent = [&registry, player] {
        MagicPortals::Impacts::Shape shape;
        MagicPortals::Impacts::ShapeOf(registry, player, shape);
        double top = std::numeric_limits<double>::infinity();
        double bottom = -std::numeric_limits<double>::infinity();
        for (const glm::dvec2& point : shape.core) {
            top = std::min(top, point.y - shape.radiusPx);
            bottom = std::max(bottom, point.y + shape.radiusPx);
        }
        return glm::dvec2(top, bottom);
    };
    const double feetBelowCentre = extent().y - playerPx(registry, layer).y;
    PutBodyAt(registry, player, glm::dvec2(72.0, 126.0 - feetBelowCentre - 0.5));
    for (int tick = 0; tick < 30; ++tick) {
        tickWith(layer, registry, kRest, {}, {});
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    }
    const double headPx = extent().x;
    const glm::dvec2 over(playerPx(registry, layer).x, headPx - 20.0 - 29.0);
    CHECK_MSG(over.y - 29.0 > 0.5 && std::fabs(over.x - 72.0) < 2.0,
              "the player stands on the platform's top, room over its head: " + Point(playerPx(registry, layer)) +
                  ", head at y " + std::to_string(headPx));
    const CrateDrop drag = crateDrop(over, player, "drag");
    CHECK_MSG(std::fabs(drag.firstMovePx - releasePx) < 0.01,
              "the drag's crate let go at rest, touching nothing: its first step " + std::to_string(drag.firstMovePx) + " px");
    CHECK_MSG(drag.tick >= 0 && drag.hit > 2.0, "the crate's begin with the player, above 2: " + describeDrop(drag));
    const auto count = [](const CrateDrop& seen, const char* event) {
        return std::count(seen.sounds.begin(), seen.sounds.end(), std::string(event));
    };
    CHECK_MSG(count(drag, "crate_dragged") == 1 && count(drag, "crate_knocked") == 0,
              "playWoodDragSound against the character, and no knock: " + describeDrop(drag));
    std::printf("  1-05 drag: %s\n", describeDrop(drag).c_str());
    layer.OnDetach(registry);
}

// PLANNING STEP 142'S SECOND FIX ROUND: a beholder rock that breaks on the level is
// heard. Boss::State::Contacts breaks a rock within its margin of something static,
// or where the step would have taken it, before the step brings the two into touch,
// so the impact watch never saw that begin and the rock's own callback
// (ETHBeginContactCallback_rolling_stone #58-71: startEarthquake(hit x 2) and
// playStoneHitSound(hit / 3) above 2, before destroyOnStaticHit's #170-208) went
// unheard. 1-32 (level31) with the walks of the verifier's probe
// (out/parity/program/P6/verify2/probe_rock): right on ticks 30-110, left on 565-601
// and right on 676-790, so the first rock falls clear of the player to the floor. On
// its break's tick there is one stone begin of it, on the static Contacts broke it
// on, and stone_hit is latched once at hit / 3 - the hit worked out here from the
// velocities the case itself read before each tick, along the line from the rock's
// point to the static's, over hit_px_per_unit - and the begin calls the stone's
// shake at hit x 2, before boss_rock_broken's 5, which is the tick's last word. The
// next rock is one the watch sees reach the floor itself: one begin and one latch
// on its tick, not two.
void ABeholderRockBrokenOnTheLevelIsHeard() {
    using Kind = MagicPortals::Impacts::Kind;
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level31");
    layer.OnAttach(registry);
    CHECK_MSG(layer.SimLevel() != nullptr, layer.LoadError());
    if (layer.SimLevel() == nullptr) return;
    CHECK_MSG(!layer.PopupOpen(), "1-32 opens on no popup, as the probe's run did");
    layer.ScheduleDevHold(30, 110, 1.0f);
    layer.ScheduleDevHold(565, 601, -1.0f);
    layer.ScheduleDevHold(676, 790, 1.0f);
    const MagicPortals::Earthquake::Rules rules = quakeRules();
    // Each rock's velocity and point as each tick began, which is where the watch
    // reads them (the layer's last act of a tick).
    struct Read {
        entt::entity body = entt::null;
        std::string name;
        std::vector<glm::dvec2> velocitiesPx;
        glm::dvec2 atPx{0.0};
    };
    std::vector<Read> reads;
    int breaks = 0;
    int ticks = 0;
    // The beholder's timeline moved with the script clock: the first rock drops on tick 1222 here (1005 in the
    // cases that place the player: this one lets it fall onto the platforms) and the first two static breaks come late and soft, so the heard-above-2 branch
    // below is NOT exercised by this case any more (the soft branch asserts the gate shut instead) - LEFT
    // FOR LATER in planning step 147: a hard break wants the rock placed over the floor, not the timeline.
    for (int i = 0; i < 3000 && breaks < 2 && layer.SimLevel() != nullptr; ++i) {
        for (const MagicPortals::Boss::Rock& rock : layer.SimLevel()->boss.rocks) {
            if (!registry.valid(rock.body)) continue;
            auto read = std::find_if(reads.begin(), reads.end(), [&](const Read& r) { return r.body == rock.body; });
            if (read == reads.end()) {
                reads.push_back(Read{rock.body, rock.name, {}, glm::dvec2(0.0)});
                read = reads.end() - 1;
            }
            read->velocitiesPx.push_back(
                MagicPortals::Units::ToPixels(registry.get<RigidBodyComponent>(rock.body).velocity));
            read->atPx = MagicPortals::Units::ToPixels(registry.get<TransformComponent>(rock.body).position);
        }
        const int brokenBefore = layer.SimLevel()->boss.rocksBroken;
        const QuakeTick seen = quakeTickWith(layer, registry, ticks);
        if (layer.SimLevel() == nullptr) break;
        const PlayedLevel& level = *layer.SimLevel();
        if (level.boss.rocksBroken == brokenBefore) {
            layer.OnUpdate(registry, MagicPortalsLayer::kTick);
            continue;
        }
        const std::vector<std::string> sounds = layer.LatchedSounds();
        const std::vector<double> volumes = layer.LatchedVolumes();
        std::vector<double> stoneHits;
        for (std::size_t s = 0; s < sounds.size() && s < volumes.size(); ++s) {
            if (sounds[s] == "stone_hit") stoneHits.push_back(volumes[s]);
        }
        CHECK_MSG(!level.boss.staticHitsNow.empty(), "the rock broke on something static on tick " +
                                                         std::to_string(layer.LayerTicks()));
        for (const MagicPortals::Boss::StaticHit& hit : level.boss.staticHitsNow) {
            ++breaks;
            const auto read = std::find_if(reads.begin(), reads.end(), [&](const Read& r) { return r.body == hit.rock; });
            const std::string name = read != reads.end() ? read->name : std::string("?");
            const std::string where = "1-32 " + name + " broken on tick " + std::to_string(layer.LayerTicks()) + " on " +
                                      layer.EntityNameOf(hit.other);
            std::vector<const MagicPortals::Impacts::Begin*> begins;
            for (const auto& begin : layer.ImpactBegins()) {
                if (begin.body == hit.rock && begin.kind == Kind::Stone) begins.push_back(&begin);
            }
            CHECK_MSG(registry.valid(hit.other) && !registry.all_of<RigidBodyComponent>(hit.other),
                      where + ": on a static body");
            // ONE BEGIN OF THE ROCK ON EACH BODY IT TOUCHED, AND NONE TWICE: the pair Contacts judged and
            // the pair the watch found are one begin (planning step 142's second fix round). The case
            // asked for exactly one begin of the rock: in the decoded movement's timeline (planning step
            // 148: the player's walk and fall moved, and with them where the beholder's rocks land) a
            // rock breaks on a tick it also meets a second body, so the question is that no pair is
            // counted twice, and that one of the begins is on what it was broken on.
            std::vector<entt::entity> others;
            const MagicPortals::Impacts::Begin* onIt = nullptr;
            for (const MagicPortals::Impacts::Begin* begin : begins) {
                others.push_back(begin->other);
                if (begin->other == hit.other) onIt = begin;
            }
            std::sort(others.begin(), others.end());
            const bool distinct = std::adjacent_find(others.begin(), others.end()) == others.end();
            {
                std::string touched;
                for (const MagicPortals::Impacts::Begin* begin : begins) touched += " " + layer.EntityNameOf(begin->other);
                std::printf("  %s: the rock's stone begins are on:%s\n", where.c_str(), touched.c_str());
            }
            // Since planning step 152 the first rock comes down on the player (the player stands under it, 54 ticks after it
            // drops; the crush is judged on the hardest recent approach and kills him, "player_died" on tick 1300) and breaks on
            // the platform in the same tick: its one begin of that tick is on the player (the entity with no name in the line
            // printed above), and the pair Contacts broke it on gets none of its own (the layer adds one only where the rock
            // has no begin that tick). So the rock must have a begin on each body it touched, none twice; the numbers below
            // are read where one is on what it broke on.
            CHECK_MSG(distinct && !begins.empty(),
                      where + ": a stone begin of it on each body and none twice: " + std::to_string(begins.size()) +
                          " begin(s), " + (distinct ? "distinct" : "a pair twice") +
                          (onIt == nullptr ? ", none on what it broke on" : ""));
            if (!distinct || onIt == nullptr || read == reads.end() || !registry.valid(hit.other)) continue;
            const ImpactRead impact = readImpact(rules, layer, *onIt);
            if (breaks == 1) {
                // The begin is Contacts' own, with no normal, where the watch never saw this one reach what it
                // broke on; or the watch's, a unit normal, where the rock had lain against it since before the
                // break (as it has in this timeline).
                CHECK_MSG(onIt->normal == glm::dvec2(0.0) || std::fabs(glm::length(onIt->normal) - 1.0) < 1e-9,
                          where + ": the begin is Contacts' (no normal) or the watch's (a unit normal): " +
                              Point(onIt->normal));
                const glm::dvec2 otherPx =
                    MagicPortals::Units::ToPixels(registry.get<TransformComponent>(hit.other).position);
                const glm::dvec2 apart = otherPx - read->atPx;
                const glm::dvec2 along = glm::length(apart) > 0.0 ? apart / glm::length(apart) : glm::dvec2(0.0);
                // The velocity it came at is the last one read - as the tick began, before the break -
                // not the fastest it ever had: a rock that lay on something a while before Contacts
                // broke it (the beholder's timeline moved with the script clock, planning step 147:
                // the player rides a platform whose swing is the script's, so the first rock now
                // breaks soft) came at the static as slowly as it lay.
                double fell = 0.0;
                for (const glm::dvec2& velocity : read->velocitiesPx) fell = std::max(fell, velocity.y);
                // (Read off the body, which is carried at SimRatio times the original's velocity: planning step 152.)
                const double want = glm::dot(read->velocitiesPx.back(), along) /
                                    MagicPortals::ScriptClock::SimRatio(layer.TickStep()) / rules.hitPxPerUnit;
                // The begin's hit is the fastest recent approach along its normal (Begin::Approaching), so it lies between the
                // last velocity read along the line to the body and the rock's fastest fall: exactly the last one where the rock
                // came down on the body, more where it lay against it first - and since planning step 153's body (the player
                // 3.9 units shorter, a longer fall to the floor, the rocks' timeline moved) both rocks break on the platform's
                // edge after lying against it, at 0.88 and not the 0.23 of the line to its centre.
                CHECK_MSG(impact.hit + 1e-6 >= want && impact.hit <= fell / MagicPortals::ScriptClock::SimRatio(layer.TickStep()) /
                                                                         rules.hitPxPerUnit + 1e-6,
                          where + ": the begin's hit " + std::to_string(impact.hit) + " between " + std::to_string(want) +
                              " (the last velocity read along the line) and the fastest fall");
                if (impact.hit > 2.0) {
                    // Above 2 the original's is heard.
                    CHECK_MSG(stoneHits.size() == 1 && std::fabs(stoneHits[0] - impact.hit / 3.0) <= 1e-6 * std::fabs(impact.hit),
                              where + ": playStoneHitSound(hit / 3) once: " + std::to_string(stoneHits.size()) +
                                  " latched" + (stoneHits.empty() ? "" : ", the first at " + std::to_string(stoneHits[0])));
                    CHECK_MSG(impact.calls && std::fabs(impact.intensity - 2.0 * impact.hit) <= 1e-6 * std::fabs(impact.hit),
                              where + ": and startEarthquake(hit x 2): " + std::to_string(impact.intensity));
                } else {
                    // At or below it the row's gate is shut: no stone_hit, no startEarthquake.
                    CHECK_MSG(stoneHits.empty() && !impact.calls,
                              where + ": a soft break is neither heard nor shaken: " + std::to_string(stoneHits.size()) +
                                  " stone_hit latched");
                }
                const std::string landed = quakeLanded(seen, 5.0, false);
                CHECK_MSG(landed.empty(), where + ": boss_rock_broken's 5 is the tick's last word: " + landed);
                std::printf("  %s at (%.1f, %.1f): the rock from (%.1f, %.1f), %zu velocities read, fell at %.1f px/s "
                            "(%.4f straight down), %.4f along the line to it; stone_hit at %.6f, the shake %.4f\n",
                            where.c_str(), otherPx.x, otherPx.y, read->atPx.x, read->atPx.y,
                            read->velocitiesPx.size(), fell, fell / rules.hitPxPerUnit, want,
                            stoneHits.empty() ? -1.0 : stoneHits[0], impact.intensity);
            } else {
                // The watch's own begin, and the one latch its gate gives each begin of the tick above 2.
                std::size_t due = 0;
                for (const auto& begin : layer.ImpactBegins()) {
                    if (begin.kind == Kind::Stone && readImpact(rules, layer, begin).hit > 2.0) ++due;
                }
                CHECK_MSG(stoneHits.size() == due, where + ": " + std::to_string(stoneHits.size()) +
                                                       " stone_hit latched on a begin at " +
                                                       std::to_string(impact.hit) + ", not the " +
                                                       std::to_string(due) + " begin(s) of the tick above 2");
                std::printf("  %s: the watch's own begin (on %s), hit %.4f, %zu stone_hit\n", where.c_str(),
                            impact.other.empty() ? "a body" : impact.other.c_str(), impact.hit, stoneHits.size());
            }
        }
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    }
    CHECK_MSG(breaks == 2, "1-32's first two rocks broke on the level: " + std::to_string(breaks));
    layer.OnDetach(registry);
}

// PLANNING STEP 142: a timed crystal's init block plays playCrystalTempAlertSound
// once, as it adds its dial (ETHCallback_crystal #60-82), and the port starts every
// dial on the level's first tick: one latch per timed crystal there, and none after.
// 1-15 (level14).
void ATimedCrystalsAlertIsLatchedOnceAtItsDialsStart() {
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level14");
    layer.OnAttach(registry);
    CHECK_MSG(layer.SimLevel() != nullptr, layer.LoadError());
    if (layer.SimLevel() == nullptr) return;
    int timed = 0;
    for (const auto& crystal : layer.SimLevel()->goals.crystals) {
        if (crystal.timed) ++timed;
    }
    CHECK_MSG(timed >= 1, "1-15 places a timed crystal: " + std::to_string(timed));
    CloseTheLevelStartPopup(layer, registry);
    const auto alerts = [&layer] {
        const std::vector<std::string> sounds = layer.LatchedSounds();
        return static_cast<int>(std::count(sounds.begin(), sounds.end(), std::string("crystal_alert")));
    };
    CHECK_MSG(alerts() == 0, "nothing before the level's first tick");
    tickWith(layer, registry, kRest, {}, {});
    CHECK_MSG(alerts() == timed, "one per timed crystal on the first: " + std::to_string(alerts()));
    for (int tick = 0; tick < 120; ++tick) tickWith(layer, registry, kRest, {}, {});
    CHECK_MSG(alerts() == timed, "and none after: " + std::to_string(alerts()));
    layer.OnDetach(registry);
}

// PLANNING STEP 142: the level's restart is a teleport (GameLayer::GameLayer
// #207-216, Game::Game #74), and the pause's resume, scores and switches are silent
// (GameMenuLayer::GameMenuLayer #74-112; GlobalSoundSwitch::GlobalSoundSwitch #23).
void TheLevelsButtonsSoundAsTheOriginalsDo() {
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level30");
    layer.OnAttach(registry);
    CHECK_MSG(layer.SimLevel() != nullptr, layer.LoadError());
    if (layer.SimLevel() == nullptr) return;
    layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    waitForFirstTap(layer, registry);
    const auto heard = [&layer](const char* event) {
        const std::vector<std::string> sounds = layer.LatchedSounds();
        return static_cast<int>(std::count(sounds.begin(), sounds.end(), std::string(event)));
    };
    Hud::Rect rect;
    CHECK_MSG(layer.ControlRect(MagicPortalsLayer::Control::Reset, rect), "restart is shown");
    if (!layer.ControlRect(MagicPortalsLayer::Control::Reset, rect)) return;
    layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    tap(layer, registry, ScreenOfView(layer, rect.Centre()));
    CHECK_MSG(layer.LevelAgeMs() == 0.0 && heard("level_button") == 1 && heard("menu_button") == 0,
              "a press on restart restarts the level with the teleport: " + std::to_string(heard("level_button")));

    for (int tick = 0; tick < 90; ++tick) tickWith(layer, registry, kRest, {}, {});
    CHECK_MSG(TapThePauseControl(layer, registry) && layer.Paused(), "the pause");
    for (int tick = 0; tick < 60; ++tick) tickWith(layer, registry, kRest, {}, {});
    layer.OnUpdate(registry, MagicPortalsLayer::kTick);
    // 1-31 is achievement 13's: the popup over the pause, silent, closed by the back
    // key, and the pause current again once it has gone (planning step 143).
    if (layer.AchievementsContent() != nullptr) {
        CHECK(layer.PressPause(registry, MagicPortals::Pause::Button::Achievements) && layer.AchievementsPopupOpen());
        press(layer, registry, MagicPortalsLayer::kBack);
        for (int tick = 0; tick < 120 && layer.AchievementsPopupOpen(); ++tick) tickWith(layer, registry, kRest, {}, {});
        CHECK(!layer.AchievementsPopupOpen() && layer.Paused());
    }
    // The music switch first: the sound's toggle dismisses it for a while.
    CHECK(layer.PressPause(registry, MagicPortals::Pause::Button::Music) && !layer.MusicOn());
    CHECK(layer.PressPause(registry, MagicPortals::Pause::Button::Music) && layer.MusicOn());
    CHECK(layer.PressPause(registry, MagicPortals::Pause::Button::Sound) && !layer.SoundOn());
    CHECK(layer.PressPause(registry, MagicPortals::Pause::Button::Sound) && layer.SoundOn());
    CHECK(layer.PressPause(registry, MagicPortals::Pause::Button::Resume));
    CHECK_MSG(layer.LatchedSounds().empty(),
              "scores, both switches and resume are silent: " + std::to_string(layer.LatchedSounds().size()));
    layer.OnDetach(registry);
}

// ---- achievements (planning step 143) ---------------------------------------------

std::vector<ScreenOverlay::Quad> CardFrame(entt::registry& registry, const MagicPortalsLayer& layer) {
    static ScreenOverlay overlay;
    overlay.Clear();
    registry.ctx().insert_or_assign<ScreenOverlay*>(&overlay);
    layer.EmitNotifications(registry);
    return overlay.Quads();
}

std::filesystem::path AchievementsScratch(const char* name) {
    const std::filesystem::path dir = std::filesystem::temp_directory_path() / name;
    std::error_code ec;
    std::filesystem::remove_all(dir, ec);
    std::filesystem::create_directories(dir, ec);
    return dir;
}

std::string ReadText(const std::filesystem::path& path) {
    std::ifstream file(path, std::ios::binary);
    std::ostringstream buffer;
    buffer << file.rdbuf();
    return buffer.str();
}

int Heard(const MagicPortalsLayer& layer, const char* event) {
    const std::vector<std::string> sounds = layer.LatchedSounds();
    return static_cast<int>(std::count(sounds.begin(), sounds.end(), std::string(event)));
}

// 1-01 to its door: LevelFinishedLayer's constructor asks on the door's tick -
// the medal this play earned, its portals, the game's time - and 45 is unlocked
// there and saved with its hash; its card leaves the stack strictly after 2500 ms
// with its stinger and turns the music to 0.15, and goes 3400 ms later with
// setDefaultMusicVolume's 0.7 (the level's track is not g_musicNames[0]).
void TheDoorUnlocksItsAchievementAndRaisesItsCard() {
    const std::filesystem::path dir = AchievementsScratch("supersonic-test-mp-layer-achievements");
    MagicPortalsLayer::Paths paths = TestPaths();
    paths.saveDir = dir.string();
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(paths, "level0");
    layer.OnAttach(registry);
    CHECK_MSG(layer.SimLevel() != nullptr && layer.AchievementRulesError().empty(),
              layer.LoadError() + layer.AchievementRulesError());
    if (layer.SimLevel() == nullptr) return;
    CHECK_MSG(layer.Unlocks().empty(), "a fresh save: the start's pass unlocks nothing");
    for (int tick = 0; tick < 600 && !layer.Finishing(); ++tick) {
        std::vector<std::string> pressed;
        if (tick == 0) pressed.push_back(MagicPortalsLayer::kRight);
        tickWith(layer, registry, kRest, {MagicPortalsLayer::kRight}, std::move(pressed));
    }
    CHECK_MSG(layer.Finishing(), "level0's door is reached by walking right");
    if (!layer.Finishing()) return;
    const int door = layer.LayerTicks();
    const std::optional<MagicPortals::Achievements::Play> play = layer.LastDoorPlay();
    const auto& cleared = layer.LastCleared();
    const int medal = cleared ? MagicPortals::LevelEnd::ComputeScore(cleared->portalsUsed, cleared->goldenScore,
                                                                     cleared->crystals, cleared->crystalsTotal)
                              : -1;
    CHECK_MSG(play && play->world == 0 && play->level == 0 && play->game && play->medal == medal &&
                  play->portals == cleared->portalsUsed,
              "the door asked with this play's numbers");
    if (play) {
        CHECK_MSG(NearD(play->gameTimeMs, layer.LevelAgeMs(), 0.01),
                  "and the game's time, this tick's included: " + std::to_string(play->gameTimeMs) + " against " +
                      std::to_string(layer.LevelAgeMs()));
    }
    CHECK_MSG(layer.Unlocks().size() == 1 && layer.Unlocks()[0].id == 45 && layer.Unlocks()[0].tick == door &&
                  layer.Unlocks()[0].notify,
              "45 on the door's tick, with its card");
    const std::string saved = ReadText(dir / "achievements.json");
    CHECK_MSG(saved.find("\"list\": \"45\"") != std::string::npos && saved.find("\"hash\": \"191\"") != std::string::npos,
              "saved there and then, with its hash: " + saved);
    CHECK_MSG(layer.Notifications().Stacked() == 1 && layer.Notifications().Front() == nullptr,
              "the card waits on the stack");
    const double gameTrack = layer.MusicVolumeNow();
    int shownAt = -1;
    int goneAt = -1;
    double shownVolume = -1.0;
    std::vector<ScreenOverlay::Quad> shownFrame;
    for (int tick = door + 1; tick <= door + 420 && goneAt < 0; ++tick) {
        tickWith(layer, registry, kRest, {}, {});
        if (shownAt < 0 && layer.Notifications().Front() != nullptr) {
            shownAt = tick;
            shownVolume = layer.MusicVolumeNow();
            CHECK_MSG(Heard(layer, "achievement_card") == 1, "the stinger as it leaves the stack");
        }
        if (shownAt > 0 && tick == shownAt + 60) shownFrame = CardFrame(registry, layer);
        if (shownAt > 0 && goneAt < 0 && layer.Notifications().Front() == nullptr) goneAt = tick;
    }
    CHECK_MSG(shownAt - door >= 156 && shownAt - door <= 157,
              "shown strictly past 2500 ms: " + std::to_string(shownAt - door) + " ticks after the door");
    CHECK_MSG(goneAt - shownAt >= 213 && goneAt - shownAt <= 214,
              "gone strictly past 3400 ms: " + std::to_string(goneAt - shownAt));
    CHECK_MSG(NearD(gameTrack, 0.7, 1e-9) && NearD(shownVolume, 0.15, 1e-9) &&
                  NearD(layer.MusicVolumeNow(), 0.7, 1e-9),
              "the music 0.7, 0.15 under the card, 0.7 after it");
    CHECK_EQ(Heard(layer, "achievement_card"), 1);
    if (layer.AchievementsContent() != nullptr && !shownFrame.empty()) {
        CHECK_MSG(CountImage(shownFrame, "nnotificationbg.png") == 3, "the card's three pieces");
        const MagicPortals::Achievements::Entry* entry = layer.AchievementsContent()->Find(45);
        if (entry != nullptr) CHECK_MSG(CountImage(shownFrame, entry->icon) == 1, "and its icon");
    }
    std::printf("  1-01: 45 on the door's tick %d (medal %d, %d portals, %.1f ms); card %d ticks later, gone %d after\n",
                door, medal, play ? play->portals : -1, play ? play->gameTimeMs : -1.0, shownAt - door,
                goneAt - shownAt);
    layer.OnDetach(registry);
    std::error_code ec;
    std::filesystem::remove_all(dir, ec);
}

// 4-19's red key: its pick dispatches 61 with a 5000 ms delay (ETHCallback_key
// #822-851), on the tick its carrier changes, and nothing at its door.
void TheRedKeysPickUnlocksItsAchievement() {
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level18c");
    layer.OnAttach(registry);
    CHECK_MSG(layer.SimLevel() != nullptr, layer.LoadError());
    if (layer.SimLevel() == nullptr) return;
    CloseTheLevelStartPopup(layer, registry);
    int picked = -1;
    for (int tick = 0; tick < 30 && picked < 0; ++tick) {
        PutPlayerAt(registry, layer, glm::dvec2(440.0, 128.0));
        registry.get<RigidBodyComponent>(layer.SimLevel()->player).velocity = glm::vec3(0.0f);
        tickWith(layer, registry, kRest, {}, {});
        for (const MagicPortals::Keys::Key& key : layer.SimLevel()->keys.keys) {
            if (key.owner != entt::null && picked < 0) picked = layer.LayerTicks();
        }
    }
    CHECK_MSG(picked > 0, "the player takes 4-19's key");
    CHECK_MSG(layer.Unlocks().size() == 1 && layer.Unlocks()[0].id == 61 && layer.Unlocks()[0].tick == picked,
              "61 on the pick's tick");
    int shownAt = -1;
    for (int tick = 0; tick < 320 && shownAt < 0; ++tick) {
        tickWith(layer, registry, kRest, {}, {});
        if (layer.Notifications().Front() != nullptr) shownAt = layer.LayerTicks();
    }
    CHECK_MSG(shownAt - picked >= 312 && shownAt - picked <= 313,
              "its card strictly past 5000 ms: " + std::to_string(shownAt - picked) + " ticks");
    std::printf("  4-19: 61 on the pick's tick %d, its card %d ticks later\n", picked, shownAt - picked);
    layer.OnDetach(registry);
}

// The pause's AchievementsPopup over 1-31, which achievement 13 names: up over the
// pause, its text the list's, the pause's buttons taking nothing under it, closed
// by the back key and gone with the pause current again. Over 1-05, named by none,
// the button the owner keeps opens nothing.
void ThePausesAchievementsPopupShowsTheLevels() {
    namespace Pause = MagicPortals::Pause;
    {
        entt::registry registry;
        publishViewport(registry);
        MagicPortalsLayer layer(TestPaths(), "level4");
        layer.OnAttach(registry);
        if (layer.SimLevel() == nullptr) return;
        CloseTheLevelStartPopup(layer, registry);
        press(layer, registry, MagicPortalsLayer::kBack);
        for (int tick = 0; tick < 60; ++tick) tickWith(layer, registry, kRest, {}, {});
        CHECK(layer.Paused());
        CHECK_MSG(!layer.PressPause(registry, Pause::Button::Achievements) && !layer.AchievementsPopupOpen(),
                  "1-05: no achievement names it, nothing opens");
        layer.OnDetach(registry);
    }
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level30");
    layer.OnAttach(registry);
    CHECK_MSG(layer.SimLevel() != nullptr, layer.LoadError());
    if (layer.SimLevel() == nullptr) return;
    CloseTheLevelStartPopup(layer, registry);
    press(layer, registry, MagicPortalsLayer::kBack);
    for (int tick = 0; tick < 60; ++tick) tickWith(layer, registry, kRest, {}, {});
    if (layer.AchievementsContent() == nullptr) {
        std::printf("  (the popup's part skipped: no list of the original's)\n");
        layer.OnDetach(registry);
        return;
    }
    CHECK(layer.PressPause(registry, Pause::Button::Achievements) && layer.AchievementsPopupOpen());
    const MagicPortals::Achievements::Entry* entry = layer.AchievementsContent()->Find(13);
    const std::string text = layer.AchievementsPopupText();
    CHECK_MSG(entry != nullptr && text == "# " + entry->title + ":\n" + entry->description,
              "1-31's one achievement, locked: '" + text + "'");
    CHECK_MSG(Heard(layer, "menu_button") == 0 && Heard(layer, "level_button") == 0, "silent");
    for (int tick = 0; tick < 60; ++tick) tickWith(layer, registry, kRest, {}, {});
    CHECK_MSG(!layer.PressPause(registry, Pause::Button::Music) && layer.MusicOn(),
              "the pause's buttons take nothing under it");
    if (OriginalArtIsThere("ThePausesAchievementsPopupShowsTheLevels")) {
        const std::vector<ScreenOverlay::Quad> frame = HudFrame(registry, layer);
        CHECK_MSG(CountImage(frame, "box_bg.png") == 9, "the frame's nine tiles");
        CHECK_MSG(CountImage(frame, "popup_close_button.png") == 1, "and its close button");
    }
    press(layer, registry, MagicPortalsLayer::kBack);
    CHECK(layer.AchievementsPopupOpen() && layer.Paused());
    int goneAfter = -1;
    for (int tick = 1; tick <= 120 && goneAfter < 0; ++tick) {
        tickWith(layer, registry, kRest, {}, {});
        if (!layer.AchievementsPopupOpen()) goneAfter = tick;
    }
    CHECK_MSG(goneAfter > 0 && layer.Paused(), "gone, the pause current again");
    CHECK(layer.PressPause(registry, Pause::Button::Resume) && !layer.Paused());
    std::printf("  1-31: the popup up over the pause, gone %d ticks after the back key\n", goneAfter);
    layer.OnDetach(registry);
}

// The main menu's pass (checkPreviouslyUnlockAchievements) over a save whose first
// chapter is all gold: its three badges and its eight medal achievements, silently,
// in the function's order, saved - and the dashboard reads the saved set: the same
// rows and points the medals gave it before.
void TheMainMenusPassFillsTheSavedSet() {
    namespace Scores = MagicPortals::Scores;
    using Screen = MagicPortalsLayer::Screen;
    const std::filesystem::path dir = AchievementsScratch("supersonic-test-mp-layer-menu-pass");
    {
        Scores::Store seed;
        std::string why;
        CHECK(seed.Open(dir.string(), why));
        for (int level = 0; level < 32; ++level) seed.Record(0, level, Scores::kGold);
        CHECK_MSG(seed.Save(why), why);
    }
    MagicPortalsLayer::Paths paths = TestPaths();
    paths.saveDir = dir.string();
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(paths, "");
    layer.OnAttach(registry);
    if (!layer.LoadError().empty() || !TickToTheMainMenu(layer, registry)) {
        CHECK_MSG(false, "no main menu: " + layer.LoadError());
        return;
    }
    std::string order;
    bool silent = true;
    for (const MagicPortalsLayer::Unlock& unlock : layer.Unlocks()) {
        order += (order.empty() ? "" : ",") + std::to_string(unlock.id);
        silent = silent && !unlock.notify;
    }
    CHECK_MSG(order == "0,3,37,45,6,7,8,9,46,47,14" && silent,
              "the badges, then the levels in order, silently: " + order);
    const std::string saved = ReadText(dir / "achievements.json");
    CHECK_MSG(saved.find("\"list\": \"0,3,37,45,6,7,8,9,46,47,14\"") != std::string::npos &&
                  saved.find("\"hash\": \"5192\"") != std::string::npos,
              "saved with its hash: " + saved);
    CHECK_MSG(layer.Notifications().Stacked() == 0, "no card");
    const auto touchAt = [&](double xPx, double yPx) {
        const glm::vec2 at(static_cast<float>(xPx), static_cast<float>(yPx));
        tickWith(layer, registry, at, {MagicPortalsLayer::kTap}, {MagicPortalsLayer::kTap});
        releaseWith(layer, registry, at);
    };
    for (int tick = 0; tick < 60; ++tick) tickWith(layer, registry, kRest, {}, {});
    touchAt(1100.0, 675.0);
    tickWith(layer, registry, kRest, {}, {});
    CHECK_MSG(layer.MenuScreen() == Screen::Achievements, "the dashboard");
    if (layer.MenuScreen() != Screen::Achievements) return;
    if (layer.AchievementsContent() != nullptr) {
        Scores::Store medals;
        std::string why;
        CHECK(medals.Open(dir.string(), why));
        const MagicPortals::Dashboard::Board before = MagicPortals::Dashboard::Build(
            layer.AchievementsContent(), layer.LockingRules(), medals, layer.ChapterTable());
        const MagicPortals::Dashboard::Board& now = layer.DashboardBoard();
        bool same = before.lines.size() == now.lines.size() && before.points == now.points;
        for (std::size_t i = 0; same && i < now.lines.size(); ++i) same = before.lines[i].unlocked == now.lines[i].unlocked;
        CHECK_MSG(same, "the saved set unlocks the rows the medals did, " + std::to_string(now.points) + " points");
    }
    layer.OnDetach(registry);
    std::error_code ec;
    std::filesystem::remove_all(dir, ec);
}

// On a fresh save 1-02 is locked, and its row's tap raises "This level is locked!"
// at once (displayLevelLockedNotification: delay 0, no icon, no sound of its own).
void TheDashboardsLockedRowRaisesItsCard() {
    using Screen = MagicPortalsLayer::Screen;
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "");
    layer.OnAttach(registry);
    if (!layer.LoadError().empty() || !TickToTheMainMenu(layer, registry)) {
        CHECK_MSG(false, "no main menu: " + layer.LoadError());
        return;
    }
    if (layer.AchievementsContent() == nullptr) {
        std::printf("  (skipped: no list of the original's)\n");
        layer.OnDetach(registry);
        return;
    }
    const auto touchAt = [&](double xPx, double yPx) {
        const glm::vec2 at(static_cast<float>(xPx), static_cast<float>(yPx));
        tickWith(layer, registry, at, {MagicPortalsLayer::kTap}, {MagicPortalsLayer::kTap});
        releaseWith(layer, registry, at);
    };
    for (int tick = 0; tick < 60; ++tick) tickWith(layer, registry, kRest, {}, {});
    touchAt(1100.0, 675.0);
    tickWith(layer, registry, kRest, {}, {});
    CHECK_MSG(layer.MenuScreen() == Screen::Achievements, "the dashboard");
    if (layer.MenuScreen() != Screen::Achievements) return;
    const MagicPortals::Dashboard::Board& board = layer.DashboardBoard();
    int locked = -1;
    for (std::size_t i = 0; i < board.lines.size() && locked < 0; ++i) {
        const auto& line = board.lines[i];
        if (!line.header && line.level >= 0 && !line.levelUnlocked) locked = static_cast<int>(i);
    }
    const glm::dvec2 view = layer.MenuBoxPx();
    CHECK_MSG(locked >= 0 && MagicPortals::Dashboard::LineShown(layer.DashboardRules(), view, locked, 0.0),
              "a locked level's row on the view: " + std::to_string(locked));
    if (locked < 0) return;
    for (int tick = 0; tick < 60; ++tick) tickWith(layer, registry, kRest, {}, {});
    const Hud::Rect rect = MagicPortals::Dashboard::LineHitRect(layer.DashboardRules(), view, locked, 0.0);
    const glm::dvec2 px = rect.Centre() / view * glm::dvec2(1280.0, 720.0);
    touchAt(px.x, px.y);
    tickWith(layer, registry, kRest, {}, {});
    const MagicPortals::Notificator::Card* card = layer.Notifications().Front();
    CHECK_MSG(card != nullptr && card->message == "This level is locked!" && card->icon.empty() && card->sound.empty() &&
                  card->durationMs == 1500.0,
              "This level is locked!, at once, for 1500 ms, no icon and no sound of its own");
    CHECK_MSG(Heard(layer, "achievement_denied") == 1 && Heard(layer, "achievement_card") == 0,
              "the denial heard, and nothing else");
    if (OriginalArtIsThere("TheDashboardsLockedRowRaisesItsCard")) {
        for (int tick = 0; tick < 45; ++tick) tickWith(layer, registry, kRest, {}, {});
        const std::vector<ScreenOverlay::Quad> frame = CardFrame(registry, layer);
        CHECK_MSG(CountImage(frame, "nnotificationbg.png") == 3, "its three pieces over the dashboard");
    }
    std::printf("  the dashboard's row %d, its level locked: the card at once\n", locked);
    layer.OnDetach(registry);
}

// ---- The smaller pictures (the program's UI, planning step 146) -------------------
//
// effects.json _bosses_flames_hands and art.json's carried_diamond, unlit_torch and
// shock_ring agent_pulse. The ghost's and the dark dragon's are in their own cases
// above; these are the rest.

// 1-32: the beholder's DEAD arm calls overTimeEntityAdder on every update - one
// small_explosion_no_light every 400 ms, 0.4 to 1.1 of 48 off it, on the same ticks
// as the sound's boss_explosion - and its end explodes it at 2 where it stands.
void TheBeholdersDeathScattersAndExplodes() {
    if (!OriginalArtIsThere("TheBeholdersDeathScattersAndExplodes")) return;
    using MagicPortals::Boss::Phase;
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level31");
    layer.OnAttach(registry);
    CHECK_MSG(layer.SimLevel() != nullptr && layer.ArtError().empty(), layer.LoadError() + layer.ArtError());
    if (layer.SimLevel() == nullptr || !layer.ArtError().empty() || !layer.SimLevel()->boss.beholder.has_value()) {
        return;
    }
    CloseTheLevelStartPopup(layer, registry);
    const MagicPortals::Game::Level& level = *layer.SimLevel();
    const MagicPortals::Boss::Beholder& beholder = *level.boss.beholder;
    std::vector<AddedEffect> added;
    std::vector<int> heard;
    int seen = layer.EffectsSpawned();
    int tick = 0;
    int deadAt = -1;
    int goneAt = -1;
    const auto step = [&]() {
        tickWith(layer, registry, kRest, {}, {});
        ++tick;
        for (const std::string& event : layer.LatchedSounds()) {
            if (event == "boss_explosion") heard.push_back(tick);
        }
        if (deadAt < 0 && beholder.phase == Phase::Dead) deadAt = tick;
        if (goneAt < 0 && beholder.gone) goneAt = tick;
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
        CollectAdded(layer, seen, tick, added);
    };
    // Three rocks rising into it, as TheBeholdersDeathStopsItsTrack puts them.
    int thrown = 0;
    for (int n = 0; n < 12000 && beholder.phase != Phase::Dead; ++n) {
        step();
        if (beholder.rocksThrown > thrown && !level.boss.rocks.empty()) {
            thrown = beholder.rocksThrown;
            const entt::entity rock = level.boss.rocks.back().body;
            if (!registry.valid(rock)) continue;
            const glm::vec3 inside = MagicPortals::Units::ToWorld(beholder.atPx.x, beholder.atPx.y + 10.0);
            auto& at = registry.get<TransformComponent>(rock);
            at.position = glm::vec3(inside.x, inside.y, at.position.z);
            registry.get<RigidBodyComponent>(rock).velocity =
                glm::vec3(0.0f, MagicPortals::Units::ToMetres(200.0), 0.0f);
        }
    }
    CHECK_MSG(beholder.phase == Phase::Dead, "three rocks killed it");
    if (beholder.phase != Phase::Dead) return;
    for (int n = 0; n < 400 && !beholder.gone; ++n) step();
    for (int n = 0; n < 5; ++n) step();
    CHECK_MSG(deadAt > 0 && goneAt > deadAt, "dead on tick " + std::to_string(deadAt) + ", gone on " +
                                                 std::to_string(goneAt));
    // THE SCATTER: one every 25th update of its DEAD arm (400 ms of 16; the 24th at 16.667), from the
    // tick it died to the tick it went, both run; each on the tick the sound's own clock plays.
    const std::vector<AddedEffect> scatter = AddedNamed(added, "small_explosion_no_light.ent");
    const int updates = goneAt - deadAt + 1;
    std::vector<int> want;
    for (int n = 25; n <= updates; n += 25) want.push_back(deadAt + n - 1);
    std::vector<int> got;
    int wrong = 0;
    for (const AddedEffect& one : scatter) {
        got.push_back(one.tick);
        const double d = glm::distance(one.report.atPx, beholder.atPx);
        if (!(d >= 19.2 - 1e-3 && d <= 52.8 + 1e-3) || one.report.zUnits != 0.0 || one.report.scriptScale != 1.0 ||
            one.report.angleDeg != 0.0 || one.report.drawn || !one.report.temporary) {
            ++wrong;
        }
    }
    CHECK_MSG(!want.empty() && got == want, "every 25th update of DEAD: " + std::to_string(got.size()) + " of " +
                                                std::to_string(want.size()) + ", the first on " +
                                                std::to_string(got.empty() ? -1 : got[0]));
    CHECK_MSG(got == heard, "on the ticks the sound's boss_explosion plays: " + std::to_string(heard.size()));
    CHECK_MSG(wrong == 0, "19.2 to 52.8 off it, at a bare 0, at x1, unturned, no picture: " +
                              std::to_string(wrong) + " off");
    // THE END: explosion_large at 2, where it stood, 32 in front, on the tick it goes.
    const std::vector<AddedEffect> bursts = AddedNamed(added, "explosion_large.ent");
    CHECK_MSG(bursts.size() == 1, "one explosion_large: " + std::to_string(bursts.size()));
    if (bursts.size() == 1) {
        CHECK_MSG(bursts[0].tick == goneAt && glm::distance(bursts[0].report.atPx, beholder.atPx) < 1e-9 &&
                      NearD(bursts[0].report.zUnits, 32.0, 1e-12) && bursts[0].report.scriptScale == 2.0,
                  "explode(currentPos, 2f) on the tick it goes: tick " + std::to_string(bursts[0].tick) + " at " +
                      Point(bursts[0].report.atPx) + " x " + std::to_string(bursts[0].report.scriptScale));
    }
    std::printf("  1-32: dead on tick %d, gone on %d: %zu scattered explosions, the last burst at x2\n", deadAt,
                goneAt, scatter.size());
    layer.OnDetach(registry);
}

// addFlames on a character fire kills - a fire agent's flame (2-10, footage F13's
// fire death) and a fireball (2-32's dragon, which kills the idle player on tick
// 286): fire32.ent on its point and depth at 40 / 64, before its blood, riding its
// body after the picture is hidden.
void ADeathByFireLeavesFlamesOnTheCharacter() {
    if (!OriginalArtIsThere("ADeathByFireLeavesFlamesOnTheCharacter")) return;
    for (const char* name : {"level9a", "level31a"}) {
        const bool flame = std::string(name) == "level9a";
        entt::registry registry;
        publishViewport(registry);
        MagicPortalsLayer layer(TestPaths(), name);
        layer.OnAttach(registry);
        CHECK_MSG(layer.SimLevel() != nullptr && layer.ArtError().empty(), layer.LoadError() + layer.ArtError());
        if (layer.SimLevel() == nullptr || !layer.ArtError().empty()) continue;
        CloseTheLevelStartPopup(layer, registry);
        const MagicPortals::Game::Level& level = *layer.SimLevel();
        std::vector<AddedEffect> added;
        int seen = layer.EffectsSpawned();
        int tick = 0;
        glm::dvec2 diedAtPx(0.0);
        for (int n = 0; n < 600 && !layer.Dying(); ++n) {
            if (flame && !level.fire.agents.empty()) PutBodyAt(registry, level.player, level.fire.agents.front().atPx);
            tickWith(layer, registry, kRest, {}, {});
            ++tick;
            if (layer.Dying()) diedAtPx = playerPx(registry, layer);
            layer.OnUpdate(registry, MagicPortalsLayer::kTick);
            CollectAdded(layer, seen, tick, added);
        }
        const bool byFire = flame ? level.fire.playerKilled : level.turrets.playerKilled;
        CHECK_MSG(layer.Dying() && byFire,
                  std::string(name) + ": killed by " + (flame ? "the flame" : "a fireball") + ": " +
                      level.hazards.killedBy);
        if (!layer.Dying()) continue;
        const std::vector<AddedEffect> flames = AddedNamed(added, "fire32.ent");
        const std::vector<AddedEffect> blood = AddedNamed(added, "blood.ent");
        CHECK_MSG(flames.size() == 1 && blood.size() == 1, std::string(name) + ": fire32 and blood, once each: " +
                                                               std::to_string(flames.size()) + ", " +
                                                               std::to_string(blood.size()));
        if (flames.size() != 1 || blood.size() != 1) continue;
        const MagicPortalsLayer::EffectReport& fire = flames[0].report;
        CHECK_MSG(fire.id < blood[0].report.id && flames[0].tick == blood[0].tick,
                  std::string(name) + ": addFlames before checkGameLost's blood, on the death's tick");
        CHECK_MSG(glm::distance(fire.atPx, diedAtPx) < 1e-6 && NearD(fire.zUnits, layer.PlayerDepth(), 1e-12) &&
                      fire.scriptScale == 0.625 && fire.angleDeg == 0.0 &&
                      fire.followKind == MagicPortalsLayer::EffectOwner::Kind::Character && !fire.hidden &&
                      fire.temporary && !fire.drawn && fire.systems == 1,
                  std::string(name) + ": on the character's point and depth at 40 / 64, riding its body, shown: " +
                      Point(fire.atPx) + " x " + std::to_string(fire.scriptScale));
        // ETHCallback_fire32: SetPositionXY(its target's) every frame, the hidden body too.
        const glm::dvec2 moved = diedAtPx + glm::dvec2(30.0, -20.0);
        PutBodyAt(registry, level.player, moved);
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
        const MagicPortalsLayer::EffectReport after = ByIdIn(layer.EffectReports(), fire.id);
        CHECK_MSG(after.id == fire.id && glm::distance(after.atPx, moved) < 1e-3,
                  std::string(name) + ": and it follows the body: " + Point(after.atPx));
        std::printf("  %s: burned by %s on tick %d: fire32 at %s x %.3f, then blood\n", name,
                    level.hazards.killedBy.c_str(), flames[0].tick, Point(fire.atPx).c_str(), fire.scriptScale);
        layer.OnDetach(registry);
    }
}

// 4-28: a minion a fire agent's flame burns destroys itself on the next tick, and its
// own callback adds addFlames' fire32.ent at its point - its frame's width over 64 -
// before its blood, both left where it went (planning step 146).
void ABurnedMinionLeavesItsFlamesBeforeItsBlood() {
    if (!OriginalArtIsThere("ABurnedMinionLeavesItsFlamesBeforeItsBlood")) return;
    entt::registry registry;
    publishViewport(registry);
    MagicPortalsLayer layer(TestPaths(), "level27c");
    layer.OnAttach(registry);
    CHECK_MSG(layer.SimLevel() != nullptr && layer.ArtError().empty(), layer.LoadError() + layer.ArtError());
    if (layer.SimLevel() == nullptr || !layer.ArtError().empty()) return;
    CloseTheLevelStartPopup(layer, registry);
    const MagicPortals::Game::Level& level = *layer.SimLevel();
    if (level.minions.minions.empty() || level.fire.agents.empty()) {
        CHECK_MSG(false, "4-28 places a knight and a fire agent");
        return;
    }
    const std::vector<MagicPortalsLayer::MinionReport> before = layer.MinionReports();
    const double frameWidth = before.empty() ? 0.0 : before.front().sizePx.x;
    const double lookZ = before.empty() ? 0.0 : before.front().lookZ;
    const MagicPortals::Minions::Minion& knight = level.minions.minions.front();
    std::vector<AddedEffect> added;
    int seen = layer.EffectsSpawned();
    int tick = 0;
    for (int n = 0; n < 10 && !knight.gone; ++n) {
        if (knight.body != entt::null && registry.valid(knight.body)) {
            PutBodyAt(registry, knight.body, level.fire.agents.front().atPx);
        }
        tickWith(layer, registry, kRest, {}, {});
        ++tick;
        layer.OnUpdate(registry, MagicPortalsLayer::kTick);
        CollectAdded(layer, seen, tick, added);
    }
    CHECK_MSG(knight.gone && level.minions.burned == 1, "the flame burned the knight");
    const std::vector<AddedEffect> flames = AddedNamed(added, "fire32.ent");
    const std::vector<AddedEffect> blood = AddedNamed(added, "blood.ent");
    CHECK_MSG(flames.size() == 1 && blood.size() == 1, "fire32 and blood, once each: " +
                                                           std::to_string(flames.size()) + ", " +
                                                           std::to_string(blood.size()));
    if (flames.size() != 1 || blood.size() != 1) return;
    const MagicPortalsLayer::EffectReport& fire = flames[0].report;
    CHECK_MSG(fire.id < blood[0].report.id && flames[0].tick == blood[0].tick,
              "addFlames (#1471) before its blood (#1490), on one tick");
    CHECK_MSG(glm::distance(fire.atPx, blood[0].report.atPx) < 1e-9 && NearD(fire.zUnits, lookZ, 1e-12) &&
                  NearD(fire.scriptScale, frameWidth / 64.0, 1e-12) &&
                  fire.followKind == MagicPortalsLayer::EffectOwner::Kind::None,
              "at its point and depth, its " + std::to_string(frameWidth) + "-unit frame over 64, left there: " +
                  Point(fire.atPx) + " x " + std::to_string(fire.scriptScale));
    std::printf("  4-28: the knight burned: fire32 at %s x %.4f, then blood\n", Point(fire.atPx).c_str(),
                fire.scriptScale);
    layer.OnDetach(registry);
}

